import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { llmScreenKind } from "../ui/kind";
import { llmScreenExecutor } from "./executor";

/**
 * The kind with its TypeScript executor attached — for hosts that EXECUTE on TS.
 *
 * The surface in `ui/kind.ts` deliberately carries no executor: the editor is
 * React on every host, so a PHP project vendors `ui/` and never `js/`. When the
 * two were one file the import dangled on exactly those hosts and the editor
 * build failed — a break that only appeared off the runtime that authored it.
 */
export const llmScreenRunnableKind: NodeKindDefinition = {
  ...llmScreenKind,
  executor: llmScreenExecutor,
};

import type { ScreenSchema } from "./types";

/**
 * Check a generated screen before anything renders it.
 *
 * fancy-screens renders an unknown component name as a visible orange
 * placeholder — good behaviour for a developer typing a schema by hand, and the
 * wrong outcome for a workflow: the run completes, reports success, and what
 * reaches the person is an error message where their interface should be. So a
 * schema naming a component the host never registered is rejected HERE, while
 * there is still a run to fail.
 *
 * Returns every problem rather than the first. An author fixing a prompt wants
 * the whole list, and a generated tree usually gets several wrong at once.
 */
export function checkSchema(schema: unknown, components: string[], maxDepth = 12): string[] {
  const known = new Set(components);
  const problems: string[] = [];
  const unknown = new Set<string>();

  const walk = (node: unknown, path: string, depth: number): void => {
    if (typeof node === "string") return;

    if (typeof node !== "object" || node === null || Array.isArray(node)) {
      problems.push(`${path}: expected a component object or a string, got ${describe(node)}`);
      return;
    }

    if (depth > maxDepth) {
      // A model that loses its place emits a tree that nests until something
      // downstream blows its stack. Naming the depth beats a RangeError.
      problems.push(`${path}: nested deeper than ${maxDepth} levels`);
      return;
    }

    const element = node as Partial<ScreenSchema>;

    if (typeof element.type !== "string" || element.type.trim() === "") {
      problems.push(`${path}: no component type`);
    } else if (!known.has(element.type) && !unknown.has(element.type)) {
      // Reported once per name, not once per occurrence: a model that gets a
      // name wrong usually uses it a dozen times, and a dozen identical lines
      // buries the other problems.
      unknown.add(element.type);
      problems.push(`${path}: unknown component "${element.type}"`);
    }

    if (element.props !== undefined && (typeof element.props !== "object" || element.props === null || Array.isArray(element.props))) {
      problems.push(`${path}: props must be an object`);
    }

    if (element.children === undefined) return;

    if (!Array.isArray(element.children)) {
      problems.push(`${path}: children must be an array`);
      return;
    }

    element.children.forEach((child, index) => walk(child, `${path}.children[${index}]`, depth + 1));
  };

  walk(schema, "screen", 0);

  if (unknown.size > 0) {
    // The actionable half of an unknown-component error: the model was told
    // what exists, so the fix is usually the registry, not the prompt.
    problems.push(
      `registered components are: ${components.length > 0 ? components.join(", ") : "(none — the host registered nothing)"}`,
    );
  }

  return problems;
}

function describe(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "an array";

  return typeof value;
}

/**
 * A generated interface, as JSON.
 *
 * Structurally the `ScreenSchema` fancy-screens already renders — `<Screen
 * schema={…}>` maps `type` through its component registry, spreads `props`, and
 * recurses `children`. Restated here as a local type rather than imported so
 * the executor carries no runtime import of a React package: a queue worker
 * generating a screen should not have to install a renderer to do it.
 *
 * The shape is unchanged on purpose. A parallel format would mean the node
 * emits something `<Screen>` cannot take, and the whole point is that it can.
 */
export type ScreenSchema = {
  /** A component name the host registered with `registerSchemaComponent`. */
  type: string;
  props?: Record<string, unknown>;
  children?: Array<ScreenSchema | string>;
};

export type LlmScreenRequest = {
  /** What the interface is for, in the author's words. */
  purpose: string;
  /**
   * Component names the model may use.
   *
   * Supplied by the host, because only the host knows what it registered.
   * A model left to guess emits `<DataTable>` into an app that registered
   * `Table`, and fancy-screens renders an orange placeholder where the
   * interface should be.
   */
  components: string[];
  /** The run's data, for the model to build the interface around. */
  context?: unknown;
  provider?: string;
  model?: string;
  /** Host-resolved credential reference, never a raw key. */
  credential?: string;
};

export type LlmScreenResult = {
  schema: ScreenSchema;
  title?: string;
};

/**
 * The seam between this node and the screen surface.
 *
 * Two jobs, deliberately on one host: generating the schema and knowing which
 * components exist are the same knowledge. Split across two registrations they
 * drift, and the drift shows up as a rendered placeholder — a run that reports
 * success having produced an error message on screen.
 *
 * ```ts
 * registerLlmScreenHost({
 *   components: () => listSchemaComponents(),          // from fancy-screens
 *   generate: (req) => myModel.json(SCREEN_SCHEMA, req),
 *   present: (screen) => screenStore.setState({ schema: screen.schema }),
 * });
 * ```
 */
export type LlmScreenHost = {
  /** Component names registered on this host's fancy-screens registry. */
  components: () => string[];
  generate: (request: LlmScreenRequest) => Promise<LlmScreenResult> | LlmScreenResult;
  /**
   * Put the generated screen in front of someone.
   *
   * Optional: a workflow may only want the schema as data — to store it, diff
   * it, or hand it to a later step — and forcing a presentation step would make
   * that impossible.
   */
  present?: (screen: { screenId: string; title?: string; schema: ScreenSchema }) => void | Promise<void>;
};

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";

import { callConnector } from "../../_connector/js/client";
import { idempotencyKeyFor } from "../../_connector/js/idempotency";
import { RESEND } from "../../_resend/js/service";

/** Send an email through Resend. */
export const resendEmailSendExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;

  const from = String(config.from ?? "").trim();
  const to = recipients(config.to);

  if (from === "") {
    throw new Error('resend_email_send: needs a "from" address on a domain verified with Resend.');
  }
  if (to.length === 0) {
    throw new Error('resend_email_send: needs at least one "to" address.');
  }
  if (!config.html && !config.text) {
    // Resend rejects this too, but three frames later and in its own words. A
    // node that knows its own requirement should say so before the round trip.
    throw new Error('resend_email_send: needs an "html" or "text" body — an empty email is never intended.');
  }

  const key = idempotencyKeyFor(ctx, ctx.node.id);

  const result = await callConnector(RESEND, {
    operation: "email_send",
    config,
    input: ctx.inputs?.in,
    request: {
      method: "POST",
      path: "/emails",
      json: {
        from,
        to,
        subject: String(config.subject ?? ""),
        ...(config.html ? { html: String(config.html) } : {}),
        ...(config.text ? { text: String(config.text) } : {}),
        ...(config.replyTo ? { reply_to: String(config.replyTo) } : {}),
      },
    },
    ...(key === null ? {} : { idempotencyKey: key }),
  });

  ctx.emit({
    type: "log",
    level: "info",
    nodeId: ctx.node.id,
    message: `resend email ${(result.data as any)?.id} to ${to.join(", ")} (${result.mode})`,
  });

  return { __port: "out", value: result };
};

/** One address, a comma-separated list, or an array — all end up a list. */
function recipients(value: unknown): string[] {
  if (Array.isArray(value)) return value.map(String).map((item) => item.trim()).filter(Boolean);
  if (typeof value !== "string") return [];

  return value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { resendEmailSendKind } from "../ui/kind";
import { resendEmailSendExecutor } from "./executor";

/** The kind with its TypeScript executor attached — for hosts that EXECUTE on TS. */
export const resendEmailSendRunnableKind: NodeKindDefinition = {
  ...resendEmailSendKind,
  executor: resendEmailSendExecutor,
};

/**
 * The authoring surface every connector node shares.
 *
 * ## The model, and where it came from
 *
 * IFTTT's authoring UX is the one non-engineers actually complete, and three of
 * its four ideas map onto fancy-flow without distortion:
 *
 * 1. **Service first, then capability.** You pick Stripe, *then* pick what about
 *    Stripe. Not a flat wall of four hundred nodes. Here that lives in the
 *    registry — `connector.service` groups a provider's nodes, and the listing
 *    tools narrow in two steps.
 * 2. **The connection is a thing, not a field.** You authorize a service once
 *    and every applet reuses it. Here: `connection.ts` in the runtime, and the
 *    single `connection` config field below.
 * 3. **Ingredients.** A trigger's output fields become named tokens you drop
 *    into a downstream action's fields. fancy-flow already has the machinery —
 *    `outputShape` on the kind, `availableVariables()` reading it off direct
 *    predecessors — so a connector's job is simply to DECLARE its shape. See
 *    `ingredients.ts`.
 * 4. **A sentence, not a form dump.** `summarize()` below.
 *
 * ## Where it does NOT map, and what we did instead
 *
 * An IFTTT applet is one trigger and one action, so "the ingredients" is
 * unambiguous: there is only one upstream. A fancy-flow graph branches, fans
 * out, merges and nests, so a connector node several hops downstream has no
 * single trigger to draw from — `availableVariables()` deliberately offers only
 * DIRECT predecessors, because a grandparent's field resolves to `null` at run
 * time and a suggestion that silently produces nothing is worse than no
 * suggestion.
 *
 * We did not paper over that. Connector triggers publish their event as a
 * single object with a declared shape, so the natural thing an author does —
 * carry it forward on the wire — keeps the ingredients available at each step.
 * Reaching further up the graph is a fancy-flow concern, recorded as a finding
 * rather than reimplemented per node.
 */

import type { ConfigField, NodeKindDefinition, OutputField } from "@particle-academy/fancy-flow/engine";

/** The domains the catalogue is grouped by. Mirrors the plan's taxonomy. */
export type ConnectorDomain =
  | "payments"
  | "commerce"
  | "messaging"
  | "email"
  | "crm"
  | "support"
  | "storage"
  | "calendar"
  | "productivity"
  | "database"
  | "devtools"
  | "analytics"
  | "marketing"
  | "ai"
  | "forms"
  | "hr"
  | "geo";

/** What a connector node does in the graph — IFTTT's "this" versus "that". */
export type ConnectorRole = "trigger" | "action" | "search";

/** How the provider exposes a test estate. Kept in step with the runtime's `SandboxKind`. */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

export type ConnectorMeta = {
  service: string;
  serviceTitle: string;
  domain: ConnectorDomain;
  role: ConnectorRole;
  /** The provider's name for this operation, so search finds what people type. */
  operation: string;
  sandbox: SandboxKind;
  /** Link to the provider documentation this node was written against. */
  docs?: string;
};

/**
 * The two fields EVERY connector node carries, in the same order, with the same
 * keys.
 *
 * Uniformity is the feature. An agent that has configured one connector has
 * configured all of them, and a human who has learned where the sandbox switch
 * lives never has to look for it again.
 */
export function connectionFields(meta: ConnectorMeta): ConfigField[] {
  const modes: Array<{ value: string; label: string }> = [
    { value: "auto", label: "Auto — sandbox locally, live in production" },
    { value: "fake", label: "Fake — no credentials, no network" },
  ];

  // Only offer sandbox where one exists. A select listing a mode the provider
  // does not have is an invitation to pick it and then read an error.
  if (meta.sandbox !== "none") {
    modes.push({ value: "sandbox", label: sandboxLabel(meta.sandbox) });
  }
  modes.push({ value: "live", label: "Live — the real account" });

  return [
    {
      type: "credential",
      key: "connection",
      label: `${meta.serviceTitle} connection`,
      credentialType: `connector:${meta.service}`,
      description:
        `Which configured ${meta.serviceTitle} connection to use. Credentials live in the host's ` +
        "configuration, never in the workflow — a graph is exported, committed and handed to agents.",
    },
    {
      type: "select",
      key: "mode",
      label: "Environment",
      options: modes,
      default: "auto",
      description:
        meta.sandbox === "none"
          ? `${meta.serviceTitle} has no sandbox estate, so "auto" means fake locally and live in production.`
          : "Auto follows the environment. Setting this explicitly overrides it everywhere, including in production.",
    },
  ];
}

function sandboxLabel(kind: SandboxKind): string {
  return kind === "base-url"
    ? "Sandbox — the provider's separate test host"
    : kind === "separate-account"
      ? "Sandbox — your separate test account"
      : "Sandbox — the provider's test estate";
}

/**
 * Build a connector node's authoring surface.
 *
 * Prepends the shared connection fields, applies the domain accent, and stamps
 * the metadata the registry reads. A connector that hand-rolled these would
 * drift from its siblings in exactly the small ways that make a catalogue feel
 * like a pile.
 */
export function defineConnectorKind(
  meta: ConnectorMeta,
  kind: Omit<NodeKindDefinition, "category"> & { category?: NodeKindDefinition["category"] },
): NodeKindDefinition & { connector: ConnectorMeta } {
  return {
    ...kind,
    // `category` stays fancy-flow's own taxonomy — it describes what the node
    // does to the GRAPH, which is what the palette groups by. Connector-ness is
    // a separate axis and is carried separately; overloading one field with two
    // meanings would make "show me the triggers" and "hide the connectors"
    // impossible to ask at the same time.
    category: kind.category ?? (meta.role === "trigger" ? "trigger" : "io"),
    accent: kind.accent ?? DOMAIN_ACCENT[meta.domain],
    configSchema: [...connectionFields(meta), ...(kind.configSchema ?? [])],
    connector: meta,
  };
}

/**
 * One line describing what a configured node will do, in IFTTT's register.
 *
 * A configured connector should read as a sentence, not as a form dump — it is
 * what makes a canvas skimmable, and it is also what an agent quotes back to a
 * human when asking whether to proceed.
 */
export function summarize(meta: ConnectorMeta, config: Record<string, unknown>, detail?: string): string {
  const mode = typeof config.mode === "string" ? config.mode : "auto";
  const where =
    mode === "fake"
      ? " (faked — nothing leaves this machine)"
      : mode === "sandbox"
        ? " in the sandbox"
        : mode === "live"
          ? " on the live account"
          : "";

  const what = detail?.trim() ? detail.trim() : meta.operation.replace(/_/g, " ");

  return meta.role === "trigger"
    ? `When ${meta.serviceTitle} reports ${what}${where}`
    : `Then ${meta.serviceTitle} will ${what}${where}`;
}

/** Declare a trigger's event fields — the "ingredients" downstream nodes pick from. */
export function ingredients(fields: OutputField[]): OutputField[] {
  return fields;
}

const DOMAIN_ACCENT: Record<ConnectorDomain, string> = {
  payments: "#635bff",
  commerce: "#96bf48",
  messaging: "#4a154b",
  email: "#0f9d58",
  crm: "#00a1e0",
  support: "#03363d",
  storage: "#ff9900",
  calendar: "#4285f4",
  productivity: "#2f3437",
  database: "#336791",
  devtools: "#24292f",
  analytics: "#f9a03c",
  marketing: "#1877f2",
  ai: "#d97757",
  forms: "#262627",
  hr: "#5c4ee5",
  geo: "#34a853",
};

/**
 * The one call path every connector node uses.
 *
 * A node's executor never chooses between "call the provider" and "call the
 * faker" — it describes the request it wants and hands it here. That is the
 * point: the code path a consumer develops against with no credentials is the
 * same code path that runs in production, so the fixtures prove something about
 * the executor rather than about a mock.
 *
 * ```ts
 * const charge = await callConnector(STRIPE, {
 *   operation: "charge_create",
 *   config,
 *   input: ctx.inputs.in,
 *   request: { method: "POST", path: "/v1/charges", form: { amount, currency } },
 *   idempotencyKey: `${ctx.node.id}:${runKey}`,
 * });
 * ```
 */

import { resolveConnection, type ConnectionCredentials, type ResolvedConnection } from "./connection";
import { classifyHttp, ConnectorConfigError, ConnectorError, ConnectorTransient } from "./errors";
import { fakeRequest, type ConnectorFaker } from "./faker";
import type { ConnectorMode, RequestedMode, SandboxKind } from "./mode";

/**
 * Everything true of a SERVICE rather than of one operation.
 *
 * One of these per provider, declared once and shared by that provider's nodes.
 * It is data — base URLs, which credential keys are required, how the sandbox
 * is selected — so that facts we verified against provider documentation live
 * in exactly one reviewable place instead of being retyped into each node.
 */
export type ServiceDescriptor = {
  service: string;
  title: string;
  sandbox: SandboxKind;
  /**
   * Base URL per mode. A `credential`-sandbox provider gives the same URL for
   * both, which is itself worth writing down: it is why a live key pointed at
   * "sandbox" quietly reaches production.
   */
  baseUrls: Partial<Record<ConnectorMode, string>>;
  /** Credential keys a remote call cannot proceed without. */
  requires: string[];
  /**
   * Apply the provider's auth scheme to an outgoing request.
   *
   * Receives the resolved MODE as well, because for some providers auth and
   * estate are the same decision expressed in the URL — Telegram puts the bot
   * token in the path and selects its test environment with a `/test` segment
   * after it. A signature that hid the mode would push those providers towards
   * a global, which is the thing this seam exists to avoid.
   */
  authorize: (
    credentials: ConnectionCredentials,
    request: PreparedRequest,
    mode: ConnectorMode,
  ) => void | Promise<void>;
  /** The service's faker. Required — see `faker.ts`. */
  faker: ConnectorFaker;
  /** Header the provider uses for idempotency, when it has one. */
  idempotencyHeader?: string;
};

export type ConnectorRequest = {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
  query?: Record<string, string | number | boolean | undefined>;
  headers?: Record<string, string>;
  /** JSON body. Mutually exclusive with `form`. */
  json?: unknown;
  /** `application/x-www-form-urlencoded` body — what several payment APIs want. */
  form?: Record<string, string | number | boolean | undefined>;
};

export type PreparedRequest = {
  method: string;
  url: string;
  headers: Record<string, string>;
  body?: string;
};

export type CallOptions = {
  operation: string;
  config: Record<string, unknown>;
  input?: unknown;
  request: ConnectorRequest;
  /**
   * Value for the provider's idempotency header. Pass something derived from
   * the run and the node, never a fresh uuid: the entire point is that a RETRY
   * carries the same key.
   */
  idempotencyKey?: string;
  /** Retry budget for retryable failures. Defaults to 2 extra attempts. */
  retries?: number;
};

/** The HTTP seam. A host may swap it; nothing here assumes a browser or Node. */
export type Transport = (request: PreparedRequest) => Promise<TransportResponse>;

export type TransportResponse = {
  status: number;
  headers: Record<string, string>;
  body: string;
};

let transport: Transport | null = null;

/** Install a transport. Only needed if the runtime has no global `fetch`. */
export function registerTransport(next: Transport | null): void {
  transport = next;
}

/** What a connector call returns, alongside the provider's own payload. */
export type ConnectorResult<T = unknown> = {
  data: T;
  /** Which estate this actually ran against. Always reported, never inferred. */
  mode: ConnectorMode;
  connection: string;
};

export async function callConnector<T = unknown>(
  service: ServiceDescriptor,
  options: CallOptions,
): Promise<ConnectorResult<T>> {
  const connection = resolveConnection({
    service: service.service,
    operation: options.operation,
    connectionId: readString(options.config, "connection"),
    requested: readString(options.config, "mode") as RequestedMode | null,
    sandbox: service.sandbox,
    baseUrls: service.baseUrls,
    requires: service.requires,
  });

  if (connection.mode === "fake") {
    return {
      data: service.faker(
        options.operation,
        fakeRequest(service.service, options.operation, options.config, options.input),
      ) as T,
      mode: "fake",
      connection: connection.id,
    };
  }

  return {
    data: (await remoteCall(service, connection, options)) as T,
    mode: connection.mode,
    connection: connection.id,
  };
}

async function remoteCall(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<unknown> {
  const prepared = await prepare(service, connection, options);
  const send = transport ?? fetchTransport;
  const ctx = { service: service.service, operation: options.operation };
  const budget = options.retries ?? 2;
  let attempt = 0;

  for (;;) {
    let response: TransportResponse;

    try {
      response = await send(prepared);
    } catch (cause) {
      // A thrown transport is a network-level failure: unreachable, reset,
      // timed out. Retryable by nature, and distinct from a 5xx, which at
      // least proves we reached something.
      const error = new ConnectorTransient(
        `${ctx.service}.${ctx.operation}: ${(cause as Error)?.message ?? "transport failed"}`,
        ctx,
      );
      if (attempt++ >= budget) throw error;
      await sleep(backoffMs(attempt));

      continue;
    }

    if (response.status < 400) {
      return response.body.trim() === "" ? null : parseJson(response.body, ctx);
    }

    const error = classifyHttp(
      response.status,
      ctx,
      response.body,
      readRetryAfter(response.headers),
    );

    if (!error.retryable || attempt++ >= budget) throw error;

    // Honour the provider's own instruction when it gave one. Guessing shorter
    // than they asked is how a throttle becomes a ban.
    const wait = "retryAfter" in error && typeof error.retryAfter === "number"
      ? error.retryAfter * 1000
      : backoffMs(attempt);
    await sleep(wait);
  }
}

async function prepare(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<PreparedRequest> {
  const base = connection.baseUrl ?? service.baseUrls[connection.mode];

  if (!base) {
    throw new ConnectorConfigError(
      `${service.service}: no base URL for "${connection.mode}" mode. ` +
        "The service descriptor must declare one per mode it supports.",
      { service: service.service, operation: options.operation },
    );
  }

  const { method, path, query, headers, json, form } = options.request;
  const url = new URL(path.replace(/^\/+/, ""), base.endsWith("/") ? base : `${base}/`);

  for (const [key, value] of Object.entries(query ?? {})) {
    if (value !== undefined) url.searchParams.set(key, String(value));
  }

  const prepared: PreparedRequest = {
    method,
    url: url.toString(),
    headers: { Accept: "application/json", ...headers },
  };

  if (form) {
    prepared.headers["Content-Type"] = "application/x-www-form-urlencoded";
    prepared.body = encodeForm(form);
  } else if (json !== undefined) {
    prepared.headers["Content-Type"] = "application/json";
    prepared.body = JSON.stringify(json);
  }

  if (options.idempotencyKey && service.idempotencyHeader) {
    prepared.headers[service.idempotencyHeader] = options.idempotencyKey;
  }

  await service.authorize(connection.credentials, prepared, connection.mode);

  return prepared;
}

/**
 * Form encoding, including the bracketed-nesting several payment APIs use
 * (`metadata[order_id]=7`). Flat maps pass through unchanged.
 */
function encodeForm(form: Record<string, unknown>): string {
  const pairs: string[] = [];

  const walk = (prefix: string, value: unknown): void => {
    if (value === undefined || value === null) return;
    if (typeof value === "object" && !Array.isArray(value)) {
      for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
        walk(prefix === "" ? key : `${prefix}[${key}]`, nested);
      }

      return;
    }
    if (Array.isArray(value)) {
      value.forEach((item, index) => walk(`${prefix}[${index}]`, item));

      return;
    }
    pairs.push(`${encodeURIComponent(prefix)}=${encodeURIComponent(String(value))}`);
  };

  walk("", form);

  return pairs.join("&");
}

const fetchTransport: Transport = async (request) => {
  const globalFetch = (globalThis as { fetch?: typeof fetch }).fetch;

  if (!globalFetch) {
    throw new Error(
      "no global fetch in this runtime — call registerTransport() with one before running a connector remotely.",
    );
  }

  const response = await globalFetch(request.url, {
    method: request.method,
    headers: request.headers,
    ...(request.body === undefined ? {} : { body: request.body }),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key.toLowerCase()] = value;
  });

  return { status: response.status, headers, body: await response.text() };
};

function parseJson(body: string, ctx: { service: string; operation: string }): unknown {
  try {
    return JSON.parse(body);
  } catch {
    throw new ConnectorError(
      `${ctx.service}.${ctx.operation}: the provider returned a body that is not JSON.`,
      ctx,
    );
  }
}

function readRetryAfter(headers: Record<string, string>): number | undefined {
  const raw = headers["retry-after"];
  if (!raw) return undefined;
  const seconds = Number(raw);

  return Number.isFinite(seconds) ? seconds : undefined;
}

/** Exponential with a ceiling. Attempt 1 → 250ms, 2 → 500ms, 3 → 1s, capped at 8s. */
function backoffMs(attempt: number): number {
  return Math.min(8000, 250 * 2 ** (attempt - 1));
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readString(config: Record<string, unknown>, key: string): string | null {
  const value = config[key];

  return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
}

/**
 * A CONNECTION — credentials plus an environment choice — configured once per
 * service and referenced by every node that uses it.
 *
 * ## Why this is not per-node config
 *
 * The obvious design is to put an API key field on each node. It is also wrong,
 * for three reasons that only show up later:
 *
 * 1. **Rotation.** A key on twelve nodes is twelve edits and one you will miss.
 * 2. **The sandbox/live switch has to live somewhere singular.** If each node
 *    carries its own, a graph can be half in the test estate and half in the
 *    real one, and nothing about the canvas shows it.
 * 3. **Credentials would be in the graph.** A `WorkflowSchema` is plain JSON
 *    that gets exported, committed, MCP'd to an agent and pasted into issues.
 *    Nothing secret may ever be in it.
 *
 * So a node's config stores a **connection id** — an opaque, non-secret name
 * like `"stripe"` or `"stripe-eu"` — and the host resolves it to credentials at
 * run time. This is the same arrangement fancy-flow already uses for LLM clients
 * and `fancy-git` uses for providers: the node cannot reach for a credential,
 * the host has to hand one over.
 *
 * ```ts
 * registerConnectionHost({
 *   environment: { production: process.env.NODE_ENV === "production" },
 *   connections: {
 *     stripe: {
 *       service: "stripe",
 *       live:    { secretKey: process.env.STRIPE_SECRET_KEY },
 *       sandbox: { secretKey: process.env.STRIPE_TEST_SECRET_KEY },
 *     },
 *   },
 * });
 * ```
 *
 * Note what is NOT here: no key, no token, no placeholder that looks like one.
 * Credentials are configuration, and configuration comes from the consumer's
 * environment.
 */

import { ConnectorConfigError } from "./errors";
import {
  ConnectorModeError,
  resolveConnectorMode,
  type ConnectorMode,
  type HostEnvironment,
  type RequestedMode,
  type SandboxKind,
} from "./mode";

/**
 * Credentials for one estate. Values are opaque strings the node's auth
 * strategy understands — `secretKey`, `clientId`/`clientSecret`, `token`.
 */
export type ConnectionCredentials = Record<string, string | undefined>;

/** One configured connection to one service. */
export type ConnectionSpec = {
  /** The service this connection is for — must match the node's `connector.service`. */
  service: string;
  /** Human label, shown in the picker. Defaults to the id. */
  label?: string;
  /**
   * Pin this connection to a mode. Optional, and usually absent: leaving it
   * unset is what lets the environment supply the default.
   */
  mode?: ConnectorMode;
  live?: ConnectionCredentials;
  sandbox?: ConnectionCredentials;
  /**
   * Override the base URL per mode. Only needed for a `separate-account`
   * provider whose tenant has its own host (a Salesforce instance URL); the
   * `base-url` providers carry theirs in the node's service descriptor.
   */
  baseUrl?: Partial<Record<ConnectorMode, string>>;
};

export type ConnectionHost = {
  environment: HostEnvironment;
  connections: Record<string, ConnectionSpec>;
};

let host: ConnectionHost | null = null;

/**
 * Install the host's connections. Returns an unregister function.
 *
 * One registration for the whole app, matching how a person thinks about it:
 * you authorize Stripe once, then every node that needs Stripe already has it.
 */
export function registerConnectionHost(next: ConnectionHost | null): () => void {
  host = next;

  return () => {
    if (host === next) host = null;
  };
}

export function getConnectionHost(): ConnectionHost | null {
  return host;
}

/** Connection ids the host has configured for a service — feeds the picker. */
export function connectionsFor(service: string): Array<{ id: string; label: string }> {
  const current = getConnectionHost();
  if (!current) return [];

  return Object.entries(current.connections)
    .filter(([, spec]) => spec.service === service)
    .map(([id, spec]) => ({ id, label: spec.label ?? id }));
}

/** What a node's executor actually needs, once everything has been resolved. */
export type ResolvedConnection = {
  id: string;
  service: string;
  mode: ConnectorMode;
  /** Empty in `fake` mode — there is nothing to authenticate against. */
  credentials: ConnectionCredentials;
  /** Undefined in `fake` mode. */
  baseUrl?: string;
};

export type ResolveOptions = {
  service: string;
  operation: string;
  /** The connection id from node config. Defaults to the service name. */
  connectionId?: string | null;
  /** The `mode` field from node config. */
  requested?: RequestedMode | null;
  sandbox: SandboxKind;
  /** Base URL per mode, from the node's service descriptor. */
  baseUrls?: Partial<Record<ConnectorMode, string>>;
  /** Credential keys that must be present for a remote call. */
  requires?: string[];
};

/**
 * Resolve the connection and mode for one call.
 *
 * ## `fake` needs no host at all
 *
 * A freshly vendored connector runs before anything is configured, and that is
 * deliberate: it is the difference between a marketplace someone can try and
 * one they can only read about. So the no-host case resolves to `fake` rather
 * than throwing — UNLESS the author explicitly asked for a remote mode, in
 * which case the ask is honoured by failing loudly instead of quietly doing
 * something else.
 */
export function resolveConnection(options: ResolveOptions): ResolvedConnection {
  const { service, operation, sandbox } = options;
  const requestedMode = options.requested ?? "auto";

  // Checked FIRST, before anything about the host, because it is a static fact
  // about the SERVICE. Asking for a sandbox that does not exist should say so
  // whether or not a connection happens to be configured — otherwise the same
  // mistake produces two different errors depending on unrelated state, and the
  // more useful one is the one you never see.
  if (requestedMode === "sandbox" && sandbox === "none") {
    throw new ConnectorModeError(
      `${service} has no sandbox estate, so "sandbox" cannot be honoured. ` +
        'Use "fake" to develop without credentials, or "live" to talk to the provider.',
    );
  }

  const id = options.connectionId?.trim() || service;
  const current = getConnectionHost();
  const spec = current?.connections[id];

  if (spec && spec.service !== service) {
    throw new ConnectorConfigError(
      `connection "${id}" is configured for the "${spec.service}" service, but this node needs "${service}".`,
      { service, operation },
    );
  }

  if (!current || !spec) {
    if (requestedMode !== "auto" && requestedMode !== "fake") {
      throw new ConnectorConfigError(
        `no "${id}" connection is registered, so ${service}.${operation} cannot run in "${requestedMode}" mode. ` +
          "Call registerConnectionHost({ connections: { " +
          `${id}: { service: "${service}", live: { … } } } }) — the node has no credentials of its own ` +
          'and must not invent any. Set the node\'s mode to "fake" to develop without one.',
        { service, operation },
      );
    }

    return { id, service, mode: "fake", credentials: {} };
  }

  const sandboxCreds = spec.sandbox ?? {};
  const mode = resolveConnectorMode({
    requested: requestedMode,
    connectionMode: spec.mode ?? null,
    sandbox,
    hasSandboxCredentials: hasAll(sandboxCreds, options.requires ?? []),
    environment: current.environment,
  });

  if (mode === "fake") {
    return { id, service, mode, credentials: {} };
  }

  const credentials = (mode === "sandbox" ? spec.sandbox : spec.live) ?? {};
  const missing = (options.requires ?? []).filter((key) => !credentials[key]);

  if (missing.length > 0) {
    // Never silently degrade to the faker here. A run that "succeeded" because
    // it quietly stopped talking to the provider is the worst failure this
    // whole design exists to prevent — it is green, it is wrong, and nothing
    // reports it.
    throw new ConnectorConfigError(
      `connection "${id}" has no ${missing.join(", ")} for ${mode} mode. ` +
        `Set connections.${id}.${mode}.${missing[0]}, or run this node in "fake" mode.`,
      { service, operation },
    );
  }

  const baseUrl = spec.baseUrl?.[mode] ?? options.baseUrls?.[mode];

  return { id, service, mode, credentials, ...(baseUrl ? { baseUrl } : {}) };
}

function hasAll(creds: ConnectionCredentials, keys: string[]): boolean {
  return keys.length > 0 && keys.every((key) => Boolean(creds[key]));
}

/**
 * The connector error taxonomy.
 *
 * Durable runs retry, and a retry policy needs to know WHICH KIND of failure it
 * is looking at. "Something went wrong" is not enough information to decide
 * between retrying, pausing for a human, and stopping — so every connector
 * failure is classified at the point it is known, which is inside the connector,
 * not three frames up where the type has already been lost.
 *
 * | class                    | retry? | why |
 * |--------------------------|--------|-----|
 * | `ConnectorConfigError`   | never  | nothing about a second attempt changes an unset key |
 * | `ConnectorAuthError`     | never  | the credential is wrong; hammering it gets accounts locked |
 * | `ConnectorRateLimited`   | yes    | after `retryAfter`, which the provider told us |
 * | `ConnectorTransient`     | yes    | 5xx, timeout, connection reset |
 * | `ConnectorRequestError`  | never  | 4xx we caused; the same request fails the same way |
 */

export type ConnectorErrorContext = {
  service: string;
  operation: string;
  /** HTTP status when there was one. */
  status?: number;
  /** The provider's own error code, when it publishes one. */
  providerCode?: string;
};

/** Base for everything below, so a host can catch the family in one clause. */
export class ConnectorError extends Error {
  readonly service: string;

  readonly operation: string;

  readonly status?: number;

  readonly providerCode?: string;

  /** Whether a second attempt could plausibly succeed. */
  readonly retryable: boolean = false;

  constructor(message: string, ctx: ConnectorErrorContext) {
    super(message);
    this.name = new.target.name;
    this.service = ctx.service;
    this.operation = ctx.operation;
    this.status = ctx.status;
    this.providerCode = ctx.providerCode;
  }
}

/**
 * A required piece of configuration is missing or unusable.
 *
 * The message must name the exact key the consumer has to set. "Stripe is not
 * configured" sends someone reading source; "no `secretKey` on the `stripe`
 * connection — set it via registerConnectionHost" sends them to the line.
 */
export class ConnectorConfigError extends ConnectorError {}

/** The provider rejected the credential. Retrying cannot help. */
export class ConnectorAuthError extends ConnectorError {
  override readonly retryable = false;
}

/** The provider asked us to slow down. */
export class ConnectorRateLimited extends ConnectorError {
  override readonly retryable = true;

  /** Seconds to wait, when the provider said. */
  readonly retryAfter?: number;

  constructor(message: string, ctx: ConnectorErrorContext & { retryAfter?: number }) {
    super(message, ctx);
    this.retryAfter = ctx.retryAfter;
  }
}

/** A 5xx, a timeout, a reset — the provider's problem, and it may pass. */
export class ConnectorTransient extends ConnectorError {
  override readonly retryable = true;
}

/** A 4xx we caused. The same request will fail the same way. */
export class ConnectorRequestError extends ConnectorError {
  override readonly retryable = false;
}

/**
 * Classify an HTTP response into the taxonomy.
 *
 * 429 before the 4xx sweep, deliberately: a rate limit is a 4xx and is the one
 * 4xx that IS worth retrying, so an ordering that checked `>= 400` first would
 * mark every throttle permanent and turn a busy minute into a failed run.
 */
export function classifyHttp(
  status: number,
  ctx: ConnectorErrorContext,
  body: string,
  retryAfter?: number,
): ConnectorError {
  const detail = body.trim() === "" ? "" : ` — ${truncate(body, 400)}`;
  const where = `${ctx.service}.${ctx.operation}`;

  if (status === 429) {
    return new ConnectorRateLimited(`${where}: rate limited by the provider${detail}`, {
      ...ctx,
      status,
      retryAfter,
    });
  }

  if (status === 401 || status === 403) {
    return new ConnectorAuthError(
      `${where}: the provider rejected the credential (${status})${detail}. ` +
        "Check the connection's credentials and that they match the mode you are running in — " +
        "a live key in sandbox, or the reverse, fails exactly like this.",
      { ...ctx, status },
    );
  }

  if (status >= 500) {
    return new ConnectorTransient(`${where}: provider returned ${status}${detail}`, { ...ctx, status });
  }

  return new ConnectorRequestError(`${where}: request rejected with ${status}${detail}`, { ...ctx, status });
}

function truncate(value: string, max: number): string {
  return value.length <= max ? value : `${value.slice(0, max)}…`;
}

/**
 * The faker layer — every connector ships one, always.
 *
 * ## Why every connector, and not just the ones without a sandbox
 *
 * A sandbox still needs an account, a key, a network, and a provider that is
 * up. That is four ways for someone evaluating the kit to get nothing working,
 * before they have learned anything about the kit. A faker removes all four:
 * vendor a node, drop it on a canvas, press run, see a shaped result.
 *
 * It is also what makes the golden fixtures honest. Fixtures run on both
 * runtimes and are the publish gate; if they needed a network they would either
 * be skipped in CI or be flaky, and a flaky gate is one people learn to
 * re-run rather than read.
 *
 * ## Deterministic, not random
 *
 * Same inputs, same output — always. A faker that returns a fresh uuid every
 * call cannot be asserted on, so its fixtures degrade to "it did not throw",
 * which is the assertion that catches nothing. Values here are derived from a
 * seed built out of the service, the operation and the request, so two runs
 * agree and two runtimes can be compared to each other.
 *
 * The values are obviously fake ON PURPOSE — `fake_`-prefixed ids, `example.test`
 * hosts, round numbers. Nobody should ever look at a faked result and wonder
 * whether it moved real money.
 */

/** A faker: one function per service, switching on the operation. */
export type ConnectorFaker = (operation: string, request: FakeRequest) => unknown;

export type FakeRequest = {
  /** The node's resolved config. */
  config: Record<string, unknown>;
  /** The value on the incoming wire. */
  input?: unknown;
  /** Deterministic helpers, seeded from service + operation + config. */
  fake: FakeValues;
};

/**
 * Deterministic value helpers handed to a faker.
 *
 * Small on purpose. A faker's job is to return the SHAPE the provider returns —
 * the field names a downstream node will reference — not to simulate the
 * provider's business logic.
 */
export type FakeValues = {
  /** A stable id with the provider's usual prefix: `id("ch")` → `ch_fake_1a2b3c`. */
  id: (prefix: string) => string;
  /** A stable integer in `[min, max]`. */
  int: (min: number, max: number) => number;
  /** Pick a stable element of a list. */
  pick: <T>(options: readonly T[]) => T;
  /** A fixed ISO-8601 instant, offset by whole seconds. Never `Date.now()`. */
  timestamp: (offsetSeconds?: number) => string;
  /** A stable lowercase hex string of `length` characters. */
  hex: (length: number) => string;
};

/**
 * The instant every faker counts from.
 *
 * A constant rather than the clock, because a fixture asserting on `createdAt`
 * must not start failing tomorrow. Chosen to be recognisably synthetic.
 */
export const FAKE_EPOCH = "2026-01-01T00:00:00.000Z";

/** FNV-1a. Small, dependency-free, and stable across both runtimes. */
export function seedFrom(...parts: unknown[]): number {
  const text = parts.map((part) => (typeof part === "string" ? part : stableJson(part))).join("|");
  let hash = 0x811c9dc5;

  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    // 32-bit FNV prime multiply, kept in range without BigInt.
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }

  return hash >>> 0;
}

/**
 * Key order must not change a seed.
 *
 * `JSON.stringify` preserves insertion order, so `{a,b}` and `{b,a}` would hash
 * differently and the "same inputs, same output" promise would hold only for
 * objects that happened to be built in the same order — which is exactly the
 * kind of almost-true that survives review and fails in a fixture months later.
 */
function stableJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;

  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([k, v]) => `${JSON.stringify(k)}:${stableJson(v)}`);

  return `{${entries.join(",")}}`;
}

/** Build the deterministic helpers for one faked call. */
export function fakeValues(seed: number): FakeValues {
  // A tiny xorshift, advanced per call so successive helpers differ while the
  // whole sequence stays a pure function of the seed.
  let state = seed || 0x9e3779b9;
  const next = (): number => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;

    return state;
  };

  const hex = (length: number): string => {
    let out = "";
    while (out.length < length) out += next().toString(16).padStart(8, "0");

    return out.slice(0, length);
  };

  return {
    hex,
    id: (prefix: string) => `${prefix}_fake_${hex(12)}`,
    int: (min: number, max: number) => min + (next() % Math.max(1, max - min + 1)),
    pick: <T>(options: readonly T[]): T => options[next() % options.length] as T,
    timestamp: (offsetSeconds = 0) =>
      new Date(Date.parse(FAKE_EPOCH) + offsetSeconds * 1000).toISOString(),
  };
}

/** Build the request handed to a faker, with helpers already seeded. */
export function fakeRequest(
  service: string,
  operation: string,
  config: Record<string, unknown>,
  input?: unknown,
): FakeRequest {
  return { config, input, fake: fakeValues(seedFrom(service, operation, config)) };
}

/**
 * Deriving an idempotency key — and being honest when we cannot.
 *
 * ## The gap this works around
 *
 * A durable run RETRIES. For a writing connector that is only survivable if the
 * retry carries the same idempotency key the first attempt did, so the provider
 * returns the original result instead of creating a second charge, a second
 * refund, a second message.
 *
 * **Neither engine's execution context carries a run identity today.** The TS
 * `ctx` is `{ node, inputs, emit, abort }`; `FancyFlow\Runtime\ExecutionContext`
 * is the same four plus `depth`. There is no run key, no attempt number, nothing
 * a node can key on — checked against fancy-flow 0.45.0 and fancy-flow-php
 * 0.17.0 rather than assumed.
 *
 * So this reads the conventional places a host might put one, and returns
 * `null` when there is none.
 *
 * ## Why the two obvious fallbacks are both wrong
 *
 * - **The node id alone** is stable across retries — and also across different
 *   runs. Two legitimate payments for the same customer would share a key, and
 *   the second would be silently deduplicated into the first. A payment that
 *   never happened, reported as success.
 * - **A fresh random value** is unique per run — and also per attempt. A retry
 *   would create a second charge, which is the whole thing we are avoiding.
 *
 * Both are worse than no key. So with no run identity a connector sends none
 * and stays `unsafe-to-replay`, which pins it to a single attempt under the
 * per-node queue driver. Fewer retries, no double writes.
 */

/** Where a host may publish the run key. Checked in order. */
export function runKeyFrom(ctx: unknown): string | null {
  const bag = ctx as Record<string, any> | null;
  if (!bag) return null;

  const candidates = [
    bag.runKey,
    bag.run?.key,
    bag.runId,
    // A host with no engine support can seed it as an initial input, which the
    // engine merges into every node's inputs.
    bag.inputs?.__runKey,
  ];

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim() !== "") return candidate.trim();
  }

  return null;
}

/**
 * The idempotency key for one node in one run, or `null`.
 *
 * `null` is a legitimate answer and callers must treat it as one — passing it
 * through means "send no idempotency header", not "make something up".
 */
export function idempotencyKeyFor(ctx: unknown, nodeId: string): string | null {
  const run = runKeyFrom(ctx);

  return run === null ? null : `${run}:${nodeId}`;
}

/**
 * The warning a node emits when it is about to write without a key.
 *
 * Said out loud, at the moment it matters, because the failure it precedes is
 * invisible: the run succeeds, the retry succeeds, and there are two charges.
 */
export const NO_IDEMPOTENCY_KEY_WARNING =
  "no run identity available, so this write is being sent WITHOUT an idempotency key. " +
  "A retry would repeat the effect rather than recover from it — the node is marked " +
  "unsafe-to-replay, so a durable runner will give it one attempt. To enable safe retries, " +
  "seed a stable `__runKey` into the run's initial inputs.";

/**
 * The shared connector runtime, for hosts that EXECUTE on TypeScript.
 *
 * Vendored, not installed: this directory is copied into a consumer's project
 * alongside the first connector node they add, and every connector after that
 * reuses it. There is no package to require — that is the whole point of the
 * node marketplace, and a shared runtime that arrived as a dependency would
 * undo it.
 */

export * from "./client";
export * from "./connection";
export * from "./errors";
export * from "./faker";
export * from "./mode";
export * from "./trigger";
export * from "./webhook";

/**
 * Which copy of a provider a connector talks to — and who decides.
 *
 * Three modes, and the third is the one that makes this marketplace usable:
 *
 * | mode      | talks to                    | needs credentials | needs network |
 * |-----------|-----------------------------|-------------------|---------------|
 * | `live`    | the provider, for real      | yes               | yes           |
 * | `sandbox` | the provider's test estate  | yes (test ones)   | yes           |
 * | `fake`    | the node's own faker        | no                | no            |
 *
 * ## The environment is the DEFAULT, never the constraint
 *
 * A locally-hosted project defaults to sandbox. It is not *pinned* to sandbox:
 * an author who explicitly asks for `live` on their laptop gets `live`, because
 * the alternative — an environment that silently overrides a stated intention —
 * produces the worst outcome available here, which is a workflow that reports
 * success while having charged nobody. Equally, `sandbox` set explicitly stays
 * sandbox in production, which is how you stage a connector before cutting it
 * over.
 *
 * So: explicit beats the connection, the connection beats the environment.
 *
 * ## Why "fake" is a MODE and not a test double
 *
 * Every connector ships a faker (see `faker.ts`), and it is reachable the same
 * way in a test, in a demo and on a laptop with no credentials. Making it a
 * separate mechanism — a mock injected only under test — would mean the code
 * path a consumer develops against is not the one that runs, and the fixtures
 * would prove nothing about the executor.
 */

/** The three environments a connector node can run against. */
export type ConnectorMode = "fake" | "sandbox" | "live";

/** What a node's `mode` config field may say. `auto` means "let the rules decide". */
export type RequestedMode = ConnectorMode | "auto";

export const CONNECTOR_MODES: ConnectorMode[] = ["fake", "sandbox", "live"];

/**
 * How a provider exposes its test estate — the four shapes that actually exist.
 *
 * This is data, not per-node code, because getting it wrong is the difference
 * between hitting a test ledger and hitting a real one. Verified per provider in
 * `.ai/plans/fancy-flow-connector-nodes.md`; a node declares which of the four
 * it is and the core does the rest.
 *
 * - `credential` — same base URL, a test-scoped key selects the estate
 *   (Stripe's `sk_test_…`). The trap: pointing a live key at it works, so the
 *   only guard is the key itself.
 * - `base-url` — a different host entirely (PayPal's `api-m.sandbox.paypal.com`).
 * - `separate-account` — a distinct tenant you must create, often with its own
 *   login host (Salesforce sandbox orgs on `test.salesforce.com`).
 * - `none` — the provider has no test estate. `sandbox` is then not offered at
 *   all, and the node's honest choices are `fake` and `live`.
 */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

/** The host's view of where it is running. Kept tiny so it is trivial to fake. */
export type HostEnvironment = {
  /** True only in a real production deployment. Everything else is "local". */
  production: boolean;
};

export type ModeInputs = {
  /** What the node's config asked for. `undefined` / `"auto"` means "decide". */
  requested?: RequestedMode | null;
  /** A mode pinned on the CONNECTION, if the host pinned one. */
  connectionMode?: ConnectorMode | null;
  /** Whether the provider has a test estate at all. */
  sandbox: SandboxKind;
  /** Whether the connection actually carries credentials for the sandbox estate. */
  hasSandboxCredentials: boolean;
  environment: HostEnvironment;
};

/**
 * Resolve the mode a connector call runs in.
 *
 * Deliberately a pure function of stated facts, so both runtimes can be held to
 * the same table of cases and a host can unit-test its own wiring without a
 * network or a provider.
 */
export function resolveConnectorMode(inputs: ModeInputs): ConnectorMode {
  const { requested, connectionMode, sandbox, hasSandboxCredentials, environment } = inputs;

  // 1. An explicit ask wins everywhere. This is the rule that makes the
  //    environment a default rather than a cage.
  if (requested && requested !== "auto") {
    if (requested === "sandbox" && sandbox === "none") {
      throw new ConnectorModeError(
        'This connector\'s provider has no sandbox estate, so "sandbox" cannot be honoured. ' +
          'Use "fake" to develop without credentials, or "live" to talk to the provider.',
      );
    }

    return requested;
  }

  // 2. A mode pinned on the connection. One place per service, which is the
  //    whole reason connections exist as a separate thing.
  if (connectionMode) return connectionMode;

  // 3. Otherwise the environment decides.
  if (environment.production) return "live";

  // Local: prefer the provider's own test estate when it exists AND is wired.
  // Falling through to `fake` when it is not is what makes a freshly vendored
  // node runnable with no setup at all — the difference between a marketplace
  // you can try and one you can only read about.
  return sandbox !== "none" && hasSandboxCredentials ? "sandbox" : "fake";
}

/** Raised when a requested mode cannot be honoured. Never downgraded silently. */
export class ConnectorModeError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ConnectorModeError";
  }
}

/** True when the mode reaches the provider over the network. */
export function isRemote(mode: ConnectorMode): boolean {
  return mode !== "fake";
}

/**
 * How a connector trigger learns that something happened.
 *
 * **Not every provider pushes, and assuming webhooks is the single most common
 * way a connector catalogue ends up lying.** Google Drive and Microsoft Graph
 * want a *subscription* you must renew before it expires. Salesforce wants a
 * Pub/Sub or CometD stream. S3 wants an event notification routed to
 * infrastructure the consumer provisions. Reddit wants you to poll. Each of
 * those is a different obligation on the host, and a node that declared
 * "webhook" for all of them would install cleanly and then never fire.
 *
 * So a trigger declares its delivery mechanism, and the host can refuse to mount
 * one it has no machinery for — at author time, not at 3am.
 */

import type { ResolvedConnection } from "./connection";
import type { ConnectorFaker } from "./faker";
import { fakeRequest } from "./faker";
import type { HmacScheme, WebhookVerification } from "./webhook";
import { header, verifyHmac } from "./webhook";

/**
 * The delivery mechanisms that actually exist in the wild.
 *
 * - `webhook` — the provider POSTs to a URL you own. Verify the signature.
 * - `subscription` — a webhook that EXPIRES. Someone has to renew it, forever,
 *   and if nobody does the workflow stops firing without an error anywhere.
 *   Distinct from `webhook` precisely because that ongoing duty is invisible.
 * - `poll` — you ask, on a schedule, and track a cursor.
 * - `pubsub` — the provider publishes to a broker (Google Pub/Sub, Salesforce
 *   Pub/Sub API, SNS/SQS) that the consumer must provision.
 * - `stream` — a long-lived connection the host maintains (websocket, gRPC,
 *   SSE, CometD).
 */
export type DeliveryMechanism = "webhook" | "subscription" | "poll" | "pubsub" | "stream";

export type TriggerDescriptor = {
  service: string;
  operation: string;
  delivery: DeliveryMechanism;
  /**
   * What the host has to do before this fires, in one sentence, aimed at the
   * person who has to do it. Surfaced by the editor and by the MCP, because a
   * trigger whose setup is undocumented is a trigger that silently never fires.
   */
  setup: string;
  /** For `subscription`: how long the provider keeps it alive, in seconds. */
  subscriptionTtl?: number;
  /** For `webhook` / `subscription`: how a delivery is authenticated. */
  verification?: WebhookVerificationSpec;
  /** For `poll`: the provider's smallest sane interval, in seconds. */
  minPollSeconds?: number;
  /** A faked sample event, so the node is runnable before any of the above. */
  faker: ConnectorFaker;
};

export type WebhookVerificationSpec = {
  /** Header carrying the signature. */
  signatureHeader: string;
  /** Header carrying the timestamp, when the scheme signs one. */
  timestampHeader?: string;
  scheme: HmacScheme;
  /**
   * Some schemes pack the timestamp INTO the signature header
   * (Stripe: `t=…,v1=…`). Given the raw header value, return the parts.
   */
  parse?: (raw: string) => { signature?: string; timestamp?: string };
};

export type InboundDelivery = {
  /** The body EXACTLY as received. Not re-serialised. See `webhook.ts`. */
  raw: string;
  headers: Record<string, string | string[] | undefined>;
};

/**
 * Verify an inbound delivery against a trigger's declared scheme.
 *
 * A trigger with no `verification` REFUSES rather than accepts. That asymmetry
 * is the whole safety property: an unverifiable endpoint is a stranger's button
 * for starting workflows in your account, and defaulting to "allow" would make
 * every misconfiguration into an open door that looks shut.
 */
export async function verifyDelivery(
  trigger: TriggerDescriptor,
  delivery: InboundDelivery,
  secret: string | undefined,
  now?: number,
): Promise<WebhookVerification> {
  const spec = trigger.verification;

  if (!spec) {
    return {
      ok: false,
      reason: `${trigger.service}.${trigger.operation} declares no signature scheme, so a delivery cannot be trusted.`,
    };
  }

  const rawHeader = header(delivery.headers, spec.signatureHeader);
  const parsed = spec.parse && rawHeader ? spec.parse(rawHeader) : { signature: rawHeader };
  const timestamp = parsed.timestamp
    ?? (spec.timestampHeader ? header(delivery.headers, spec.timestampHeader) : undefined);

  return verifyHmac({
    raw: delivery.raw,
    signature: parsed.signature,
    secret,
    scheme: spec.scheme,
    timestamp,
    ...(now === undefined ? {} : { now }),
  });
}

/**
 * The event a trigger node publishes when it runs.
 *
 * Three sources, in order, and the third is why a connector trigger is usable
 * on day one:
 *
 * 1. A verified delivery the host injected on the `in` port.
 * 2. Nothing injected, but the connection is remote — that is a host wiring
 *    error, and it fails loudly rather than emitting a plausible blank.
 * 3. `fake` mode — the trigger emits its own sample event, so an author can
 *    press Run, see the real field names, and wire the downstream nodes against
 *    them before the provider has ever been contacted.
 */
export function triggerEvent(
  trigger: TriggerDescriptor,
  connection: ResolvedConnection,
  injected: unknown,
  config: Record<string, unknown>,
): unknown {
  if (hasDelivery(injected)) return injected;

  if (connection.mode === "fake") {
    return trigger.faker(
      trigger.operation,
      fakeRequest(trigger.service, trigger.operation, config),
    );
  }

  throw new Error(
    `${trigger.service}.${trigger.operation}: no event was delivered to this trigger. ` +
      `Its delivery mechanism is "${trigger.delivery}" — ${trigger.setup} ` +
      'Set the node\'s mode to "fake" to design against a sample event instead.',
  );
}

/**
 * Whether a value on the `in` port is an actual delivery.
 *
 * An EMPTY object or array counts as nothing delivered, and that is not
 * fussiness: a manually started run seeds `{}` on the trigger's input, so a
 * bare null check would hand the executor an empty envelope and call it an
 * event. Downstream every field would be `null`, the run would be green, and
 * nothing would say the trigger never fired.
 */
function hasDelivery(value: unknown): boolean {
  if (value === undefined || value === null) return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "object") return Object.keys(value as object).length > 0;

  return true;
}

/**
 * Verifying an inbound provider webhook.
 *
 * An unverified webhook endpoint is a public, unauthenticated way to start a
 * workflow in someone's account — which is to say, a way for a stranger to make
 * your app refund an order or post to your Slack. So verification is part of the
 * connector pattern rather than an exercise for the host: a trigger node that
 * cannot verify its deliveries must say so, and a host must not be able to mount
 * one by accident.
 *
 * ## The three things every provider's scheme actually needs
 *
 * Providers differ in header names and in what exactly gets signed, and almost
 * nothing else:
 *
 * 1. **The RAW body.** Signatures are computed over bytes. Re-serialising parsed
 *    JSON changes key order and whitespace and produces a signature mismatch
 *    that looks like a wrong secret. The host must pass the body it received.
 * 2. **A constant-time comparison.** `===` on a signature leaks, through timing,
 *    which prefix was right. That is a real forgery path, not a theoretical one.
 * 3. **A timestamp tolerance.** Without it a valid signature is valid forever,
 *    so anyone who ever saw one delivery can replay it whenever they like.
 *
 * WebCrypto rather than `node:crypto`, so the same file runs on Node, Bun, Deno
 * and an edge runtime. Node 22 is the suite's floor and has it globally.
 */

export type WebhookVerification =
  | { ok: true }
  | { ok: false; reason: string };

export type HmacScheme = {
  /** Hash to use. */
  algorithm: "SHA-256" | "SHA-1" | "SHA-512";
  /**
   * Build the exact string that gets signed. Providers differ here more than
   * anywhere else — Stripe signs `${timestamp}.${body}`, Slack signs
   * `v0:${timestamp}:${body}`, GitHub signs the body alone.
   */
  payload: (raw: string, timestamp?: string) => string;
  /** Seconds a delivery stays acceptable. */
  tolerance?: number;
  /** Encoding of the signature the provider sends. */
  encoding?: "hex" | "base64";
};

/**
 * Verify an HMAC-signed delivery.
 *
 * Returns a RESULT rather than throwing, and the failure carries a reason: a
 * host wants to log which check failed (stale? wrong secret? no header?) while
 * still answering the provider with an opaque 400.
 */
export async function verifyHmac(options: {
  raw: string;
  signature: string | undefined;
  secret: string | undefined;
  scheme: HmacScheme;
  timestamp?: string;
  /** Seconds since the epoch. Injected so tests are not clock-dependent. */
  now?: number;
}): Promise<WebhookVerification> {
  const { raw, signature, secret, scheme, timestamp } = options;

  if (!secret) {
    // Never "accept when unconfigured". An endpoint that verifies nothing
    // because nobody set a secret is strictly worse than one that is off: it
    // looks protected.
    return { ok: false, reason: "no signing secret configured for this trigger" };
  }
  if (!signature) return { ok: false, reason: "delivery carried no signature header" };

  if (scheme.tolerance !== undefined) {
    if (!timestamp) return { ok: false, reason: "delivery carried no timestamp header" };

    const sent = Number(timestamp);
    if (!Number.isFinite(sent)) return { ok: false, reason: "timestamp header is not a number" };

    const now = options.now ?? Math.floor(Date.now() / 1000);
    if (Math.abs(now - sent) > scheme.tolerance) {
      return { ok: false, reason: `delivery is outside the ${scheme.tolerance}s replay window` };
    }
  }

  const expected = await hmac(secret, scheme.payload(raw, timestamp), scheme.algorithm, scheme.encoding ?? "hex");

  return constantTimeEquals(expected, signature)
    ? { ok: true }
    : { ok: false, reason: "signature did not match" };
}

/** HMAC of `payload` under `secret`, hex or base64 encoded. */
export async function hmac(
  secret: string,
  payload: string,
  algorithm: HmacScheme["algorithm"],
  encoding: "hex" | "base64" = "hex",
): Promise<string> {
  const subtle = globalThis.crypto?.subtle;

  if (!subtle) {
    throw new Error(
      "WebCrypto is not available in this runtime, so webhook signatures cannot be verified. " +
        "Refusing to accept deliveries unverified.",
    );
  }

  const encoder = new TextEncoder();
  const key = await subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: algorithm },
    false,
    ["sign"],
  );
  const bytes = new Uint8Array(await subtle.sign("HMAC", key, encoder.encode(payload)));

  if (encoding === "base64") {
    let binary = "";
    bytes.forEach((byte) => {
      binary += String.fromCharCode(byte);
    });

    return btoa(binary);
  }

  return Array.from(bytes)
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Compare two strings without leaking where they diverge.
 *
 * The length check first is deliberate and safe: a signature's length is fixed
 * by its algorithm and is not a secret, so revealing a mismatch there tells an
 * attacker nothing they could not compute.
 */
export function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) return false;

  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);

  return diff === 0;
}

/**
 * Pull one header case-insensitively.
 *
 * Header case is not preserved consistently across proxies, frameworks and
 * runtimes; a connector that read `req.headers["Stripe-Signature"]` would work
 * behind one server and reject every delivery behind another.
 */
export function header(headers: Record<string, string | string[] | undefined>, name: string): string | undefined {
  const wanted = name.toLowerCase();

  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() !== wanted) continue;

    return Array.isArray(value) ? value[0] : value;
  }

  return undefined;
}

/**
 * Resend's identity on the authoring surface.
 *
 * `ui/` lands on EVERY host, so it must import nothing from `js/` — the
 * vendoring test fails the build if it does.
 */

import type { ConnectorMeta } from "../../_connector/ui/connector";

export const RESEND_SERVICE = {
  service: "resend",
  serviceTitle: "Resend",
  domain: "email",
  // No test estate. The shared field builder reads this and simply does not
  // offer "sandbox" — a choice the provider cannot honour is an invitation to
  // pick it and read an error.
  sandbox: "none",
} as const satisfies Pick<ConnectorMeta, "service" | "serviceTitle" | "domain" | "sandbox">;

export function resendMeta(
  role: ConnectorMeta["role"],
  operation: string,
  docs: string,
): ConnectorMeta {
  return { ...RESEND_SERVICE, role, operation, docs };
}

/**
 * Resend — the exemplar for a provider with NO sandbox.
 *
 * ## Why this shape matters enough to be an exemplar
 *
 * Roughly a third of the providers worth connecting have no test estate at all.
 * Resend, Mailchimp, Loops, Discord, Attio, Close, Help Scout, Front, Linear:
 * for every one of them, "just try it" means writing to production. Front's
 * production data is live customer email.
 *
 * A connector catalogue that only worked properly for providers with sandboxes
 * would be a catalogue you cannot evaluate for a third of what it covers. So
 * `fake` is not the fallback here — it is the primary development mode, and the
 * node's `mode` field does not offer "sandbox" at all, because offering a choice
 * the provider cannot honour is an invitation to pick it and read an error.
 *
 * Resend does publish simulator RECIPIENTS (`delivered@resend.dev`,
 * `bounced@resend.dev`, …). Those are not a sandbox: the send is real, it is
 * billed, and it counts against the quota. Modelling them as one would put a
 * live send behind a control labelled "test".
 */

import type { ServiceDescriptor } from "../../_connector/js/client";
import type { ConnectorFaker } from "../../_connector/js/faker";

const API = "https://api.resend.com";

/**
 * Resend's simulator recipients, offered as choices on the node.
 *
 * Named for what they are — live sends that land in a simulator — so nobody
 * reads them as a test estate.
 */
export const RESEND_SIMULATOR_RECIPIENTS = [
  "delivered@resend.dev",
  "bounced@resend.dev",
  "complained@resend.dev",
  "suppressed@resend.dev",
] as const;

export const resendFaker: ConnectorFaker = (operation, request) => {
  const { fake, config } = request;

  if (operation !== "email_send") {
    throw new Error(
      `resend: no fake response is defined for "${operation}". Add one to resendFaker before shipping ` +
        "a node that calls it.",
    );
  }

  return {
    id: fake.hex(8) + "-" + fake.hex(4) + "-" + fake.hex(4) + "-" + fake.hex(4) + "-" + fake.hex(12),
    from: String(config.from ?? "noreply@example.test"),
    to: toList(config.to),
    subject: String(config.subject ?? ""),
    created_at: fake.timestamp(),
    last_event: "delivered",
  };
};

function toList(value: unknown): string[] {
  if (Array.isArray(value)) return value.map(String);
  if (typeof value !== "string" || value.trim() === "") return [];

  return value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

export const RESEND: ServiceDescriptor = {
  service: "resend",
  title: "Resend",
  // The whole point of this exemplar. `sandbox: "none"` makes the shared mode
  // resolver fall through to `fake` on a local project rather than to a test
  // estate that does not exist.
  sandbox: "none",
  baseUrls: { live: API },
  requires: ["apiKey"],
  authorize: (credentials, request) => {
    request.headers.Authorization = `Bearer ${credentials.apiKey}`;
    // Not optional and not cosmetic: Resend answers 403 to a request with no
    // User-Agent, which reads exactly like a bad key and sends people to rotate
    // a credential that was fine.
    request.headers["User-Agent"] = "fancy-flow-connector";
  },
  faker: resendFaker,
};

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";

import { callConnector } from "../../_connector/js/client";
import { idempotencyKeyFor, NO_IDEMPOTENCY_KEY_WARNING } from "../../_connector/js/idempotency";
import { STRIPE } from "../../_stripe/js/service";

/**
 * Create a Stripe PaymentIntent.
 *
 * Notice what is NOT here: no key, no base URL, no mode check, no retry loop,
 * no fake/real branch. The executor describes the request; `callConnector`
 * resolves the connection, picks the estate, and either calls Stripe or calls
 * the faker. Every connector in the catalogue is this shape, which is the point
 * of having a pattern rather than two hundred bespoke nodes.
 */
export const stripePaymentIntentExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;

  const amount = Number(config.amount);
  if (!Number.isInteger(amount) || amount <= 0) {
    // Fail loudly and specifically. "Invalid request" from Stripe three frames
    // later costs an author ten minutes; naming the unit costs them none, and
    // the smallest-unit rule is the single most common mistake against this API.
    throw new Error(
      `stripe_payment_intent: "amount" must be a positive whole number in the currency's smallest unit ` +
        `(1000 = $10.00), got ${JSON.stringify(config.amount)}.`,
    );
  }

  const idempotencyKey = idempotencyKeyFor(ctx, ctx.node.id);
  if (idempotencyKey === null) {
    ctx.emit({
      type: "log",
      level: "warn",
      nodeId: ctx.node.id,
      message: `stripe_payment_intent: ${NO_IDEMPOTENCY_KEY_WARNING}`,
    });
  }

  const result = await callConnector(STRIPE, {
    operation: "payment_intent_create",
    config,
    input: ctx.inputs?.in,
    request: {
      method: "POST",
      path: "/v1/payment_intents",
      // Stripe's API is form-encoded, including its bracketed nesting for
      // metadata. The shared client handles the encoding; the node just says
      // what it wants sent.
      form: {
        amount,
        currency: String(config.currency ?? "usd").toLowerCase(),
        ...(config.customer ? { customer: String(config.customer) } : {}),
        ...(config.description ? { description: String(config.description) } : {}),
        ...(config.receiptEmail ? { receipt_email: String(config.receiptEmail) } : {}),
        ...metadataForm(config.metadata),
      },
    },
    // Derived from the RUN and the NODE, never fresh. A retried durable run
    // must send the same key or Stripe creates a second payment — which is the
    // exact failure `unsafe-to-replay` exists to prevent, and the key is what
    // turns "never retry" into "retry safely".
    ...(idempotencyKey === null ? {} : { idempotencyKey }),
  });

  ctx.emit({
    type: "log",
    level: "info",
    nodeId: ctx.node.id,
    message: `stripe payment_intent ${(result.data as any)?.id} (${result.mode})`,
  });

  return { __port: "out", value: result };
};

/** `{ order_id: "7" }` → `{ "metadata[order_id]": "7" }`. */
function metadataForm(value: unknown): Record<string, string> {
  if (!value || typeof value !== "object") return {};

  const form: Record<string, string> = {};
  for (const [key, item] of Object.entries(value as Record<string, unknown>)) {
    if (item !== undefined && item !== null && item !== "") form[`metadata[${key}]`] = String(item);
  }

  return form;
}

import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { stripePaymentIntentKind } from "../ui/kind";
import { stripePaymentIntentExecutor } from "./executor";

/**
 * The kind with its TypeScript executor attached — for hosts that EXECUTE on TS.
 *
 * The surface in ui/kind.ts carries no executor: the editor is React on every
 * host, so a PHP project vendors ui/ and never js/.
 */
export const stripePaymentIntentRunnableKind: NodeKindDefinition = {
  ...stripePaymentIntentKind,
  executor: stripePaymentIntentExecutor,
};

/**
 * The authoring surface every connector node shares.
 *
 * ## The model, and where it came from
 *
 * IFTTT's authoring UX is the one non-engineers actually complete, and three of
 * its four ideas map onto fancy-flow without distortion:
 *
 * 1. **Service first, then capability.** You pick Stripe, *then* pick what about
 *    Stripe. Not a flat wall of four hundred nodes. Here that lives in the
 *    registry — `connector.service` groups a provider's nodes, and the listing
 *    tools narrow in two steps.
 * 2. **The connection is a thing, not a field.** You authorize a service once
 *    and every applet reuses it. Here: `connection.ts` in the runtime, and the
 *    single `connection` config field below.
 * 3. **Ingredients.** A trigger's output fields become named tokens you drop
 *    into a downstream action's fields. fancy-flow already has the machinery —
 *    `outputShape` on the kind, `availableVariables()` reading it off direct
 *    predecessors — so a connector's job is simply to DECLARE its shape. See
 *    `ingredients.ts`.
 * 4. **A sentence, not a form dump.** `summarize()` below.
 *
 * ## Where it does NOT map, and what we did instead
 *
 * An IFTTT applet is one trigger and one action, so "the ingredients" is
 * unambiguous: there is only one upstream. A fancy-flow graph branches, fans
 * out, merges and nests, so a connector node several hops downstream has no
 * single trigger to draw from — `availableVariables()` deliberately offers only
 * DIRECT predecessors, because a grandparent's field resolves to `null` at run
 * time and a suggestion that silently produces nothing is worse than no
 * suggestion.
 *
 * We did not paper over that. Connector triggers publish their event as a
 * single object with a declared shape, so the natural thing an author does —
 * carry it forward on the wire — keeps the ingredients available at each step.
 * Reaching further up the graph is a fancy-flow concern, recorded as a finding
 * rather than reimplemented per node.
 */

import type { ConfigField, NodeKindDefinition, OutputField } from "@particle-academy/fancy-flow/engine";

/** The domains the catalogue is grouped by. Mirrors the plan's taxonomy. */
export type ConnectorDomain =
  | "payments"
  | "commerce"
  | "messaging"
  | "email"
  | "crm"
  | "support"
  | "storage"
  | "calendar"
  | "productivity"
  | "database"
  | "devtools"
  | "analytics"
  | "marketing"
  | "ai"
  | "forms"
  | "hr"
  | "geo";

/** What a connector node does in the graph — IFTTT's "this" versus "that". */
export type ConnectorRole = "trigger" | "action" | "search";

/** How the provider exposes a test estate. Kept in step with the runtime's `SandboxKind`. */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

export type ConnectorMeta = {
  service: string;
  serviceTitle: string;
  domain: ConnectorDomain;
  role: ConnectorRole;
  /** The provider's name for this operation, so search finds what people type. */
  operation: string;
  sandbox: SandboxKind;
  /** Link to the provider documentation this node was written against. */
  docs?: string;
};

/**
 * The two fields EVERY connector node carries, in the same order, with the same
 * keys.
 *
 * Uniformity is the feature. An agent that has configured one connector has
 * configured all of them, and a human who has learned where the sandbox switch
 * lives never has to look for it again.
 */
export function connectionFields(meta: ConnectorMeta): ConfigField[] {
  const modes: Array<{ value: string; label: string }> = [
    { value: "auto", label: "Auto — sandbox locally, live in production" },
    { value: "fake", label: "Fake — no credentials, no network" },
  ];

  // Only offer sandbox where one exists. A select listing a mode the provider
  // does not have is an invitation to pick it and then read an error.
  if (meta.sandbox !== "none") {
    modes.push({ value: "sandbox", label: sandboxLabel(meta.sandbox) });
  }
  modes.push({ value: "live", label: "Live — the real account" });

  return [
    {
      type: "credential",
      key: "connection",
      label: `${meta.serviceTitle} connection`,
      credentialType: `connector:${meta.service}`,
      description:
        `Which configured ${meta.serviceTitle} connection to use. Credentials live in the host's ` +
        "configuration, never in the workflow — a graph is exported, committed and handed to agents.",
    },
    {
      type: "select",
      key: "mode",
      label: "Environment",
      options: modes,
      default: "auto",
      description:
        meta.sandbox === "none"
          ? `${meta.serviceTitle} has no sandbox estate, so "auto" means fake locally and live in production.`
          : "Auto follows the environment. Setting this explicitly overrides it everywhere, including in production.",
    },
  ];
}

function sandboxLabel(kind: SandboxKind): string {
  return kind === "base-url"
    ? "Sandbox — the provider's separate test host"
    : kind === "separate-account"
      ? "Sandbox — your separate test account"
      : "Sandbox — the provider's test estate";
}

/**
 * Build a connector node's authoring surface.
 *
 * Prepends the shared connection fields, applies the domain accent, and stamps
 * the metadata the registry reads. A connector that hand-rolled these would
 * drift from its siblings in exactly the small ways that make a catalogue feel
 * like a pile.
 */
export function defineConnectorKind(
  meta: ConnectorMeta,
  kind: Omit<NodeKindDefinition, "category"> & { category?: NodeKindDefinition["category"] },
): NodeKindDefinition & { connector: ConnectorMeta } {
  return {
    ...kind,
    // `category` stays fancy-flow's own taxonomy — it describes what the node
    // does to the GRAPH, which is what the palette groups by. Connector-ness is
    // a separate axis and is carried separately; overloading one field with two
    // meanings would make "show me the triggers" and "hide the connectors"
    // impossible to ask at the same time.
    category: kind.category ?? (meta.role === "trigger" ? "trigger" : "io"),
    accent: kind.accent ?? DOMAIN_ACCENT[meta.domain],
    configSchema: [...connectionFields(meta), ...(kind.configSchema ?? [])],
    connector: meta,
  };
}

/**
 * One line describing what a configured node will do, in IFTTT's register.
 *
 * A configured connector should read as a sentence, not as a form dump — it is
 * what makes a canvas skimmable, and it is also what an agent quotes back to a
 * human when asking whether to proceed.
 */
export function summarize(meta: ConnectorMeta, config: Record<string, unknown>, detail?: string): string {
  const mode = typeof config.mode === "string" ? config.mode : "auto";
  const where =
    mode === "fake"
      ? " (faked — nothing leaves this machine)"
      : mode === "sandbox"
        ? " in the sandbox"
        : mode === "live"
          ? " on the live account"
          : "";

  const what = detail?.trim() ? detail.trim() : meta.operation.replace(/_/g, " ");

  return meta.role === "trigger"
    ? `When ${meta.serviceTitle} reports ${what}${where}`
    : `Then ${meta.serviceTitle} will ${what}${where}`;
}

/** Declare a trigger's event fields — the "ingredients" downstream nodes pick from. */
export function ingredients(fields: OutputField[]): OutputField[] {
  return fields;
}

const DOMAIN_ACCENT: Record<ConnectorDomain, string> = {
  payments: "#635bff",
  commerce: "#96bf48",
  messaging: "#4a154b",
  email: "#0f9d58",
  crm: "#00a1e0",
  support: "#03363d",
  storage: "#ff9900",
  calendar: "#4285f4",
  productivity: "#2f3437",
  database: "#336791",
  devtools: "#24292f",
  analytics: "#f9a03c",
  marketing: "#1877f2",
  ai: "#d97757",
  forms: "#262627",
  hr: "#5c4ee5",
  geo: "#34a853",
};

/**
 * The one call path every connector node uses.
 *
 * A node's executor never chooses between "call the provider" and "call the
 * faker" — it describes the request it wants and hands it here. That is the
 * point: the code path a consumer develops against with no credentials is the
 * same code path that runs in production, so the fixtures prove something about
 * the executor rather than about a mock.
 *
 * ```ts
 * const charge = await callConnector(STRIPE, {
 *   operation: "charge_create",
 *   config,
 *   input: ctx.inputs.in,
 *   request: { method: "POST", path: "/v1/charges", form: { amount, currency } },
 *   idempotencyKey: `${ctx.node.id}:${runKey}`,
 * });
 * ```
 */

import { resolveConnection, type ConnectionCredentials, type ResolvedConnection } from "./connection";
import { classifyHttp, ConnectorConfigError, ConnectorError, ConnectorTransient } from "./errors";
import { fakeRequest, type ConnectorFaker } from "./faker";
import type { ConnectorMode, RequestedMode, SandboxKind } from "./mode";

/**
 * Everything true of a SERVICE rather than of one operation.
 *
 * One of these per provider, declared once and shared by that provider's nodes.
 * It is data — base URLs, which credential keys are required, how the sandbox
 * is selected — so that facts we verified against provider documentation live
 * in exactly one reviewable place instead of being retyped into each node.
 */
export type ServiceDescriptor = {
  service: string;
  title: string;
  sandbox: SandboxKind;
  /**
   * Base URL per mode. A `credential`-sandbox provider gives the same URL for
   * both, which is itself worth writing down: it is why a live key pointed at
   * "sandbox" quietly reaches production.
   */
  baseUrls: Partial<Record<ConnectorMode, string>>;
  /** Credential keys a remote call cannot proceed without. */
  requires: string[];
  /**
   * Apply the provider's auth scheme to an outgoing request.
   *
   * Receives the resolved MODE as well, because for some providers auth and
   * estate are the same decision expressed in the URL — Telegram puts the bot
   * token in the path and selects its test environment with a `/test` segment
   * after it. A signature that hid the mode would push those providers towards
   * a global, which is the thing this seam exists to avoid.
   */
  authorize: (
    credentials: ConnectionCredentials,
    request: PreparedRequest,
    mode: ConnectorMode,
  ) => void | Promise<void>;
  /** The service's faker. Required — see `faker.ts`. */
  faker: ConnectorFaker;
  /** Header the provider uses for idempotency, when it has one. */
  idempotencyHeader?: string;
};

export type ConnectorRequest = {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
  query?: Record<string, string | number | boolean | undefined>;
  headers?: Record<string, string>;
  /** JSON body. Mutually exclusive with `form`. */
  json?: unknown;
  /** `application/x-www-form-urlencoded` body — what several payment APIs want. */
  form?: Record<string, string | number | boolean | undefined>;
};

export type PreparedRequest = {
  method: string;
  url: string;
  headers: Record<string, string>;
  body?: string;
};

export type CallOptions = {
  operation: string;
  config: Record<string, unknown>;
  input?: unknown;
  request: ConnectorRequest;
  /**
   * Value for the provider's idempotency header. Pass something derived from
   * the run and the node, never a fresh uuid: the entire point is that a RETRY
   * carries the same key.
   */
  idempotencyKey?: string;
  /** Retry budget for retryable failures. Defaults to 2 extra attempts. */
  retries?: number;
};

/** The HTTP seam. A host may swap it; nothing here assumes a browser or Node. */
export type Transport = (request: PreparedRequest) => Promise<TransportResponse>;

export type TransportResponse = {
  status: number;
  headers: Record<string, string>;
  body: string;
};

let transport: Transport | null = null;

/** Install a transport. Only needed if the runtime has no global `fetch`. */
export function registerTransport(next: Transport | null): void {
  transport = next;
}

/** What a connector call returns, alongside the provider's own payload. */
export type ConnectorResult<T = unknown> = {
  data: T;
  /** Which estate this actually ran against. Always reported, never inferred. */
  mode: ConnectorMode;
  connection: string;
};

export async function callConnector<T = unknown>(
  service: ServiceDescriptor,
  options: CallOptions,
): Promise<ConnectorResult<T>> {
  const connection = resolveConnection({
    service: service.service,
    operation: options.operation,
    connectionId: readString(options.config, "connection"),
    requested: readString(options.config, "mode") as RequestedMode | null,
    sandbox: service.sandbox,
    baseUrls: service.baseUrls,
    requires: service.requires,
  });

  if (connection.mode === "fake") {
    return {
      data: service.faker(
        options.operation,
        fakeRequest(service.service, options.operation, options.config, options.input),
      ) as T,
      mode: "fake",
      connection: connection.id,
    };
  }

  return {
    data: (await remoteCall(service, connection, options)) as T,
    mode: connection.mode,
    connection: connection.id,
  };
}

async function remoteCall(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<unknown> {
  const prepared = await prepare(service, connection, options);
  const send = transport ?? fetchTransport;
  const ctx = { service: service.service, operation: options.operation };
  const budget = options.retries ?? 2;
  let attempt = 0;

  for (;;) {
    let response: TransportResponse;

    try {
      response = await send(prepared);
    } catch (cause) {
      // A thrown transport is a network-level failure: unreachable, reset,
      // timed out. Retryable by nature, and distinct from a 5xx, which at
      // least proves we reached something.
      const error = new ConnectorTransient(
        `${ctx.service}.${ctx.operation}: ${(cause as Error)?.message ?? "transport failed"}`,
        ctx,
      );
      if (attempt++ >= budget) throw error;
      await sleep(backoffMs(attempt));

      continue;
    }

    if (response.status < 400) {
      return response.body.trim() === "" ? null : parseJson(response.body, ctx);
    }

    const error = classifyHttp(
      response.status,
      ctx,
      response.body,
      readRetryAfter(response.headers),
    );

    if (!error.retryable || attempt++ >= budget) throw error;

    // Honour the provider's own instruction when it gave one. Guessing shorter
    // than they asked is how a throttle becomes a ban.
    const wait = "retryAfter" in error && typeof error.retryAfter === "number"
      ? error.retryAfter * 1000
      : backoffMs(attempt);
    await sleep(wait);
  }
}

async function prepare(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<PreparedRequest> {
  const base = connection.baseUrl ?? service.baseUrls[connection.mode];

  if (!base) {
    throw new ConnectorConfigError(
      `${service.service}: no base URL for "${connection.mode}" mode. ` +
        "The service descriptor must declare one per mode it supports.",
      { service: service.service, operation: options.operation },
    );
  }

  const { method, path, query, headers, json, form } = options.request;
  const url = new URL(path.replace(/^\/+/, ""), base.endsWith("/") ? base : `${base}/`);

  for (const [key, value] of Object.entries(query ?? {})) {
    if (value !== undefined) url.searchParams.set(key, String(value));
  }

  const prepared: PreparedRequest = {
    method,
    url: url.toString(),
    headers: { Accept: "application/json", ...headers },
  };

  if (form) {
    prepared.headers["Content-Type"] = "application/x-www-form-urlencoded";
    prepared.body = encodeForm(form);
  } else if (json !== undefined) {
    prepared.headers["Content-Type"] = "application/json";
    prepared.body = JSON.stringify(json);
  }

  if (options.idempotencyKey && service.idempotencyHeader) {
    prepared.headers[service.idempotencyHeader] = options.idempotencyKey;
  }

  await service.authorize(connection.credentials, prepared, connection.mode);

  return prepared;
}

/**
 * Form encoding, including the bracketed-nesting several payment APIs use
 * (`metadata[order_id]=7`). Flat maps pass through unchanged.
 */
function encodeForm(form: Record<string, unknown>): string {
  const pairs: string[] = [];

  const walk = (prefix: string, value: unknown): void => {
    if (value === undefined || value === null) return;
    if (typeof value === "object" && !Array.isArray(value)) {
      for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
        walk(prefix === "" ? key : `${prefix}[${key}]`, nested);
      }

      return;
    }
    if (Array.isArray(value)) {
      value.forEach((item, index) => walk(`${prefix}[${index}]`, item));

      return;
    }
    pairs.push(`${encodeURIComponent(prefix)}=${encodeURIComponent(String(value))}`);
  };

  walk("", form);

  return pairs.join("&");
}

const fetchTransport: Transport = async (request) => {
  const globalFetch = (globalThis as { fetch?: typeof fetch }).fetch;

  if (!globalFetch) {
    throw new Error(
      "no global fetch in this runtime — call registerTransport() with one before running a connector remotely.",
    );
  }

  const response = await globalFetch(request.url, {
    method: request.method,
    headers: request.headers,
    ...(request.body === undefined ? {} : { body: request.body }),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key.toLowerCase()] = value;
  });

  return { status: response.status, headers, body: await response.text() };
};

function parseJson(body: string, ctx: { service: string; operation: string }): unknown {
  try {
    return JSON.parse(body);
  } catch {
    throw new ConnectorError(
      `${ctx.service}.${ctx.operation}: the provider returned a body that is not JSON.`,
      ctx,
    );
  }
}

function readRetryAfter(headers: Record<string, string>): number | undefined {
  const raw = headers["retry-after"];
  if (!raw) return undefined;
  const seconds = Number(raw);

  return Number.isFinite(seconds) ? seconds : undefined;
}

/** Exponential with a ceiling. Attempt 1 → 250ms, 2 → 500ms, 3 → 1s, capped at 8s. */
function backoffMs(attempt: number): number {
  return Math.min(8000, 250 * 2 ** (attempt - 1));
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readString(config: Record<string, unknown>, key: string): string | null {
  const value = config[key];

  return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
}

/**
 * A CONNECTION — credentials plus an environment choice — configured once per
 * service and referenced by every node that uses it.
 *
 * ## Why this is not per-node config
 *
 * The obvious design is to put an API key field on each node. It is also wrong,
 * for three reasons that only show up later:
 *
 * 1. **Rotation.** A key on twelve nodes is twelve edits and one you will miss.
 * 2. **The sandbox/live switch has to live somewhere singular.** If each node
 *    carries its own, a graph can be half in the test estate and half in the
 *    real one, and nothing about the canvas shows it.
 * 3. **Credentials would be in the graph.** A `WorkflowSchema` is plain JSON
 *    that gets exported, committed, MCP'd to an agent and pasted into issues.
 *    Nothing secret may ever be in it.
 *
 * So a node's config stores a **connection id** — an opaque, non-secret name
 * like `"stripe"` or `"stripe-eu"` — and the host resolves it to credentials at
 * run time. This is the same arrangement fancy-flow already uses for LLM clients
 * and `fancy-git` uses for providers: the node cannot reach for a credential,
 * the host has to hand one over.
 *
 * ```ts
 * registerConnectionHost({
 *   environment: { production: process.env.NODE_ENV === "production" },
 *   connections: {
 *     stripe: {
 *       service: "stripe",
 *       live:    { secretKey: process.env.STRIPE_SECRET_KEY },
 *       sandbox: { secretKey: process.env.STRIPE_TEST_SECRET_KEY },
 *     },
 *   },
 * });
 * ```
 *
 * Note what is NOT here: no key, no token, no placeholder that looks like one.
 * Credentials are configuration, and configuration comes from the consumer's
 * environment.
 */

import { ConnectorConfigError } from "./errors";
import {
  ConnectorModeError,
  resolveConnectorMode,
  type ConnectorMode,
  type HostEnvironment,
  type RequestedMode,
  type SandboxKind,
} from "./mode";

/**
 * Credentials for one estate. Values are opaque strings the node's auth
 * strategy understands — `secretKey`, `clientId`/`clientSecret`, `token`.
 */
export type ConnectionCredentials = Record<string, string | undefined>;

/** One configured connection to one service. */
export type ConnectionSpec = {
  /** The service this connection is for — must match the node's `connector.service`. */
  service: string;
  /** Human label, shown in the picker. Defaults to the id. */
  label?: string;
  /**
   * Pin this connection to a mode. Optional, and usually absent: leaving it
   * unset is what lets the environment supply the default.
   */
  mode?: ConnectorMode;
  live?: ConnectionCredentials;
  sandbox?: ConnectionCredentials;
  /**
   * Override the base URL per mode. Only needed for a `separate-account`
   * provider whose tenant has its own host (a Salesforce instance URL); the
   * `base-url` providers carry theirs in the node's service descriptor.
   */
  baseUrl?: Partial<Record<ConnectorMode, string>>;
};

export type ConnectionHost = {
  environment: HostEnvironment;
  connections: Record<string, ConnectionSpec>;
};

let host: ConnectionHost | null = null;

/**
 * Install the host's connections. Returns an unregister function.
 *
 * One registration for the whole app, matching how a person thinks about it:
 * you authorize Stripe once, then every node that needs Stripe already has it.
 */
export function registerConnectionHost(next: ConnectionHost | null): () => void {
  host = next;

  return () => {
    if (host === next) host = null;
  };
}

export function getConnectionHost(): ConnectionHost | null {
  return host;
}

/** Connection ids the host has configured for a service — feeds the picker. */
export function connectionsFor(service: string): Array<{ id: string; label: string }> {
  const current = getConnectionHost();
  if (!current) return [];

  return Object.entries(current.connections)
    .filter(([, spec]) => spec.service === service)
    .map(([id, spec]) => ({ id, label: spec.label ?? id }));
}

/** What a node's executor actually needs, once everything has been resolved. */
export type ResolvedConnection = {
  id: string;
  service: string;
  mode: ConnectorMode;
  /** Empty in `fake` mode — there is nothing to authenticate against. */
  credentials: ConnectionCredentials;
  /** Undefined in `fake` mode. */
  baseUrl?: string;
};

export type ResolveOptions = {
  service: string;
  operation: string;
  /** The connection id from node config. Defaults to the service name. */
  connectionId?: string | null;
  /** The `mode` field from node config. */
  requested?: RequestedMode | null;
  sandbox: SandboxKind;
  /** Base URL per mode, from the node's service descriptor. */
  baseUrls?: Partial<Record<ConnectorMode, string>>;
  /** Credential keys that must be present for a remote call. */
  requires?: string[];
};

/**
 * Resolve the connection and mode for one call.
 *
 * ## `fake` needs no host at all
 *
 * A freshly vendored connector runs before anything is configured, and that is
 * deliberate: it is the difference between a marketplace someone can try and
 * one they can only read about. So the no-host case resolves to `fake` rather
 * than throwing — UNLESS the author explicitly asked for a remote mode, in
 * which case the ask is honoured by failing loudly instead of quietly doing
 * something else.
 */
export function resolveConnection(options: ResolveOptions): ResolvedConnection {
  const { service, operation, sandbox } = options;
  const requestedMode = options.requested ?? "auto";

  // Checked FIRST, before anything about the host, because it is a static fact
  // about the SERVICE. Asking for a sandbox that does not exist should say so
  // whether or not a connection happens to be configured — otherwise the same
  // mistake produces two different errors depending on unrelated state, and the
  // more useful one is the one you never see.
  if (requestedMode === "sandbox" && sandbox === "none") {
    throw new ConnectorModeError(
      `${service} has no sandbox estate, so "sandbox" cannot be honoured. ` +
        'Use "fake" to develop without credentials, or "live" to talk to the provider.',
    );
  }

  const id = options.connectionId?.trim() || service;
  const current = getConnectionHost();
  const spec = current?.connections[id];

  if (spec && spec.service !== service) {
    throw new ConnectorConfigError(
      `connection "${id}" is configured for the "${spec.service}" service, but this node needs "${service}".`,
      { service, operation },
    );
  }

  if (!current || !spec) {
    if (requestedMode !== "auto" && requestedMode !== "fake") {
      throw new ConnectorConfigError(
        `no "${id}" connection is registered, so ${service}.${operation} cannot run in "${requestedMode}" mode. ` +
          "Call registerConnectionHost({ connections: { " +
          `${id}: { service: "${service}", live: { … } } } }) — the node has no credentials of its own ` +
          'and must not invent any. Set the node\'s mode to "fake" to develop without one.',
        { service, operation },
      );
    }

    return { id, service, mode: "fake", credentials: {} };
  }

  const sandboxCreds = spec.sandbox ?? {};
  const mode = resolveConnectorMode({
    requested: requestedMode,
    connectionMode: spec.mode ?? null,
    sandbox,
    hasSandboxCredentials: hasAll(sandboxCreds, options.requires ?? []),
    environment: current.environment,
  });

  if (mode === "fake") {
    return { id, service, mode, credentials: {} };
  }

  const credentials = (mode === "sandbox" ? spec.sandbox : spec.live) ?? {};
  const missing = (options.requires ?? []).filter((key) => !credentials[key]);

  if (missing.length > 0) {
    // Never silently degrade to the faker here. A run that "succeeded" because
    // it quietly stopped talking to the provider is the worst failure this
    // whole design exists to prevent — it is green, it is wrong, and nothing
    // reports it.
    throw new ConnectorConfigError(
      `connection "${id}" has no ${missing.join(", ")} for ${mode} mode. ` +
        `Set connections.${id}.${mode}.${missing[0]}, or run this node in "fake" mode.`,
      { service, operation },
    );
  }

  const baseUrl = spec.baseUrl?.[mode] ?? options.baseUrls?.[mode];

  return { id, service, mode, credentials, ...(baseUrl ? { baseUrl } : {}) };
}

function hasAll(creds: ConnectionCredentials, keys: string[]): boolean {
  return keys.length > 0 && keys.every((key) => Boolean(creds[key]));
}

/**
 * The connector error taxonomy.
 *
 * Durable runs retry, and a retry policy needs to know WHICH KIND of failure it
 * is looking at. "Something went wrong" is not enough information to decide
 * between retrying, pausing for a human, and stopping — so every connector
 * failure is classified at the point it is known, which is inside the connector,
 * not three frames up where the type has already been lost.
 *
 * | class                    | retry? | why |
 * |--------------------------|--------|-----|
 * | `ConnectorConfigError`   | never  | nothing about a second attempt changes an unset key |
 * | `ConnectorAuthError`     | never  | the credential is wrong; hammering it gets accounts locked |
 * | `ConnectorRateLimited`   | yes    | after `retryAfter`, which the provider told us |
 * | `ConnectorTransient`     | yes    | 5xx, timeout, connection reset |
 * | `ConnectorRequestError`  | never  | 4xx we caused; the same request fails the same way |
 */

export type ConnectorErrorContext = {
  service: string;
  operation: string;
  /** HTTP status when there was one. */
  status?: number;
  /** The provider's own error code, when it publishes one. */
  providerCode?: string;
};

/** Base for everything below, so a host can catch the family in one clause. */
export class ConnectorError extends Error {
  readonly service: string;

  readonly operation: string;

  readonly status?: number;

  readonly providerCode?: string;

  /** Whether a second attempt could plausibly succeed. */
  readonly retryable: boolean = false;

  constructor(message: string, ctx: ConnectorErrorContext) {
    super(message);
    this.name = new.target.name;
    this.service = ctx.service;
    this.operation = ctx.operation;
    this.status = ctx.status;
    this.providerCode = ctx.providerCode;
  }
}

/**
 * A required piece of configuration is missing or unusable.
 *
 * The message must name the exact key the consumer has to set. "Stripe is not
 * configured" sends someone reading source; "no `secretKey` on the `stripe`
 * connection — set it via registerConnectionHost" sends them to the line.
 */
export class ConnectorConfigError extends ConnectorError {}

/** The provider rejected the credential. Retrying cannot help. */
export class ConnectorAuthError extends ConnectorError {
  override readonly retryable = false;
}

/** The provider asked us to slow down. */
export class ConnectorRateLimited extends ConnectorError {
  override readonly retryable = true;

  /** Seconds to wait, when the provider said. */
  readonly retryAfter?: number;

  constructor(message: string, ctx: ConnectorErrorContext & { retryAfter?: number }) {
    super(message, ctx);
    this.retryAfter = ctx.retryAfter;
  }
}

/** A 5xx, a timeout, a reset — the provider's problem, and it may pass. */
export class ConnectorTransient extends ConnectorError {
  override readonly retryable = true;
}

/** A 4xx we caused. The same request will fail the same way. */
export class ConnectorRequestError extends ConnectorError {
  override readonly retryable = false;
}

/**
 * Classify an HTTP response into the taxonomy.
 *
 * 429 before the 4xx sweep, deliberately: a rate limit is a 4xx and is the one
 * 4xx that IS worth retrying, so an ordering that checked `>= 400` first would
 * mark every throttle permanent and turn a busy minute into a failed run.
 */
export function classifyHttp(
  status: number,
  ctx: ConnectorErrorContext,
  body: string,
  retryAfter?: number,
): ConnectorError {
  const detail = body.trim() === "" ? "" : ` — ${truncate(body, 400)}`;
  const where = `${ctx.service}.${ctx.operation}`;

  if (status === 429) {
    return new ConnectorRateLimited(`${where}: rate limited by the provider${detail}`, {
      ...ctx,
      status,
      retryAfter,
    });
  }

  if (status === 401 || status === 403) {
    return new ConnectorAuthError(
      `${where}: the provider rejected the credential (${status})${detail}. ` +
        "Check the connection's credentials and that they match the mode you are running in — " +
        "a live key in sandbox, or the reverse, fails exactly like this.",
      { ...ctx, status },
    );
  }

  if (status >= 500) {
    return new ConnectorTransient(`${where}: provider returned ${status}${detail}`, { ...ctx, status });
  }

  return new ConnectorRequestError(`${where}: request rejected with ${status}${detail}`, { ...ctx, status });
}

function truncate(value: string, max: number): string {
  return value.length <= max ? value : `${value.slice(0, max)}…`;
}

/**
 * The faker layer — every connector ships one, always.
 *
 * ## Why every connector, and not just the ones without a sandbox
 *
 * A sandbox still needs an account, a key, a network, and a provider that is
 * up. That is four ways for someone evaluating the kit to get nothing working,
 * before they have learned anything about the kit. A faker removes all four:
 * vendor a node, drop it on a canvas, press run, see a shaped result.
 *
 * It is also what makes the golden fixtures honest. Fixtures run on both
 * runtimes and are the publish gate; if they needed a network they would either
 * be skipped in CI or be flaky, and a flaky gate is one people learn to
 * re-run rather than read.
 *
 * ## Deterministic, not random
 *
 * Same inputs, same output — always. A faker that returns a fresh uuid every
 * call cannot be asserted on, so its fixtures degrade to "it did not throw",
 * which is the assertion that catches nothing. Values here are derived from a
 * seed built out of the service, the operation and the request, so two runs
 * agree and two runtimes can be compared to each other.
 *
 * The values are obviously fake ON PURPOSE — `fake_`-prefixed ids, `example.test`
 * hosts, round numbers. Nobody should ever look at a faked result and wonder
 * whether it moved real money.
 */

/** A faker: one function per service, switching on the operation. */
export type ConnectorFaker = (operation: string, request: FakeRequest) => unknown;

export type FakeRequest = {
  /** The node's resolved config. */
  config: Record<string, unknown>;
  /** The value on the incoming wire. */
  input?: unknown;
  /** Deterministic helpers, seeded from service + operation + config. */
  fake: FakeValues;
};

/**
 * Deterministic value helpers handed to a faker.
 *
 * Small on purpose. A faker's job is to return the SHAPE the provider returns —
 * the field names a downstream node will reference — not to simulate the
 * provider's business logic.
 */
export type FakeValues = {
  /** A stable id with the provider's usual prefix: `id("ch")` → `ch_fake_1a2b3c`. */
  id: (prefix: string) => string;
  /** A stable integer in `[min, max]`. */
  int: (min: number, max: number) => number;
  /** Pick a stable element of a list. */
  pick: <T>(options: readonly T[]) => T;
  /** A fixed ISO-8601 instant, offset by whole seconds. Never `Date.now()`. */
  timestamp: (offsetSeconds?: number) => string;
  /** A stable lowercase hex string of `length` characters. */
  hex: (length: number) => string;
};

/**
 * The instant every faker counts from.
 *
 * A constant rather than the clock, because a fixture asserting on `createdAt`
 * must not start failing tomorrow. Chosen to be recognisably synthetic.
 */
export const FAKE_EPOCH = "2026-01-01T00:00:00.000Z";

/** FNV-1a. Small, dependency-free, and stable across both runtimes. */
export function seedFrom(...parts: unknown[]): number {
  const text = parts.map((part) => (typeof part === "string" ? part : stableJson(part))).join("|");
  let hash = 0x811c9dc5;

  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    // 32-bit FNV prime multiply, kept in range without BigInt.
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }

  return hash >>> 0;
}

/**
 * Key order must not change a seed.
 *
 * `JSON.stringify` preserves insertion order, so `{a,b}` and `{b,a}` would hash
 * differently and the "same inputs, same output" promise would hold only for
 * objects that happened to be built in the same order — which is exactly the
 * kind of almost-true that survives review and fails in a fixture months later.
 */
function stableJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;

  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([k, v]) => `${JSON.stringify(k)}:${stableJson(v)}`);

  return `{${entries.join(",")}}`;
}

/** Build the deterministic helpers for one faked call. */
export function fakeValues(seed: number): FakeValues {
  // A tiny xorshift, advanced per call so successive helpers differ while the
  // whole sequence stays a pure function of the seed.
  let state = seed || 0x9e3779b9;
  const next = (): number => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;

    return state;
  };

  const hex = (length: number): string => {
    let out = "";
    while (out.length < length) out += next().toString(16).padStart(8, "0");

    return out.slice(0, length);
  };

  return {
    hex,
    id: (prefix: string) => `${prefix}_fake_${hex(12)}`,
    int: (min: number, max: number) => min + (next() % Math.max(1, max - min + 1)),
    pick: <T>(options: readonly T[]): T => options[next() % options.length] as T,
    timestamp: (offsetSeconds = 0) =>
      new Date(Date.parse(FAKE_EPOCH) + offsetSeconds * 1000).toISOString(),
  };
}

/** Build the request handed to a faker, with helpers already seeded. */
export function fakeRequest(
  service: string,
  operation: string,
  config: Record<string, unknown>,
  input?: unknown,
): FakeRequest {
  return { config, input, fake: fakeValues(seedFrom(service, operation, config)) };
}

/**
 * Deriving an idempotency key — and being honest when we cannot.
 *
 * ## The gap this works around
 *
 * A durable run RETRIES. For a writing connector that is only survivable if the
 * retry carries the same idempotency key the first attempt did, so the provider
 * returns the original result instead of creating a second charge, a second
 * refund, a second message.
 *
 * **Neither engine's execution context carries a run identity today.** The TS
 * `ctx` is `{ node, inputs, emit, abort }`; `FancyFlow\Runtime\ExecutionContext`
 * is the same four plus `depth`. There is no run key, no attempt number, nothing
 * a node can key on — checked against fancy-flow 0.45.0 and fancy-flow-php
 * 0.17.0 rather than assumed.
 *
 * So this reads the conventional places a host might put one, and returns
 * `null` when there is none.
 *
 * ## Why the two obvious fallbacks are both wrong
 *
 * - **The node id alone** is stable across retries — and also across different
 *   runs. Two legitimate payments for the same customer would share a key, and
 *   the second would be silently deduplicated into the first. A payment that
 *   never happened, reported as success.
 * - **A fresh random value** is unique per run — and also per attempt. A retry
 *   would create a second charge, which is the whole thing we are avoiding.
 *
 * Both are worse than no key. So with no run identity a connector sends none
 * and stays `unsafe-to-replay`, which pins it to a single attempt under the
 * per-node queue driver. Fewer retries, no double writes.
 */

/** Where a host may publish the run key. Checked in order. */
export function runKeyFrom(ctx: unknown): string | null {
  const bag = ctx as Record<string, any> | null;
  if (!bag) return null;

  const candidates = [
    bag.runKey,
    bag.run?.key,
    bag.runId,
    // A host with no engine support can seed it as an initial input, which the
    // engine merges into every node's inputs.
    bag.inputs?.__runKey,
  ];

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim() !== "") return candidate.trim();
  }

  return null;
}

/**
 * The idempotency key for one node in one run, or `null`.
 *
 * `null` is a legitimate answer and callers must treat it as one — passing it
 * through means "send no idempotency header", not "make something up".
 */
export function idempotencyKeyFor(ctx: unknown, nodeId: string): string | null {
  const run = runKeyFrom(ctx);

  return run === null ? null : `${run}:${nodeId}`;
}

/**
 * The warning a node emits when it is about to write without a key.
 *
 * Said out loud, at the moment it matters, because the failure it precedes is
 * invisible: the run succeeds, the retry succeeds, and there are two charges.
 */
export const NO_IDEMPOTENCY_KEY_WARNING =
  "no run identity available, so this write is being sent WITHOUT an idempotency key. " +
  "A retry would repeat the effect rather than recover from it — the node is marked " +
  "unsafe-to-replay, so a durable runner will give it one attempt. To enable safe retries, " +
  "seed a stable `__runKey` into the run's initial inputs.";

/**
 * The shared connector runtime, for hosts that EXECUTE on TypeScript.
 *
 * Vendored, not installed: this directory is copied into a consumer's project
 * alongside the first connector node they add, and every connector after that
 * reuses it. There is no package to require — that is the whole point of the
 * node marketplace, and a shared runtime that arrived as a dependency would
 * undo it.
 */

export * from "./client";
export * from "./connection";
export * from "./errors";
export * from "./faker";
export * from "./mode";
export * from "./trigger";
export * from "./webhook";

/**
 * Which copy of a provider a connector talks to — and who decides.
 *
 * Three modes, and the third is the one that makes this marketplace usable:
 *
 * | mode      | talks to                    | needs credentials | needs network |
 * |-----------|-----------------------------|-------------------|---------------|
 * | `live`    | the provider, for real      | yes               | yes           |
 * | `sandbox` | the provider's test estate  | yes (test ones)   | yes           |
 * | `fake`    | the node's own faker        | no                | no            |
 *
 * ## The environment is the DEFAULT, never the constraint
 *
 * A locally-hosted project defaults to sandbox. It is not *pinned* to sandbox:
 * an author who explicitly asks for `live` on their laptop gets `live`, because
 * the alternative — an environment that silently overrides a stated intention —
 * produces the worst outcome available here, which is a workflow that reports
 * success while having charged nobody. Equally, `sandbox` set explicitly stays
 * sandbox in production, which is how you stage a connector before cutting it
 * over.
 *
 * So: explicit beats the connection, the connection beats the environment.
 *
 * ## Why "fake" is a MODE and not a test double
 *
 * Every connector ships a faker (see `faker.ts`), and it is reachable the same
 * way in a test, in a demo and on a laptop with no credentials. Making it a
 * separate mechanism — a mock injected only under test — would mean the code
 * path a consumer develops against is not the one that runs, and the fixtures
 * would prove nothing about the executor.
 */

/** The three environments a connector node can run against. */
export type ConnectorMode = "fake" | "sandbox" | "live";

/** What a node's `mode` config field may say. `auto` means "let the rules decide". */
export type RequestedMode = ConnectorMode | "auto";

export const CONNECTOR_MODES: ConnectorMode[] = ["fake", "sandbox", "live"];

/**
 * How a provider exposes its test estate — the four shapes that actually exist.
 *
 * This is data, not per-node code, because getting it wrong is the difference
 * between hitting a test ledger and hitting a real one. Verified per provider in
 * `.ai/plans/fancy-flow-connector-nodes.md`; a node declares which of the four
 * it is and the core does the rest.
 *
 * - `credential` — same base URL, a test-scoped key selects the estate
 *   (Stripe's `sk_test_…`). The trap: pointing a live key at it works, so the
 *   only guard is the key itself.
 * - `base-url` — a different host entirely (PayPal's `api-m.sandbox.paypal.com`).
 * - `separate-account` — a distinct tenant you must create, often with its own
 *   login host (Salesforce sandbox orgs on `test.salesforce.com`).
 * - `none` — the provider has no test estate. `sandbox` is then not offered at
 *   all, and the node's honest choices are `fake` and `live`.
 */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

/** The host's view of where it is running. Kept tiny so it is trivial to fake. */
export type HostEnvironment = {
  /** True only in a real production deployment. Everything else is "local". */
  production: boolean;
};

export type ModeInputs = {
  /** What the node's config asked for. `undefined` / `"auto"` means "decide". */
  requested?: RequestedMode | null;
  /** A mode pinned on the CONNECTION, if the host pinned one. */
  connectionMode?: ConnectorMode | null;
  /** Whether the provider has a test estate at all. */
  sandbox: SandboxKind;
  /** Whether the connection actually carries credentials for the sandbox estate. */
  hasSandboxCredentials: boolean;
  environment: HostEnvironment;
};

/**
 * Resolve the mode a connector call runs in.
 *
 * Deliberately a pure function of stated facts, so both runtimes can be held to
 * the same table of cases and a host can unit-test its own wiring without a
 * network or a provider.
 */
export function resolveConnectorMode(inputs: ModeInputs): ConnectorMode {
  const { requested, connectionMode, sandbox, hasSandboxCredentials, environment } = inputs;

  // 1. An explicit ask wins everywhere. This is the rule that makes the
  //    environment a default rather than a cage.
  if (requested && requested !== "auto") {
    if (requested === "sandbox" && sandbox === "none") {
      throw new ConnectorModeError(
        'This connector\'s provider has no sandbox estate, so "sandbox" cannot be honoured. ' +
          'Use "fake" to develop without credentials, or "live" to talk to the provider.',
      );
    }

    return requested;
  }

  // 2. A mode pinned on the connection. One place per service, which is the
  //    whole reason connections exist as a separate thing.
  if (connectionMode) return connectionMode;

  // 3. Otherwise the environment decides.
  if (environment.production) return "live";

  // Local: prefer the provider's own test estate when it exists AND is wired.
  // Falling through to `fake` when it is not is what makes a freshly vendored
  // node runnable with no setup at all — the difference between a marketplace
  // you can try and one you can only read about.
  return sandbox !== "none" && hasSandboxCredentials ? "sandbox" : "fake";
}

/** Raised when a requested mode cannot be honoured. Never downgraded silently. */
export class ConnectorModeError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ConnectorModeError";
  }
}

/** True when the mode reaches the provider over the network. */
export function isRemote(mode: ConnectorMode): boolean {
  return mode !== "fake";
}

/**
 * How a connector trigger learns that something happened.
 *
 * **Not every provider pushes, and assuming webhooks is the single most common
 * way a connector catalogue ends up lying.** Google Drive and Microsoft Graph
 * want a *subscription* you must renew before it expires. Salesforce wants a
 * Pub/Sub or CometD stream. S3 wants an event notification routed to
 * infrastructure the consumer provisions. Reddit wants you to poll. Each of
 * those is a different obligation on the host, and a node that declared
 * "webhook" for all of them would install cleanly and then never fire.
 *
 * So a trigger declares its delivery mechanism, and the host can refuse to mount
 * one it has no machinery for — at author time, not at 3am.
 */

import type { ResolvedConnection } from "./connection";
import type { ConnectorFaker } from "./faker";
import { fakeRequest } from "./faker";
import type { HmacScheme, WebhookVerification } from "./webhook";
import { header, verifyHmac } from "./webhook";

/**
 * The delivery mechanisms that actually exist in the wild.
 *
 * - `webhook` — the provider POSTs to a URL you own. Verify the signature.
 * - `subscription` — a webhook that EXPIRES. Someone has to renew it, forever,
 *   and if nobody does the workflow stops firing without an error anywhere.
 *   Distinct from `webhook` precisely because that ongoing duty is invisible.
 * - `poll` — you ask, on a schedule, and track a cursor.
 * - `pubsub` — the provider publishes to a broker (Google Pub/Sub, Salesforce
 *   Pub/Sub API, SNS/SQS) that the consumer must provision.
 * - `stream` — a long-lived connection the host maintains (websocket, gRPC,
 *   SSE, CometD).
 */
export type DeliveryMechanism = "webhook" | "subscription" | "poll" | "pubsub" | "stream";

export type TriggerDescriptor = {
  service: string;
  operation: string;
  delivery: DeliveryMechanism;
  /**
   * What the host has to do before this fires, in one sentence, aimed at the
   * person who has to do it. Surfaced by the editor and by the MCP, because a
   * trigger whose setup is undocumented is a trigger that silently never fires.
   */
  setup: string;
  /** For `subscription`: how long the provider keeps it alive, in seconds. */
  subscriptionTtl?: number;
  /** For `webhook` / `subscription`: how a delivery is authenticated. */
  verification?: WebhookVerificationSpec;
  /** For `poll`: the provider's smallest sane interval, in seconds. */
  minPollSeconds?: number;
  /** A faked sample event, so the node is runnable before any of the above. */
  faker: ConnectorFaker;
};

export type WebhookVerificationSpec = {
  /** Header carrying the signature. */
  signatureHeader: string;
  /** Header carrying the timestamp, when the scheme signs one. */
  timestampHeader?: string;
  scheme: HmacScheme;
  /**
   * Some schemes pack the timestamp INTO the signature header
   * (Stripe: `t=…,v1=…`). Given the raw header value, return the parts.
   */
  parse?: (raw: string) => { signature?: string; timestamp?: string };
};

export type InboundDelivery = {
  /** The body EXACTLY as received. Not re-serialised. See `webhook.ts`. */
  raw: string;
  headers: Record<string, string | string[] | undefined>;
};

/**
 * Verify an inbound delivery against a trigger's declared scheme.
 *
 * A trigger with no `verification` REFUSES rather than accepts. That asymmetry
 * is the whole safety property: an unverifiable endpoint is a stranger's button
 * for starting workflows in your account, and defaulting to "allow" would make
 * every misconfiguration into an open door that looks shut.
 */
export async function verifyDelivery(
  trigger: TriggerDescriptor,
  delivery: InboundDelivery,
  secret: string | undefined,
  now?: number,
): Promise<WebhookVerification> {
  const spec = trigger.verification;

  if (!spec) {
    return {
      ok: false,
      reason: `${trigger.service}.${trigger.operation} declares no signature scheme, so a delivery cannot be trusted.`,
    };
  }

  const rawHeader = header(delivery.headers, spec.signatureHeader);
  const parsed = spec.parse && rawHeader ? spec.parse(rawHeader) : { signature: rawHeader };
  const timestamp = parsed.timestamp
    ?? (spec.timestampHeader ? header(delivery.headers, spec.timestampHeader) : undefined);

  return verifyHmac({
    raw: delivery.raw,
    signature: parsed.signature,
    secret,
    scheme: spec.scheme,
    timestamp,
    ...(now === undefined ? {} : { now }),
  });
}

/**
 * The event a trigger node publishes when it runs.
 *
 * Three sources, in order, and the third is why a connector trigger is usable
 * on day one:
 *
 * 1. A verified delivery the host injected on the `in` port.
 * 2. Nothing injected, but the connection is remote — that is a host wiring
 *    error, and it fails loudly rather than emitting a plausible blank.
 * 3. `fake` mode — the trigger emits its own sample event, so an author can
 *    press Run, see the real field names, and wire the downstream nodes against
 *    them before the provider has ever been contacted.
 */
export function triggerEvent(
  trigger: TriggerDescriptor,
  connection: ResolvedConnection,
  injected: unknown,
  config: Record<string, unknown>,
): unknown {
  if (hasDelivery(injected)) return injected;

  if (connection.mode === "fake") {
    return trigger.faker(
      trigger.operation,
      fakeRequest(trigger.service, trigger.operation, config),
    );
  }

  throw new Error(
    `${trigger.service}.${trigger.operation}: no event was delivered to this trigger. ` +
      `Its delivery mechanism is "${trigger.delivery}" — ${trigger.setup} ` +
      'Set the node\'s mode to "fake" to design against a sample event instead.',
  );
}

/**
 * Whether a value on the `in` port is an actual delivery.
 *
 * An EMPTY object or array counts as nothing delivered, and that is not
 * fussiness: a manually started run seeds `{}` on the trigger's input, so a
 * bare null check would hand the executor an empty envelope and call it an
 * event. Downstream every field would be `null`, the run would be green, and
 * nothing would say the trigger never fired.
 */
function hasDelivery(value: unknown): boolean {
  if (value === undefined || value === null) return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "object") return Object.keys(value as object).length > 0;

  return true;
}

/**
 * Verifying an inbound provider webhook.
 *
 * An unverified webhook endpoint is a public, unauthenticated way to start a
 * workflow in someone's account — which is to say, a way for a stranger to make
 * your app refund an order or post to your Slack. So verification is part of the
 * connector pattern rather than an exercise for the host: a trigger node that
 * cannot verify its deliveries must say so, and a host must not be able to mount
 * one by accident.
 *
 * ## The three things every provider's scheme actually needs
 *
 * Providers differ in header names and in what exactly gets signed, and almost
 * nothing else:
 *
 * 1. **The RAW body.** Signatures are computed over bytes. Re-serialising parsed
 *    JSON changes key order and whitespace and produces a signature mismatch
 *    that looks like a wrong secret. The host must pass the body it received.
 * 2. **A constant-time comparison.** `===` on a signature leaks, through timing,
 *    which prefix was right. That is a real forgery path, not a theoretical one.
 * 3. **A timestamp tolerance.** Without it a valid signature is valid forever,
 *    so anyone who ever saw one delivery can replay it whenever they like.
 *
 * WebCrypto rather than `node:crypto`, so the same file runs on Node, Bun, Deno
 * and an edge runtime. Node 22 is the suite's floor and has it globally.
 */

export type WebhookVerification =
  | { ok: true }
  | { ok: false; reason: string };

export type HmacScheme = {
  /** Hash to use. */
  algorithm: "SHA-256" | "SHA-1" | "SHA-512";
  /**
   * Build the exact string that gets signed. Providers differ here more than
   * anywhere else — Stripe signs `${timestamp}.${body}`, Slack signs
   * `v0:${timestamp}:${body}`, GitHub signs the body alone.
   */
  payload: (raw: string, timestamp?: string) => string;
  /** Seconds a delivery stays acceptable. */
  tolerance?: number;
  /** Encoding of the signature the provider sends. */
  encoding?: "hex" | "base64";
};

/**
 * Verify an HMAC-signed delivery.
 *
 * Returns a RESULT rather than throwing, and the failure carries a reason: a
 * host wants to log which check failed (stale? wrong secret? no header?) while
 * still answering the provider with an opaque 400.
 */
export async function verifyHmac(options: {
  raw: string;
  signature: string | undefined;
  secret: string | undefined;
  scheme: HmacScheme;
  timestamp?: string;
  /** Seconds since the epoch. Injected so tests are not clock-dependent. */
  now?: number;
}): Promise<WebhookVerification> {
  const { raw, signature, secret, scheme, timestamp } = options;

  if (!secret) {
    // Never "accept when unconfigured". An endpoint that verifies nothing
    // because nobody set a secret is strictly worse than one that is off: it
    // looks protected.
    return { ok: false, reason: "no signing secret configured for this trigger" };
  }
  if (!signature) return { ok: false, reason: "delivery carried no signature header" };

  if (scheme.tolerance !== undefined) {
    if (!timestamp) return { ok: false, reason: "delivery carried no timestamp header" };

    const sent = Number(timestamp);
    if (!Number.isFinite(sent)) return { ok: false, reason: "timestamp header is not a number" };

    const now = options.now ?? Math.floor(Date.now() / 1000);
    if (Math.abs(now - sent) > scheme.tolerance) {
      return { ok: false, reason: `delivery is outside the ${scheme.tolerance}s replay window` };
    }
  }

  const expected = await hmac(secret, scheme.payload(raw, timestamp), scheme.algorithm, scheme.encoding ?? "hex");

  return constantTimeEquals(expected, signature)
    ? { ok: true }
    : { ok: false, reason: "signature did not match" };
}

/** HMAC of `payload` under `secret`, hex or base64 encoded. */
export async function hmac(
  secret: string,
  payload: string,
  algorithm: HmacScheme["algorithm"],
  encoding: "hex" | "base64" = "hex",
): Promise<string> {
  const subtle = globalThis.crypto?.subtle;

  if (!subtle) {
    throw new Error(
      "WebCrypto is not available in this runtime, so webhook signatures cannot be verified. " +
        "Refusing to accept deliveries unverified.",
    );
  }

  const encoder = new TextEncoder();
  const key = await subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: algorithm },
    false,
    ["sign"],
  );
  const bytes = new Uint8Array(await subtle.sign("HMAC", key, encoder.encode(payload)));

  if (encoding === "base64") {
    let binary = "";
    bytes.forEach((byte) => {
      binary += String.fromCharCode(byte);
    });

    return btoa(binary);
  }

  return Array.from(bytes)
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Compare two strings without leaking where they diverge.
 *
 * The length check first is deliberate and safe: a signature's length is fixed
 * by its algorithm and is not a secret, so revealing a mismatch there tells an
 * attacker nothing they could not compute.
 */
export function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) return false;

  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);

  return diff === 0;
}

/**
 * Pull one header case-insensitively.
 *
 * Header case is not preserved consistently across proxies, frameworks and
 * runtimes; a connector that read `req.headers["Stripe-Signature"]` would work
 * behind one server and reject every delivery behind another.
 */
export function header(headers: Record<string, string | string[] | undefined>, name: string): string | undefined {
  const wanted = name.toLowerCase();

  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() !== wanted) continue;

    return Array.isArray(value) ? value[0] : value;
  }

  return undefined;
}

/**
 * Stripe's identity on the authoring surface, shared by every Stripe node.
 *
 * `ui/` lands on EVERY host — a PHP project vendors `ui/` and `php/` and never
 * `js/` — so this file must import nothing from `js/`. The vendoring test in
 * `tests/js/flow-nodes/vendoring.test.ts` fails the build if it does, because
 * that import is a dangling module the moment the node is copied for PHP.
 */

import type { ConnectorMeta } from "../../_connector/ui/connector";

/** The parts of a connector's identity that belong to the SERVICE, not the node. */
export const STRIPE_SERVICE = {
  service: "stripe",
  serviceTitle: "Stripe",
  domain: "payments",
  sandbox: "credential",
} as const satisfies Pick<ConnectorMeta, "service" | "serviceTitle" | "domain" | "sandbox">;

/** Build a Stripe node's connector metadata from the operation it performs. */
export function stripeMeta(
  role: ConnectorMeta["role"],
  operation: string,
  docs: string,
): ConnectorMeta {
  return { ...STRIPE_SERVICE, role, operation, docs };
}

/**
 * Stripe, as one service descriptor shared by every Stripe node.
 *
 * ## Why a per-service shared directory
 *
 * `_connector` carries what is true of ALL connectors. This carries what is
 * true of Stripe: its base URL, its auth scheme, its idempotency header, its
 * webhook signature format, and its faker. Six Stripe nodes would otherwise
 * retype all of that six times, and the day Stripe changes something, five of
 * the six would keep the old answer.
 *
 * Vendoring any Stripe node copies `_connector` and `_stripe` alongside it. Both
 * are source in the consumer's project, editable in place, and neither is a
 * package.
 *
 * ## The sandbox trap, written down where it is used
 *
 * Stripe's test estate is selected by the KEY, not by the URL —
 * `api.stripe.com` serves both. So a live key sent to a node whose mode says
 * "sandbox" reaches the real ledger and succeeds. Nothing in the request
 * distinguishes them; the only guard is which credential the connection holds,
 * which is exactly why credentials sit on the connection rather than on twelve
 * separate nodes.
 */

import type { ConnectorFaker, FakeRequest } from "../../_connector/js/faker";
import type { ServiceDescriptor } from "../../_connector/js/client";
import type { HmacScheme } from "../../_connector/js/webhook";

const API = "https://api.stripe.com";

/**
 * Stripe's webhook signature scheme.
 *
 * `Stripe-Signature: t=1700000000,v1=<hex>`, where the signed payload is
 * `${t}.${rawBody}` under HMAC-SHA256, and the default replay window is five
 * minutes. The timestamp travels INSIDE the signature header rather than in one
 * of its own, which is why `verification.parse` exists.
 */
export const STRIPE_SIGNATURE_SCHEME: HmacScheme = {
  algorithm: "SHA-256",
  payload: (raw, timestamp) => `${timestamp}.${raw}`,
  tolerance: 300,
  encoding: "hex",
};

/** Split `t=…,v1=…` into its parts. Unknown schemes (`v0=…`) are ignored. */
export function parseStripeSignature(raw: string): { signature?: string; timestamp?: string } {
  const parts = raw.split(",").map((part) => part.trim());
  const result: { signature?: string; timestamp?: string } = {};

  for (const part of parts) {
    const [key, value] = part.split("=", 2);
    if (key === "t") result.timestamp = value;
    // Stripe may send several `v1` signatures during a secret rotation. Taking
    // the first is what the verification loop expects; a rotation window is
    // rare enough that failing over to a second is not worth the ambiguity of
    // "which one matched".
    if (key === "v1" && !result.signature) result.signature = value;
  }

  return result;
}

/**
 * The faker.
 *
 * Shapes, not behaviour: the goal is that a downstream node sees the field
 * NAMES Stripe actually publishes, so an author can wire `{{ $json.data.id }}`
 * against a fake and have it keep working against the real thing. Amounts and
 * ids are deterministic, and every value is visibly synthetic.
 */
export const stripeFaker: ConnectorFaker = (operation, request) => {
  const { fake, config } = request;

  switch (operation) {
    case "payment_intent_create":
      return paymentIntent(config, fake);

    case "refund_create":
      return {
        id: fake.id("re"),
        object: "refund",
        amount: Number(config.amount ?? 0) || fake.int(500, 25000),
        currency: String(config.currency ?? "usd"),
        payment_intent: String(config.paymentIntent ?? fake.id("pi")),
        reason: config.reason ? String(config.reason) : null,
        status: "succeeded",
        created: 1767225600,
      };

    case "customer_create":
      return {
        id: fake.id("cus"),
        object: "customer",
        email: String(config.email ?? "ada@example.test"),
        name: config.name ? String(config.name) : null,
        created: 1767225600,
        livemode: false,
      };

    default:
      // A faker asked for an operation it has no shape for must SAY so. Making
      // something up would produce a green run whose output silently has none
      // of the fields the author is about to reference.
      throw new Error(
        `stripe: no fake response is defined for "${operation}". ` +
          "Add one to stripeFaker before shipping a node that calls it — a connector without a faker " +
          "cannot be developed against, tested, or demonstrated.",
      );
  }
};

function paymentIntent(config: Record<string, unknown>, fake: FakeRequest["fake"]) {
  const amount = Number(config.amount ?? 0) || fake.int(500, 25000);

  return {
    id: fake.id("pi"),
    object: "payment_intent",
    amount,
    amount_received: amount,
    currency: String(config.currency ?? "usd"),
    customer: config.customer ? String(config.customer) : null,
    description: config.description ? String(config.description) : null,
    status: "succeeded",
    // `livemode: false` is not decoration. It is the field a downstream branch
    // reads to refuse to act on test data, and a faker that reported `true`
    // would make that branch untestable.
    livemode: false,
    created: 1767225600,
    latest_charge: fake.id("ch"),
    receipt_email: config.receiptEmail ? String(config.receiptEmail) : null,
  };
}

/** The Stripe service, for the TypeScript runtime. */
export const STRIPE: ServiceDescriptor = {
  service: "stripe",
  title: "Stripe",
  // Same host for both estates — the key decides. See the note at the top.
  sandbox: "credential",
  baseUrls: { live: API, sandbox: API },
  requires: ["secretKey"],
  // Bearer, not Basic. Stripe accepts the key as a Basic username too, and both
  // are documented, but one spelling in one place is one fewer thing to get
  // subtly wrong.
  authorize: (credentials, request) => {
    request.headers.Authorization = `Bearer ${credentials.secretKey}`;
  },
  // Retried durable runs MUST not create a second charge. This is the header
  // that makes `unsafe-to-replay` recoverable rather than merely forbidden.
  idempotencyHeader: "Idempotency-Key",
  faker: stripeFaker,
};

/**
 * Stripe's webhook trigger — the delivery contract, shared by its trigger nodes.
 *
 * Kept beside the service descriptor rather than inside a node, because a
 * signature scheme is a fact about STRIPE. Two Stripe triggers must not be able
 * to disagree about how a delivery is verified.
 */

import type { ConnectorFaker } from "../../_connector/js/faker";
import type { InboundDelivery, TriggerDescriptor } from "../../_connector/js/trigger";
import { verifyDelivery } from "../../_connector/js/trigger";
import type { WebhookVerification } from "../../_connector/js/webhook";
import { parseStripeSignature, STRIPE_SIGNATURE_SCHEME } from "./service";

/**
 * A sample event per type.
 *
 * The point is the SHAPE — an author wiring `{{ $json.data.object.amount }}`
 * against a fake must find the same path when a real delivery arrives. So these
 * mirror Stripe's envelope exactly: `id`, `type`, `created`, `livemode`, and the
 * object under `data.object`.
 */
export const stripeEventFaker: ConnectorFaker = (operation, request) => {
  const { fake, config } = request;
  const type = String(config.sample ?? "payment_intent.succeeded");

  const object = (() => {
    switch (type) {
      case "charge.refunded":
        return {
          id: fake.id("ch"),
          object: "charge",
          amount: 2500,
          amount_refunded: 2500,
          currency: "usd",
          status: "succeeded",
          refunded: true,
        };
      case "checkout.session.completed":
        return {
          id: fake.id("cs"),
          object: "checkout.session",
          amount_total: 2500,
          currency: "usd",
          status: "complete",
          payment_status: "paid",
          customer_email: "ada@example.test",
        };
      case "customer.subscription.deleted":
        return {
          id: fake.id("sub"),
          object: "subscription",
          status: "canceled",
          customer: fake.id("cus"),
          canceled_at: 1767225600,
        };
      default:
        return {
          id: fake.id("pi"),
          object: "payment_intent",
          amount: 2500,
          amount_received: 2500,
          currency: "usd",
          status: "succeeded",
        };
    }
  })();

  return {
    id: fake.id("evt"),
    object: "event",
    type,
    api_version: "2026-01-01",
    created: 1767225600,
    // Never `true`. A faked event that claimed to be live money would make the
    // downstream guard — "only act when livemode" — untestable, which is the
    // one branch you most want covered.
    livemode: false,
    data: { object },
  };
};

export const STRIPE_WEBHOOK_TRIGGER: TriggerDescriptor = {
  service: "stripe",
  operation: "webhook",
  delivery: "webhook",
  setup:
    "Add an endpoint in the Stripe dashboard (or via POST /v1/webhook_endpoints) pointing at the route your " +
    "host mounts for this trigger, then put the endpoint's signing secret on the connection as `webhookSecret`.",
  verification: {
    signatureHeader: "Stripe-Signature",
    scheme: STRIPE_SIGNATURE_SCHEME,
    // Stripe packs the timestamp INTO the signature header (`t=…,v1=…`) rather
    // than sending one of its own, so it has to be parsed out before the HMAC
    // can be computed over `{t}.{body}`.
    parse: parseStripeSignature,
  },
  faker: stripeEventFaker,
};

/**
 * Verify one inbound Stripe delivery.
 *
 * The host calls this BEFORE starting a run, with the body exactly as received.
 * Re-serialised JSON changes key order and whitespace, and produces a mismatch
 * that looks precisely like a wrong secret — hours of debugging the wrong thing.
 */
export function verifyStripeDelivery(
  delivery: InboundDelivery,
  webhookSecret: string | undefined,
  now?: number,
): Promise<WebhookVerification> {
  return verifyDelivery(STRIPE_WEBHOOK_TRIGGER, delivery, webhookSecret, now);
}

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";

import { resolveConnection } from "../../_connector/js/connection";
import { triggerEvent } from "../../_connector/js/trigger";
import { STRIPE_WEBHOOK_TRIGGER } from "../../_stripe/js/trigger";

/**
 * Publish the Stripe event that started this run.
 *
 * ## A trigger executor does not receive the webhook
 *
 * The HOST does. It owns the route, verifies the signature (see
 * `verifyStripeDelivery`), and injects the verified event on this node's `in`
 * port before starting the run. By the time this runs, the delivery is already
 * trusted — which is why there is no verification here and must not be: a
 * check that runs after the graph has started is a check that has already
 * failed.
 *
 * In `fake` mode there is no host and no delivery, so the trigger emits its own
 * sample event. That is what makes the node runnable on a canvas the moment it
 * is vendored, with the same field names a real delivery carries.
 */
export const stripeWebhookTriggerExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;

  const connection = resolveConnection({
    service: "stripe",
    operation: "webhook",
    connectionId: typeof config.connection === "string" ? config.connection : null,
    requested: (config.mode as never) ?? null,
    sandbox: "credential",
    // A trigger authenticates DELIVERIES, not outbound calls, so the secret it
    // needs is the endpoint's signing secret rather than the API key.
    requires: ["webhookSecret"],
  });

  const event = triggerEvent(STRIPE_WEBHOOK_TRIGGER, connection, ctx.inputs?.in, config) as {
    type?: string;
  };

  const wanted = String(config.eventTypes ?? "")
    .split(",")
    .map((type) => type.trim())
    .filter(Boolean);

  if (wanted.length > 0 && event.type && !wanted.includes(event.type)) {
    // Settle WITHOUT activating the port: the delivery was legitimate, it just
    // is not one this workflow acts on. Throwing would turn Stripe's normal
    // fan-out of event types into a wall of failed runs, and every one of them
    // would look like an incident.
    ctx.emit({
      type: "log",
      level: "info",
      nodeId: ctx.node.id,
      message: `stripe_webhook_trigger: ignoring ${event.type} — not in the configured event types`,
    });

    return { __port: "ignored", value: event };
  }

  return { __port: "out", value: event };
};

import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { stripeWebhookTriggerKind } from "../ui/kind";
import { stripeWebhookTriggerExecutor } from "./executor";

/** The kind with its TypeScript executor attached — for hosts that EXECUTE on TS. */
export const stripeWebhookTriggerRunnableKind: NodeKindDefinition = {
  ...stripeWebhookTriggerKind,
  executor: stripeWebhookTriggerExecutor,
};

/**
 * The authoring surface every connector node shares.
 *
 * ## The model, and where it came from
 *
 * IFTTT's authoring UX is the one non-engineers actually complete, and three of
 * its four ideas map onto fancy-flow without distortion:
 *
 * 1. **Service first, then capability.** You pick Stripe, *then* pick what about
 *    Stripe. Not a flat wall of four hundred nodes. Here that lives in the
 *    registry — `connector.service` groups a provider's nodes, and the listing
 *    tools narrow in two steps.
 * 2. **The connection is a thing, not a field.** You authorize a service once
 *    and every applet reuses it. Here: `connection.ts` in the runtime, and the
 *    single `connection` config field below.
 * 3. **Ingredients.** A trigger's output fields become named tokens you drop
 *    into a downstream action's fields. fancy-flow already has the machinery —
 *    `outputShape` on the kind, `availableVariables()` reading it off direct
 *    predecessors — so a connector's job is simply to DECLARE its shape. See
 *    `ingredients.ts`.
 * 4. **A sentence, not a form dump.** `summarize()` below.
 *
 * ## Where it does NOT map, and what we did instead
 *
 * An IFTTT applet is one trigger and one action, so "the ingredients" is
 * unambiguous: there is only one upstream. A fancy-flow graph branches, fans
 * out, merges and nests, so a connector node several hops downstream has no
 * single trigger to draw from — `availableVariables()` deliberately offers only
 * DIRECT predecessors, because a grandparent's field resolves to `null` at run
 * time and a suggestion that silently produces nothing is worse than no
 * suggestion.
 *
 * We did not paper over that. Connector triggers publish their event as a
 * single object with a declared shape, so the natural thing an author does —
 * carry it forward on the wire — keeps the ingredients available at each step.
 * Reaching further up the graph is a fancy-flow concern, recorded as a finding
 * rather than reimplemented per node.
 */

import type { ConfigField, NodeKindDefinition, OutputField } from "@particle-academy/fancy-flow/engine";

/** The domains the catalogue is grouped by. Mirrors the plan's taxonomy. */
export type ConnectorDomain =
  | "payments"
  | "commerce"
  | "messaging"
  | "email"
  | "crm"
  | "support"
  | "storage"
  | "calendar"
  | "productivity"
  | "database"
  | "devtools"
  | "analytics"
  | "marketing"
  | "ai"
  | "forms"
  | "hr"
  | "geo";

/** What a connector node does in the graph — IFTTT's "this" versus "that". */
export type ConnectorRole = "trigger" | "action" | "search";

/** How the provider exposes a test estate. Kept in step with the runtime's `SandboxKind`. */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

export type ConnectorMeta = {
  service: string;
  serviceTitle: string;
  domain: ConnectorDomain;
  role: ConnectorRole;
  /** The provider's name for this operation, so search finds what people type. */
  operation: string;
  sandbox: SandboxKind;
  /** Link to the provider documentation this node was written against. */
  docs?: string;
};

/**
 * The two fields EVERY connector node carries, in the same order, with the same
 * keys.
 *
 * Uniformity is the feature. An agent that has configured one connector has
 * configured all of them, and a human who has learned where the sandbox switch
 * lives never has to look for it again.
 */
export function connectionFields(meta: ConnectorMeta): ConfigField[] {
  const modes: Array<{ value: string; label: string }> = [
    { value: "auto", label: "Auto — sandbox locally, live in production" },
    { value: "fake", label: "Fake — no credentials, no network" },
  ];

  // Only offer sandbox where one exists. A select listing a mode the provider
  // does not have is an invitation to pick it and then read an error.
  if (meta.sandbox !== "none") {
    modes.push({ value: "sandbox", label: sandboxLabel(meta.sandbox) });
  }
  modes.push({ value: "live", label: "Live — the real account" });

  return [
    {
      type: "credential",
      key: "connection",
      label: `${meta.serviceTitle} connection`,
      credentialType: `connector:${meta.service}`,
      description:
        `Which configured ${meta.serviceTitle} connection to use. Credentials live in the host's ` +
        "configuration, never in the workflow — a graph is exported, committed and handed to agents.",
    },
    {
      type: "select",
      key: "mode",
      label: "Environment",
      options: modes,
      default: "auto",
      description:
        meta.sandbox === "none"
          ? `${meta.serviceTitle} has no sandbox estate, so "auto" means fake locally and live in production.`
          : "Auto follows the environment. Setting this explicitly overrides it everywhere, including in production.",
    },
  ];
}

function sandboxLabel(kind: SandboxKind): string {
  return kind === "base-url"
    ? "Sandbox — the provider's separate test host"
    : kind === "separate-account"
      ? "Sandbox — your separate test account"
      : "Sandbox — the provider's test estate";
}

/**
 * Build a connector node's authoring surface.
 *
 * Prepends the shared connection fields, applies the domain accent, and stamps
 * the metadata the registry reads. A connector that hand-rolled these would
 * drift from its siblings in exactly the small ways that make a catalogue feel
 * like a pile.
 */
export function defineConnectorKind(
  meta: ConnectorMeta,
  kind: Omit<NodeKindDefinition, "category"> & { category?: NodeKindDefinition["category"] },
): NodeKindDefinition & { connector: ConnectorMeta } {
  return {
    ...kind,
    // `category` stays fancy-flow's own taxonomy — it describes what the node
    // does to the GRAPH, which is what the palette groups by. Connector-ness is
    // a separate axis and is carried separately; overloading one field with two
    // meanings would make "show me the triggers" and "hide the connectors"
    // impossible to ask at the same time.
    category: kind.category ?? (meta.role === "trigger" ? "trigger" : "io"),
    accent: kind.accent ?? DOMAIN_ACCENT[meta.domain],
    configSchema: [...connectionFields(meta), ...(kind.configSchema ?? [])],
    connector: meta,
  };
}

/**
 * One line describing what a configured node will do, in IFTTT's register.
 *
 * A configured connector should read as a sentence, not as a form dump — it is
 * what makes a canvas skimmable, and it is also what an agent quotes back to a
 * human when asking whether to proceed.
 */
export function summarize(meta: ConnectorMeta, config: Record<string, unknown>, detail?: string): string {
  const mode = typeof config.mode === "string" ? config.mode : "auto";
  const where =
    mode === "fake"
      ? " (faked — nothing leaves this machine)"
      : mode === "sandbox"
        ? " in the sandbox"
        : mode === "live"
          ? " on the live account"
          : "";

  const what = detail?.trim() ? detail.trim() : meta.operation.replace(/_/g, " ");

  return meta.role === "trigger"
    ? `When ${meta.serviceTitle} reports ${what}${where}`
    : `Then ${meta.serviceTitle} will ${what}${where}`;
}

/** Declare a trigger's event fields — the "ingredients" downstream nodes pick from. */
export function ingredients(fields: OutputField[]): OutputField[] {
  return fields;
}

const DOMAIN_ACCENT: Record<ConnectorDomain, string> = {
  payments: "#635bff",
  commerce: "#96bf48",
  messaging: "#4a154b",
  email: "#0f9d58",
  crm: "#00a1e0",
  support: "#03363d",
  storage: "#ff9900",
  calendar: "#4285f4",
  productivity: "#2f3437",
  database: "#336791",
  devtools: "#24292f",
  analytics: "#f9a03c",
  marketing: "#1877f2",
  ai: "#d97757",
  forms: "#262627",
  hr: "#5c4ee5",
  geo: "#34a853",
};

/**
 * The one call path every connector node uses.
 *
 * A node's executor never chooses between "call the provider" and "call the
 * faker" — it describes the request it wants and hands it here. That is the
 * point: the code path a consumer develops against with no credentials is the
 * same code path that runs in production, so the fixtures prove something about
 * the executor rather than about a mock.
 *
 * ```ts
 * const charge = await callConnector(STRIPE, {
 *   operation: "charge_create",
 *   config,
 *   input: ctx.inputs.in,
 *   request: { method: "POST", path: "/v1/charges", form: { amount, currency } },
 *   idempotencyKey: `${ctx.node.id}:${runKey}`,
 * });
 * ```
 */

import { resolveConnection, type ConnectionCredentials, type ResolvedConnection } from "./connection";
import { classifyHttp, ConnectorConfigError, ConnectorError, ConnectorTransient } from "./errors";
import { fakeRequest, type ConnectorFaker } from "./faker";
import type { ConnectorMode, RequestedMode, SandboxKind } from "./mode";

/**
 * Everything true of a SERVICE rather than of one operation.
 *
 * One of these per provider, declared once and shared by that provider's nodes.
 * It is data — base URLs, which credential keys are required, how the sandbox
 * is selected — so that facts we verified against provider documentation live
 * in exactly one reviewable place instead of being retyped into each node.
 */
export type ServiceDescriptor = {
  service: string;
  title: string;
  sandbox: SandboxKind;
  /**
   * Base URL per mode. A `credential`-sandbox provider gives the same URL for
   * both, which is itself worth writing down: it is why a live key pointed at
   * "sandbox" quietly reaches production.
   */
  baseUrls: Partial<Record<ConnectorMode, string>>;
  /** Credential keys a remote call cannot proceed without. */
  requires: string[];
  /**
   * Apply the provider's auth scheme to an outgoing request.
   *
   * Receives the resolved MODE as well, because for some providers auth and
   * estate are the same decision expressed in the URL — Telegram puts the bot
   * token in the path and selects its test environment with a `/test` segment
   * after it. A signature that hid the mode would push those providers towards
   * a global, which is the thing this seam exists to avoid.
   */
  authorize: (
    credentials: ConnectionCredentials,
    request: PreparedRequest,
    mode: ConnectorMode,
  ) => void | Promise<void>;
  /** The service's faker. Required — see `faker.ts`. */
  faker: ConnectorFaker;
  /** Header the provider uses for idempotency, when it has one. */
  idempotencyHeader?: string;
};

export type ConnectorRequest = {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
  query?: Record<string, string | number | boolean | undefined>;
  headers?: Record<string, string>;
  /** JSON body. Mutually exclusive with `form`. */
  json?: unknown;
  /** `application/x-www-form-urlencoded` body — what several payment APIs want. */
  form?: Record<string, string | number | boolean | undefined>;
};

export type PreparedRequest = {
  method: string;
  url: string;
  headers: Record<string, string>;
  body?: string;
};

export type CallOptions = {
  operation: string;
  config: Record<string, unknown>;
  input?: unknown;
  request: ConnectorRequest;
  /**
   * Value for the provider's idempotency header. Pass something derived from
   * the run and the node, never a fresh uuid: the entire point is that a RETRY
   * carries the same key.
   */
  idempotencyKey?: string;
  /** Retry budget for retryable failures. Defaults to 2 extra attempts. */
  retries?: number;
};

/** The HTTP seam. A host may swap it; nothing here assumes a browser or Node. */
export type Transport = (request: PreparedRequest) => Promise<TransportResponse>;

export type TransportResponse = {
  status: number;
  headers: Record<string, string>;
  body: string;
};

let transport: Transport | null = null;

/** Install a transport. Only needed if the runtime has no global `fetch`. */
export function registerTransport(next: Transport | null): void {
  transport = next;
}

/** What a connector call returns, alongside the provider's own payload. */
export type ConnectorResult<T = unknown> = {
  data: T;
  /** Which estate this actually ran against. Always reported, never inferred. */
  mode: ConnectorMode;
  connection: string;
};

export async function callConnector<T = unknown>(
  service: ServiceDescriptor,
  options: CallOptions,
): Promise<ConnectorResult<T>> {
  const connection = resolveConnection({
    service: service.service,
    operation: options.operation,
    connectionId: readString(options.config, "connection"),
    requested: readString(options.config, "mode") as RequestedMode | null,
    sandbox: service.sandbox,
    baseUrls: service.baseUrls,
    requires: service.requires,
  });

  if (connection.mode === "fake") {
    return {
      data: service.faker(
        options.operation,
        fakeRequest(service.service, options.operation, options.config, options.input),
      ) as T,
      mode: "fake",
      connection: connection.id,
    };
  }

  return {
    data: (await remoteCall(service, connection, options)) as T,
    mode: connection.mode,
    connection: connection.id,
  };
}

async function remoteCall(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<unknown> {
  const prepared = await prepare(service, connection, options);
  const send = transport ?? fetchTransport;
  const ctx = { service: service.service, operation: options.operation };
  const budget = options.retries ?? 2;
  let attempt = 0;

  for (;;) {
    let response: TransportResponse;

    try {
      response = await send(prepared);
    } catch (cause) {
      // A thrown transport is a network-level failure: unreachable, reset,
      // timed out. Retryable by nature, and distinct from a 5xx, which at
      // least proves we reached something.
      const error = new ConnectorTransient(
        `${ctx.service}.${ctx.operation}: ${(cause as Error)?.message ?? "transport failed"}`,
        ctx,
      );
      if (attempt++ >= budget) throw error;
      await sleep(backoffMs(attempt));

      continue;
    }

    if (response.status < 400) {
      return response.body.trim() === "" ? null : parseJson(response.body, ctx);
    }

    const error = classifyHttp(
      response.status,
      ctx,
      response.body,
      readRetryAfter(response.headers),
    );

    if (!error.retryable || attempt++ >= budget) throw error;

    // Honour the provider's own instruction when it gave one. Guessing shorter
    // than they asked is how a throttle becomes a ban.
    const wait = "retryAfter" in error && typeof error.retryAfter === "number"
      ? error.retryAfter * 1000
      : backoffMs(attempt);
    await sleep(wait);
  }
}

async function prepare(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<PreparedRequest> {
  const base = connection.baseUrl ?? service.baseUrls[connection.mode];

  if (!base) {
    throw new ConnectorConfigError(
      `${service.service}: no base URL for "${connection.mode}" mode. ` +
        "The service descriptor must declare one per mode it supports.",
      { service: service.service, operation: options.operation },
    );
  }

  const { method, path, query, headers, json, form } = options.request;
  const url = new URL(path.replace(/^\/+/, ""), base.endsWith("/") ? base : `${base}/`);

  for (const [key, value] of Object.entries(query ?? {})) {
    if (value !== undefined) url.searchParams.set(key, String(value));
  }

  const prepared: PreparedRequest = {
    method,
    url: url.toString(),
    headers: { Accept: "application/json", ...headers },
  };

  if (form) {
    prepared.headers["Content-Type"] = "application/x-www-form-urlencoded";
    prepared.body = encodeForm(form);
  } else if (json !== undefined) {
    prepared.headers["Content-Type"] = "application/json";
    prepared.body = JSON.stringify(json);
  }

  if (options.idempotencyKey && service.idempotencyHeader) {
    prepared.headers[service.idempotencyHeader] = options.idempotencyKey;
  }

  await service.authorize(connection.credentials, prepared, connection.mode);

  return prepared;
}

/**
 * Form encoding, including the bracketed-nesting several payment APIs use
 * (`metadata[order_id]=7`). Flat maps pass through unchanged.
 */
function encodeForm(form: Record<string, unknown>): string {
  const pairs: string[] = [];

  const walk = (prefix: string, value: unknown): void => {
    if (value === undefined || value === null) return;
    if (typeof value === "object" && !Array.isArray(value)) {
      for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
        walk(prefix === "" ? key : `${prefix}[${key}]`, nested);
      }

      return;
    }
    if (Array.isArray(value)) {
      value.forEach((item, index) => walk(`${prefix}[${index}]`, item));

      return;
    }
    pairs.push(`${encodeURIComponent(prefix)}=${encodeURIComponent(String(value))}`);
  };

  walk("", form);

  return pairs.join("&");
}

const fetchTransport: Transport = async (request) => {
  const globalFetch = (globalThis as { fetch?: typeof fetch }).fetch;

  if (!globalFetch) {
    throw new Error(
      "no global fetch in this runtime — call registerTransport() with one before running a connector remotely.",
    );
  }

  const response = await globalFetch(request.url, {
    method: request.method,
    headers: request.headers,
    ...(request.body === undefined ? {} : { body: request.body }),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key.toLowerCase()] = value;
  });

  return { status: response.status, headers, body: await response.text() };
};

function parseJson(body: string, ctx: { service: string; operation: string }): unknown {
  try {
    return JSON.parse(body);
  } catch {
    throw new ConnectorError(
      `${ctx.service}.${ctx.operation}: the provider returned a body that is not JSON.`,
      ctx,
    );
  }
}

function readRetryAfter(headers: Record<string, string>): number | undefined {
  const raw = headers["retry-after"];
  if (!raw) return undefined;
  const seconds = Number(raw);

  return Number.isFinite(seconds) ? seconds : undefined;
}

/** Exponential with a ceiling. Attempt 1 → 250ms, 2 → 500ms, 3 → 1s, capped at 8s. */
function backoffMs(attempt: number): number {
  return Math.min(8000, 250 * 2 ** (attempt - 1));
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readString(config: Record<string, unknown>, key: string): string | null {
  const value = config[key];

  return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
}

/**
 * A CONNECTION — credentials plus an environment choice — configured once per
 * service and referenced by every node that uses it.
 *
 * ## Why this is not per-node config
 *
 * The obvious design is to put an API key field on each node. It is also wrong,
 * for three reasons that only show up later:
 *
 * 1. **Rotation.** A key on twelve nodes is twelve edits and one you will miss.
 * 2. **The sandbox/live switch has to live somewhere singular.** If each node
 *    carries its own, a graph can be half in the test estate and half in the
 *    real one, and nothing about the canvas shows it.
 * 3. **Credentials would be in the graph.** A `WorkflowSchema` is plain JSON
 *    that gets exported, committed, MCP'd to an agent and pasted into issues.
 *    Nothing secret may ever be in it.
 *
 * So a node's config stores a **connection id** — an opaque, non-secret name
 * like `"stripe"` or `"stripe-eu"` — and the host resolves it to credentials at
 * run time. This is the same arrangement fancy-flow already uses for LLM clients
 * and `fancy-git` uses for providers: the node cannot reach for a credential,
 * the host has to hand one over.
 *
 * ```ts
 * registerConnectionHost({
 *   environment: { production: process.env.NODE_ENV === "production" },
 *   connections: {
 *     stripe: {
 *       service: "stripe",
 *       live:    { secretKey: process.env.STRIPE_SECRET_KEY },
 *       sandbox: { secretKey: process.env.STRIPE_TEST_SECRET_KEY },
 *     },
 *   },
 * });
 * ```
 *
 * Note what is NOT here: no key, no token, no placeholder that looks like one.
 * Credentials are configuration, and configuration comes from the consumer's
 * environment.
 */

import { ConnectorConfigError } from "./errors";
import {
  ConnectorModeError,
  resolveConnectorMode,
  type ConnectorMode,
  type HostEnvironment,
  type RequestedMode,
  type SandboxKind,
} from "./mode";

/**
 * Credentials for one estate. Values are opaque strings the node's auth
 * strategy understands — `secretKey`, `clientId`/`clientSecret`, `token`.
 */
export type ConnectionCredentials = Record<string, string | undefined>;

/** One configured connection to one service. */
export type ConnectionSpec = {
  /** The service this connection is for — must match the node's `connector.service`. */
  service: string;
  /** Human label, shown in the picker. Defaults to the id. */
  label?: string;
  /**
   * Pin this connection to a mode. Optional, and usually absent: leaving it
   * unset is what lets the environment supply the default.
   */
  mode?: ConnectorMode;
  live?: ConnectionCredentials;
  sandbox?: ConnectionCredentials;
  /**
   * Override the base URL per mode. Only needed for a `separate-account`
   * provider whose tenant has its own host (a Salesforce instance URL); the
   * `base-url` providers carry theirs in the node's service descriptor.
   */
  baseUrl?: Partial<Record<ConnectorMode, string>>;
};

export type ConnectionHost = {
  environment: HostEnvironment;
  connections: Record<string, ConnectionSpec>;
};

let host: ConnectionHost | null = null;

/**
 * Install the host's connections. Returns an unregister function.
 *
 * One registration for the whole app, matching how a person thinks about it:
 * you authorize Stripe once, then every node that needs Stripe already has it.
 */
export function registerConnectionHost(next: ConnectionHost | null): () => void {
  host = next;

  return () => {
    if (host === next) host = null;
  };
}

export function getConnectionHost(): ConnectionHost | null {
  return host;
}

/** Connection ids the host has configured for a service — feeds the picker. */
export function connectionsFor(service: string): Array<{ id: string; label: string }> {
  const current = getConnectionHost();
  if (!current) return [];

  return Object.entries(current.connections)
    .filter(([, spec]) => spec.service === service)
    .map(([id, spec]) => ({ id, label: spec.label ?? id }));
}

/** What a node's executor actually needs, once everything has been resolved. */
export type ResolvedConnection = {
  id: string;
  service: string;
  mode: ConnectorMode;
  /** Empty in `fake` mode — there is nothing to authenticate against. */
  credentials: ConnectionCredentials;
  /** Undefined in `fake` mode. */
  baseUrl?: string;
};

export type ResolveOptions = {
  service: string;
  operation: string;
  /** The connection id from node config. Defaults to the service name. */
  connectionId?: string | null;
  /** The `mode` field from node config. */
  requested?: RequestedMode | null;
  sandbox: SandboxKind;
  /** Base URL per mode, from the node's service descriptor. */
  baseUrls?: Partial<Record<ConnectorMode, string>>;
  /** Credential keys that must be present for a remote call. */
  requires?: string[];
};

/**
 * Resolve the connection and mode for one call.
 *
 * ## `fake` needs no host at all
 *
 * A freshly vendored connector runs before anything is configured, and that is
 * deliberate: it is the difference between a marketplace someone can try and
 * one they can only read about. So the no-host case resolves to `fake` rather
 * than throwing — UNLESS the author explicitly asked for a remote mode, in
 * which case the ask is honoured by failing loudly instead of quietly doing
 * something else.
 */
export function resolveConnection(options: ResolveOptions): ResolvedConnection {
  const { service, operation, sandbox } = options;
  const requestedMode = options.requested ?? "auto";

  // Checked FIRST, before anything about the host, because it is a static fact
  // about the SERVICE. Asking for a sandbox that does not exist should say so
  // whether or not a connection happens to be configured — otherwise the same
  // mistake produces two different errors depending on unrelated state, and the
  // more useful one is the one you never see.
  if (requestedMode === "sandbox" && sandbox === "none") {
    throw new ConnectorModeError(
      `${service} has no sandbox estate, so "sandbox" cannot be honoured. ` +
        'Use "fake" to develop without credentials, or "live" to talk to the provider.',
    );
  }

  const id = options.connectionId?.trim() || service;
  const current = getConnectionHost();
  const spec = current?.connections[id];

  if (spec && spec.service !== service) {
    throw new ConnectorConfigError(
      `connection "${id}" is configured for the "${spec.service}" service, but this node needs "${service}".`,
      { service, operation },
    );
  }

  if (!current || !spec) {
    if (requestedMode !== "auto" && requestedMode !== "fake") {
      throw new ConnectorConfigError(
        `no "${id}" connection is registered, so ${service}.${operation} cannot run in "${requestedMode}" mode. ` +
          "Call registerConnectionHost({ connections: { " +
          `${id}: { service: "${service}", live: { … } } } }) — the node has no credentials of its own ` +
          'and must not invent any. Set the node\'s mode to "fake" to develop without one.',
        { service, operation },
      );
    }

    return { id, service, mode: "fake", credentials: {} };
  }

  const sandboxCreds = spec.sandbox ?? {};
  const mode = resolveConnectorMode({
    requested: requestedMode,
    connectionMode: spec.mode ?? null,
    sandbox,
    hasSandboxCredentials: hasAll(sandboxCreds, options.requires ?? []),
    environment: current.environment,
  });

  if (mode === "fake") {
    return { id, service, mode, credentials: {} };
  }

  const credentials = (mode === "sandbox" ? spec.sandbox : spec.live) ?? {};
  const missing = (options.requires ?? []).filter((key) => !credentials[key]);

  if (missing.length > 0) {
    // Never silently degrade to the faker here. A run that "succeeded" because
    // it quietly stopped talking to the provider is the worst failure this
    // whole design exists to prevent — it is green, it is wrong, and nothing
    // reports it.
    throw new ConnectorConfigError(
      `connection "${id}" has no ${missing.join(", ")} for ${mode} mode. ` +
        `Set connections.${id}.${mode}.${missing[0]}, or run this node in "fake" mode.`,
      { service, operation },
    );
  }

  const baseUrl = spec.baseUrl?.[mode] ?? options.baseUrls?.[mode];

  return { id, service, mode, credentials, ...(baseUrl ? { baseUrl } : {}) };
}

function hasAll(creds: ConnectionCredentials, keys: string[]): boolean {
  return keys.length > 0 && keys.every((key) => Boolean(creds[key]));
}

/**
 * The connector error taxonomy.
 *
 * Durable runs retry, and a retry policy needs to know WHICH KIND of failure it
 * is looking at. "Something went wrong" is not enough information to decide
 * between retrying, pausing for a human, and stopping — so every connector
 * failure is classified at the point it is known, which is inside the connector,
 * not three frames up where the type has already been lost.
 *
 * | class                    | retry? | why |
 * |--------------------------|--------|-----|
 * | `ConnectorConfigError`   | never  | nothing about a second attempt changes an unset key |
 * | `ConnectorAuthError`     | never  | the credential is wrong; hammering it gets accounts locked |
 * | `ConnectorRateLimited`   | yes    | after `retryAfter`, which the provider told us |
 * | `ConnectorTransient`     | yes    | 5xx, timeout, connection reset |
 * | `ConnectorRequestError`  | never  | 4xx we caused; the same request fails the same way |
 */

export type ConnectorErrorContext = {
  service: string;
  operation: string;
  /** HTTP status when there was one. */
  status?: number;
  /** The provider's own error code, when it publishes one. */
  providerCode?: string;
};

/** Base for everything below, so a host can catch the family in one clause. */
export class ConnectorError extends Error {
  readonly service: string;

  readonly operation: string;

  readonly status?: number;

  readonly providerCode?: string;

  /** Whether a second attempt could plausibly succeed. */
  readonly retryable: boolean = false;

  constructor(message: string, ctx: ConnectorErrorContext) {
    super(message);
    this.name = new.target.name;
    this.service = ctx.service;
    this.operation = ctx.operation;
    this.status = ctx.status;
    this.providerCode = ctx.providerCode;
  }
}

/**
 * A required piece of configuration is missing or unusable.
 *
 * The message must name the exact key the consumer has to set. "Stripe is not
 * configured" sends someone reading source; "no `secretKey` on the `stripe`
 * connection — set it via registerConnectionHost" sends them to the line.
 */
export class ConnectorConfigError extends ConnectorError {}

/** The provider rejected the credential. Retrying cannot help. */
export class ConnectorAuthError extends ConnectorError {
  override readonly retryable = false;
}

/** The provider asked us to slow down. */
export class ConnectorRateLimited extends ConnectorError {
  override readonly retryable = true;

  /** Seconds to wait, when the provider said. */
  readonly retryAfter?: number;

  constructor(message: string, ctx: ConnectorErrorContext & { retryAfter?: number }) {
    super(message, ctx);
    this.retryAfter = ctx.retryAfter;
  }
}

/** A 5xx, a timeout, a reset — the provider's problem, and it may pass. */
export class ConnectorTransient extends ConnectorError {
  override readonly retryable = true;
}

/** A 4xx we caused. The same request will fail the same way. */
export class ConnectorRequestError extends ConnectorError {
  override readonly retryable = false;
}

/**
 * Classify an HTTP response into the taxonomy.
 *
 * 429 before the 4xx sweep, deliberately: a rate limit is a 4xx and is the one
 * 4xx that IS worth retrying, so an ordering that checked `>= 400` first would
 * mark every throttle permanent and turn a busy minute into a failed run.
 */
export function classifyHttp(
  status: number,
  ctx: ConnectorErrorContext,
  body: string,
  retryAfter?: number,
): ConnectorError {
  const detail = body.trim() === "" ? "" : ` — ${truncate(body, 400)}`;
  const where = `${ctx.service}.${ctx.operation}`;

  if (status === 429) {
    return new ConnectorRateLimited(`${where}: rate limited by the provider${detail}`, {
      ...ctx,
      status,
      retryAfter,
    });
  }

  if (status === 401 || status === 403) {
    return new ConnectorAuthError(
      `${where}: the provider rejected the credential (${status})${detail}. ` +
        "Check the connection's credentials and that they match the mode you are running in — " +
        "a live key in sandbox, or the reverse, fails exactly like this.",
      { ...ctx, status },
    );
  }

  if (status >= 500) {
    return new ConnectorTransient(`${where}: provider returned ${status}${detail}`, { ...ctx, status });
  }

  return new ConnectorRequestError(`${where}: request rejected with ${status}${detail}`, { ...ctx, status });
}

function truncate(value: string, max: number): string {
  return value.length <= max ? value : `${value.slice(0, max)}…`;
}

/**
 * The faker layer — every connector ships one, always.
 *
 * ## Why every connector, and not just the ones without a sandbox
 *
 * A sandbox still needs an account, a key, a network, and a provider that is
 * up. That is four ways for someone evaluating the kit to get nothing working,
 * before they have learned anything about the kit. A faker removes all four:
 * vendor a node, drop it on a canvas, press run, see a shaped result.
 *
 * It is also what makes the golden fixtures honest. Fixtures run on both
 * runtimes and are the publish gate; if they needed a network they would either
 * be skipped in CI or be flaky, and a flaky gate is one people learn to
 * re-run rather than read.
 *
 * ## Deterministic, not random
 *
 * Same inputs, same output — always. A faker that returns a fresh uuid every
 * call cannot be asserted on, so its fixtures degrade to "it did not throw",
 * which is the assertion that catches nothing. Values here are derived from a
 * seed built out of the service, the operation and the request, so two runs
 * agree and two runtimes can be compared to each other.
 *
 * The values are obviously fake ON PURPOSE — `fake_`-prefixed ids, `example.test`
 * hosts, round numbers. Nobody should ever look at a faked result and wonder
 * whether it moved real money.
 */

/** A faker: one function per service, switching on the operation. */
export type ConnectorFaker = (operation: string, request: FakeRequest) => unknown;

export type FakeRequest = {
  /** The node's resolved config. */
  config: Record<string, unknown>;
  /** The value on the incoming wire. */
  input?: unknown;
  /** Deterministic helpers, seeded from service + operation + config. */
  fake: FakeValues;
};

/**
 * Deterministic value helpers handed to a faker.
 *
 * Small on purpose. A faker's job is to return the SHAPE the provider returns —
 * the field names a downstream node will reference — not to simulate the
 * provider's business logic.
 */
export type FakeValues = {
  /** A stable id with the provider's usual prefix: `id("ch")` → `ch_fake_1a2b3c`. */
  id: (prefix: string) => string;
  /** A stable integer in `[min, max]`. */
  int: (min: number, max: number) => number;
  /** Pick a stable element of a list. */
  pick: <T>(options: readonly T[]) => T;
  /** A fixed ISO-8601 instant, offset by whole seconds. Never `Date.now()`. */
  timestamp: (offsetSeconds?: number) => string;
  /** A stable lowercase hex string of `length` characters. */
  hex: (length: number) => string;
};

/**
 * The instant every faker counts from.
 *
 * A constant rather than the clock, because a fixture asserting on `createdAt`
 * must not start failing tomorrow. Chosen to be recognisably synthetic.
 */
export const FAKE_EPOCH = "2026-01-01T00:00:00.000Z";

/** FNV-1a. Small, dependency-free, and stable across both runtimes. */
export function seedFrom(...parts: unknown[]): number {
  const text = parts.map((part) => (typeof part === "string" ? part : stableJson(part))).join("|");
  let hash = 0x811c9dc5;

  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    // 32-bit FNV prime multiply, kept in range without BigInt.
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }

  return hash >>> 0;
}

/**
 * Key order must not change a seed.
 *
 * `JSON.stringify` preserves insertion order, so `{a,b}` and `{b,a}` would hash
 * differently and the "same inputs, same output" promise would hold only for
 * objects that happened to be built in the same order — which is exactly the
 * kind of almost-true that survives review and fails in a fixture months later.
 */
function stableJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;

  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([k, v]) => `${JSON.stringify(k)}:${stableJson(v)}`);

  return `{${entries.join(",")}}`;
}

/** Build the deterministic helpers for one faked call. */
export function fakeValues(seed: number): FakeValues {
  // A tiny xorshift, advanced per call so successive helpers differ while the
  // whole sequence stays a pure function of the seed.
  let state = seed || 0x9e3779b9;
  const next = (): number => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;

    return state;
  };

  const hex = (length: number): string => {
    let out = "";
    while (out.length < length) out += next().toString(16).padStart(8, "0");

    return out.slice(0, length);
  };

  return {
    hex,
    id: (prefix: string) => `${prefix}_fake_${hex(12)}`,
    int: (min: number, max: number) => min + (next() % Math.max(1, max - min + 1)),
    pick: <T>(options: readonly T[]): T => options[next() % options.length] as T,
    timestamp: (offsetSeconds = 0) =>
      new Date(Date.parse(FAKE_EPOCH) + offsetSeconds * 1000).toISOString(),
  };
}

/** Build the request handed to a faker, with helpers already seeded. */
export function fakeRequest(
  service: string,
  operation: string,
  config: Record<string, unknown>,
  input?: unknown,
): FakeRequest {
  return { config, input, fake: fakeValues(seedFrom(service, operation, config)) };
}

/**
 * Deriving an idempotency key — and being honest when we cannot.
 *
 * ## The gap this works around
 *
 * A durable run RETRIES. For a writing connector that is only survivable if the
 * retry carries the same idempotency key the first attempt did, so the provider
 * returns the original result instead of creating a second charge, a second
 * refund, a second message.
 *
 * **Neither engine's execution context carries a run identity today.** The TS
 * `ctx` is `{ node, inputs, emit, abort }`; `FancyFlow\Runtime\ExecutionContext`
 * is the same four plus `depth`. There is no run key, no attempt number, nothing
 * a node can key on — checked against fancy-flow 0.45.0 and fancy-flow-php
 * 0.17.0 rather than assumed.
 *
 * So this reads the conventional places a host might put one, and returns
 * `null` when there is none.
 *
 * ## Why the two obvious fallbacks are both wrong
 *
 * - **The node id alone** is stable across retries — and also across different
 *   runs. Two legitimate payments for the same customer would share a key, and
 *   the second would be silently deduplicated into the first. A payment that
 *   never happened, reported as success.
 * - **A fresh random value** is unique per run — and also per attempt. A retry
 *   would create a second charge, which is the whole thing we are avoiding.
 *
 * Both are worse than no key. So with no run identity a connector sends none
 * and stays `unsafe-to-replay`, which pins it to a single attempt under the
 * per-node queue driver. Fewer retries, no double writes.
 */

/** Where a host may publish the run key. Checked in order. */
export function runKeyFrom(ctx: unknown): string | null {
  const bag = ctx as Record<string, any> | null;
  if (!bag) return null;

  const candidates = [
    bag.runKey,
    bag.run?.key,
    bag.runId,
    // A host with no engine support can seed it as an initial input, which the
    // engine merges into every node's inputs.
    bag.inputs?.__runKey,
  ];

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim() !== "") return candidate.trim();
  }

  return null;
}

/**
 * The idempotency key for one node in one run, or `null`.
 *
 * `null` is a legitimate answer and callers must treat it as one — passing it
 * through means "send no idempotency header", not "make something up".
 */
export function idempotencyKeyFor(ctx: unknown, nodeId: string): string | null {
  const run = runKeyFrom(ctx);

  return run === null ? null : `${run}:${nodeId}`;
}

/**
 * The warning a node emits when it is about to write without a key.
 *
 * Said out loud, at the moment it matters, because the failure it precedes is
 * invisible: the run succeeds, the retry succeeds, and there are two charges.
 */
export const NO_IDEMPOTENCY_KEY_WARNING =
  "no run identity available, so this write is being sent WITHOUT an idempotency key. " +
  "A retry would repeat the effect rather than recover from it — the node is marked " +
  "unsafe-to-replay, so a durable runner will give it one attempt. To enable safe retries, " +
  "seed a stable `__runKey` into the run's initial inputs.";

/**
 * The shared connector runtime, for hosts that EXECUTE on TypeScript.
 *
 * Vendored, not installed: this directory is copied into a consumer's project
 * alongside the first connector node they add, and every connector after that
 * reuses it. There is no package to require — that is the whole point of the
 * node marketplace, and a shared runtime that arrived as a dependency would
 * undo it.
 */

export * from "./client";
export * from "./connection";
export * from "./errors";
export * from "./faker";
export * from "./mode";
export * from "./trigger";
export * from "./webhook";

/**
 * Which copy of a provider a connector talks to — and who decides.
 *
 * Three modes, and the third is the one that makes this marketplace usable:
 *
 * | mode      | talks to                    | needs credentials | needs network |
 * |-----------|-----------------------------|-------------------|---------------|
 * | `live`    | the provider, for real      | yes               | yes           |
 * | `sandbox` | the provider's test estate  | yes (test ones)   | yes           |
 * | `fake`    | the node's own faker        | no                | no            |
 *
 * ## The environment is the DEFAULT, never the constraint
 *
 * A locally-hosted project defaults to sandbox. It is not *pinned* to sandbox:
 * an author who explicitly asks for `live` on their laptop gets `live`, because
 * the alternative — an environment that silently overrides a stated intention —
 * produces the worst outcome available here, which is a workflow that reports
 * success while having charged nobody. Equally, `sandbox` set explicitly stays
 * sandbox in production, which is how you stage a connector before cutting it
 * over.
 *
 * So: explicit beats the connection, the connection beats the environment.
 *
 * ## Why "fake" is a MODE and not a test double
 *
 * Every connector ships a faker (see `faker.ts`), and it is reachable the same
 * way in a test, in a demo and on a laptop with no credentials. Making it a
 * separate mechanism — a mock injected only under test — would mean the code
 * path a consumer develops against is not the one that runs, and the fixtures
 * would prove nothing about the executor.
 */

/** The three environments a connector node can run against. */
export type ConnectorMode = "fake" | "sandbox" | "live";

/** What a node's `mode` config field may say. `auto` means "let the rules decide". */
export type RequestedMode = ConnectorMode | "auto";

export const CONNECTOR_MODES: ConnectorMode[] = ["fake", "sandbox", "live"];

/**
 * How a provider exposes its test estate — the four shapes that actually exist.
 *
 * This is data, not per-node code, because getting it wrong is the difference
 * between hitting a test ledger and hitting a real one. Verified per provider in
 * `.ai/plans/fancy-flow-connector-nodes.md`; a node declares which of the four
 * it is and the core does the rest.
 *
 * - `credential` — same base URL, a test-scoped key selects the estate
 *   (Stripe's `sk_test_…`). The trap: pointing a live key at it works, so the
 *   only guard is the key itself.
 * - `base-url` — a different host entirely (PayPal's `api-m.sandbox.paypal.com`).
 * - `separate-account` — a distinct tenant you must create, often with its own
 *   login host (Salesforce sandbox orgs on `test.salesforce.com`).
 * - `none` — the provider has no test estate. `sandbox` is then not offered at
 *   all, and the node's honest choices are `fake` and `live`.
 */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

/** The host's view of where it is running. Kept tiny so it is trivial to fake. */
export type HostEnvironment = {
  /** True only in a real production deployment. Everything else is "local". */
  production: boolean;
};

export type ModeInputs = {
  /** What the node's config asked for. `undefined` / `"auto"` means "decide". */
  requested?: RequestedMode | null;
  /** A mode pinned on the CONNECTION, if the host pinned one. */
  connectionMode?: ConnectorMode | null;
  /** Whether the provider has a test estate at all. */
  sandbox: SandboxKind;
  /** Whether the connection actually carries credentials for the sandbox estate. */
  hasSandboxCredentials: boolean;
  environment: HostEnvironment;
};

/**
 * Resolve the mode a connector call runs in.
 *
 * Deliberately a pure function of stated facts, so both runtimes can be held to
 * the same table of cases and a host can unit-test its own wiring without a
 * network or a provider.
 */
export function resolveConnectorMode(inputs: ModeInputs): ConnectorMode {
  const { requested, connectionMode, sandbox, hasSandboxCredentials, environment } = inputs;

  // 1. An explicit ask wins everywhere. This is the rule that makes the
  //    environment a default rather than a cage.
  if (requested && requested !== "auto") {
    if (requested === "sandbox" && sandbox === "none") {
      throw new ConnectorModeError(
        'This connector\'s provider has no sandbox estate, so "sandbox" cannot be honoured. ' +
          'Use "fake" to develop without credentials, or "live" to talk to the provider.',
      );
    }

    return requested;
  }

  // 2. A mode pinned on the connection. One place per service, which is the
  //    whole reason connections exist as a separate thing.
  if (connectionMode) return connectionMode;

  // 3. Otherwise the environment decides.
  if (environment.production) return "live";

  // Local: prefer the provider's own test estate when it exists AND is wired.
  // Falling through to `fake` when it is not is what makes a freshly vendored
  // node runnable with no setup at all — the difference between a marketplace
  // you can try and one you can only read about.
  return sandbox !== "none" && hasSandboxCredentials ? "sandbox" : "fake";
}

/** Raised when a requested mode cannot be honoured. Never downgraded silently. */
export class ConnectorModeError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ConnectorModeError";
  }
}

/** True when the mode reaches the provider over the network. */
export function isRemote(mode: ConnectorMode): boolean {
  return mode !== "fake";
}

/**
 * How a connector trigger learns that something happened.
 *
 * **Not every provider pushes, and assuming webhooks is the single most common
 * way a connector catalogue ends up lying.** Google Drive and Microsoft Graph
 * want a *subscription* you must renew before it expires. Salesforce wants a
 * Pub/Sub or CometD stream. S3 wants an event notification routed to
 * infrastructure the consumer provisions. Reddit wants you to poll. Each of
 * those is a different obligation on the host, and a node that declared
 * "webhook" for all of them would install cleanly and then never fire.
 *
 * So a trigger declares its delivery mechanism, and the host can refuse to mount
 * one it has no machinery for — at author time, not at 3am.
 */

import type { ResolvedConnection } from "./connection";
import type { ConnectorFaker } from "./faker";
import { fakeRequest } from "./faker";
import type { HmacScheme, WebhookVerification } from "./webhook";
import { header, verifyHmac } from "./webhook";

/**
 * The delivery mechanisms that actually exist in the wild.
 *
 * - `webhook` — the provider POSTs to a URL you own. Verify the signature.
 * - `subscription` — a webhook that EXPIRES. Someone has to renew it, forever,
 *   and if nobody does the workflow stops firing without an error anywhere.
 *   Distinct from `webhook` precisely because that ongoing duty is invisible.
 * - `poll` — you ask, on a schedule, and track a cursor.
 * - `pubsub` — the provider publishes to a broker (Google Pub/Sub, Salesforce
 *   Pub/Sub API, SNS/SQS) that the consumer must provision.
 * - `stream` — a long-lived connection the host maintains (websocket, gRPC,
 *   SSE, CometD).
 */
export type DeliveryMechanism = "webhook" | "subscription" | "poll" | "pubsub" | "stream";

export type TriggerDescriptor = {
  service: string;
  operation: string;
  delivery: DeliveryMechanism;
  /**
   * What the host has to do before this fires, in one sentence, aimed at the
   * person who has to do it. Surfaced by the editor and by the MCP, because a
   * trigger whose setup is undocumented is a trigger that silently never fires.
   */
  setup: string;
  /** For `subscription`: how long the provider keeps it alive, in seconds. */
  subscriptionTtl?: number;
  /** For `webhook` / `subscription`: how a delivery is authenticated. */
  verification?: WebhookVerificationSpec;
  /** For `poll`: the provider's smallest sane interval, in seconds. */
  minPollSeconds?: number;
  /** A faked sample event, so the node is runnable before any of the above. */
  faker: ConnectorFaker;
};

export type WebhookVerificationSpec = {
  /** Header carrying the signature. */
  signatureHeader: string;
  /** Header carrying the timestamp, when the scheme signs one. */
  timestampHeader?: string;
  scheme: HmacScheme;
  /**
   * Some schemes pack the timestamp INTO the signature header
   * (Stripe: `t=…,v1=…`). Given the raw header value, return the parts.
   */
  parse?: (raw: string) => { signature?: string; timestamp?: string };
};

export type InboundDelivery = {
  /** The body EXACTLY as received. Not re-serialised. See `webhook.ts`. */
  raw: string;
  headers: Record<string, string | string[] | undefined>;
};

/**
 * Verify an inbound delivery against a trigger's declared scheme.
 *
 * A trigger with no `verification` REFUSES rather than accepts. That asymmetry
 * is the whole safety property: an unverifiable endpoint is a stranger's button
 * for starting workflows in your account, and defaulting to "allow" would make
 * every misconfiguration into an open door that looks shut.
 */
export async function verifyDelivery(
  trigger: TriggerDescriptor,
  delivery: InboundDelivery,
  secret: string | undefined,
  now?: number,
): Promise<WebhookVerification> {
  const spec = trigger.verification;

  if (!spec) {
    return {
      ok: false,
      reason: `${trigger.service}.${trigger.operation} declares no signature scheme, so a delivery cannot be trusted.`,
    };
  }

  const rawHeader = header(delivery.headers, spec.signatureHeader);
  const parsed = spec.parse && rawHeader ? spec.parse(rawHeader) : { signature: rawHeader };
  const timestamp = parsed.timestamp
    ?? (spec.timestampHeader ? header(delivery.headers, spec.timestampHeader) : undefined);

  return verifyHmac({
    raw: delivery.raw,
    signature: parsed.signature,
    secret,
    scheme: spec.scheme,
    timestamp,
    ...(now === undefined ? {} : { now }),
  });
}

/**
 * The event a trigger node publishes when it runs.
 *
 * Three sources, in order, and the third is why a connector trigger is usable
 * on day one:
 *
 * 1. A verified delivery the host injected on the `in` port.
 * 2. Nothing injected, but the connection is remote — that is a host wiring
 *    error, and it fails loudly rather than emitting a plausible blank.
 * 3. `fake` mode — the trigger emits its own sample event, so an author can
 *    press Run, see the real field names, and wire the downstream nodes against
 *    them before the provider has ever been contacted.
 */
export function triggerEvent(
  trigger: TriggerDescriptor,
  connection: ResolvedConnection,
  injected: unknown,
  config: Record<string, unknown>,
): unknown {
  if (hasDelivery(injected)) return injected;

  if (connection.mode === "fake") {
    return trigger.faker(
      trigger.operation,
      fakeRequest(trigger.service, trigger.operation, config),
    );
  }

  throw new Error(
    `${trigger.service}.${trigger.operation}: no event was delivered to this trigger. ` +
      `Its delivery mechanism is "${trigger.delivery}" — ${trigger.setup} ` +
      'Set the node\'s mode to "fake" to design against a sample event instead.',
  );
}

/**
 * Whether a value on the `in` port is an actual delivery.
 *
 * An EMPTY object or array counts as nothing delivered, and that is not
 * fussiness: a manually started run seeds `{}` on the trigger's input, so a
 * bare null check would hand the executor an empty envelope and call it an
 * event. Downstream every field would be `null`, the run would be green, and
 * nothing would say the trigger never fired.
 */
function hasDelivery(value: unknown): boolean {
  if (value === undefined || value === null) return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "object") return Object.keys(value as object).length > 0;

  return true;
}

/**
 * Verifying an inbound provider webhook.
 *
 * An unverified webhook endpoint is a public, unauthenticated way to start a
 * workflow in someone's account — which is to say, a way for a stranger to make
 * your app refund an order or post to your Slack. So verification is part of the
 * connector pattern rather than an exercise for the host: a trigger node that
 * cannot verify its deliveries must say so, and a host must not be able to mount
 * one by accident.
 *
 * ## The three things every provider's scheme actually needs
 *
 * Providers differ in header names and in what exactly gets signed, and almost
 * nothing else:
 *
 * 1. **The RAW body.** Signatures are computed over bytes. Re-serialising parsed
 *    JSON changes key order and whitespace and produces a signature mismatch
 *    that looks like a wrong secret. The host must pass the body it received.
 * 2. **A constant-time comparison.** `===` on a signature leaks, through timing,
 *    which prefix was right. That is a real forgery path, not a theoretical one.
 * 3. **A timestamp tolerance.** Without it a valid signature is valid forever,
 *    so anyone who ever saw one delivery can replay it whenever they like.
 *
 * WebCrypto rather than `node:crypto`, so the same file runs on Node, Bun, Deno
 * and an edge runtime. Node 22 is the suite's floor and has it globally.
 */

export type WebhookVerification =
  | { ok: true }
  | { ok: false; reason: string };

export type HmacScheme = {
  /** Hash to use. */
  algorithm: "SHA-256" | "SHA-1" | "SHA-512";
  /**
   * Build the exact string that gets signed. Providers differ here more than
   * anywhere else — Stripe signs `${timestamp}.${body}`, Slack signs
   * `v0:${timestamp}:${body}`, GitHub signs the body alone.
   */
  payload: (raw: string, timestamp?: string) => string;
  /** Seconds a delivery stays acceptable. */
  tolerance?: number;
  /** Encoding of the signature the provider sends. */
  encoding?: "hex" | "base64";
};

/**
 * Verify an HMAC-signed delivery.
 *
 * Returns a RESULT rather than throwing, and the failure carries a reason: a
 * host wants to log which check failed (stale? wrong secret? no header?) while
 * still answering the provider with an opaque 400.
 */
export async function verifyHmac(options: {
  raw: string;
  signature: string | undefined;
  secret: string | undefined;
  scheme: HmacScheme;
  timestamp?: string;
  /** Seconds since the epoch. Injected so tests are not clock-dependent. */
  now?: number;
}): Promise<WebhookVerification> {
  const { raw, signature, secret, scheme, timestamp } = options;

  if (!secret) {
    // Never "accept when unconfigured". An endpoint that verifies nothing
    // because nobody set a secret is strictly worse than one that is off: it
    // looks protected.
    return { ok: false, reason: "no signing secret configured for this trigger" };
  }
  if (!signature) return { ok: false, reason: "delivery carried no signature header" };

  if (scheme.tolerance !== undefined) {
    if (!timestamp) return { ok: false, reason: "delivery carried no timestamp header" };

    const sent = Number(timestamp);
    if (!Number.isFinite(sent)) return { ok: false, reason: "timestamp header is not a number" };

    const now = options.now ?? Math.floor(Date.now() / 1000);
    if (Math.abs(now - sent) > scheme.tolerance) {
      return { ok: false, reason: `delivery is outside the ${scheme.tolerance}s replay window` };
    }
  }

  const expected = await hmac(secret, scheme.payload(raw, timestamp), scheme.algorithm, scheme.encoding ?? "hex");

  return constantTimeEquals(expected, signature)
    ? { ok: true }
    : { ok: false, reason: "signature did not match" };
}

/** HMAC of `payload` under `secret`, hex or base64 encoded. */
export async function hmac(
  secret: string,
  payload: string,
  algorithm: HmacScheme["algorithm"],
  encoding: "hex" | "base64" = "hex",
): Promise<string> {
  const subtle = globalThis.crypto?.subtle;

  if (!subtle) {
    throw new Error(
      "WebCrypto is not available in this runtime, so webhook signatures cannot be verified. " +
        "Refusing to accept deliveries unverified.",
    );
  }

  const encoder = new TextEncoder();
  const key = await subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: algorithm },
    false,
    ["sign"],
  );
  const bytes = new Uint8Array(await subtle.sign("HMAC", key, encoder.encode(payload)));

  if (encoding === "base64") {
    let binary = "";
    bytes.forEach((byte) => {
      binary += String.fromCharCode(byte);
    });

    return btoa(binary);
  }

  return Array.from(bytes)
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Compare two strings without leaking where they diverge.
 *
 * The length check first is deliberate and safe: a signature's length is fixed
 * by its algorithm and is not a secret, so revealing a mismatch there tells an
 * attacker nothing they could not compute.
 */
export function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) return false;

  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);

  return diff === 0;
}

/**
 * Pull one header case-insensitively.
 *
 * Header case is not preserved consistently across proxies, frameworks and
 * runtimes; a connector that read `req.headers["Stripe-Signature"]` would work
 * behind one server and reject every delivery behind another.
 */
export function header(headers: Record<string, string | string[] | undefined>, name: string): string | undefined {
  const wanted = name.toLowerCase();

  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() !== wanted) continue;

    return Array.isArray(value) ? value[0] : value;
  }

  return undefined;
}

/**
 * Stripe's identity on the authoring surface, shared by every Stripe node.
 *
 * `ui/` lands on EVERY host — a PHP project vendors `ui/` and `php/` and never
 * `js/` — so this file must import nothing from `js/`. The vendoring test in
 * `tests/js/flow-nodes/vendoring.test.ts` fails the build if it does, because
 * that import is a dangling module the moment the node is copied for PHP.
 */

import type { ConnectorMeta } from "../../_connector/ui/connector";

/** The parts of a connector's identity that belong to the SERVICE, not the node. */
export const STRIPE_SERVICE = {
  service: "stripe",
  serviceTitle: "Stripe",
  domain: "payments",
  sandbox: "credential",
} as const satisfies Pick<ConnectorMeta, "service" | "serviceTitle" | "domain" | "sandbox">;

/** Build a Stripe node's connector metadata from the operation it performs. */
export function stripeMeta(
  role: ConnectorMeta["role"],
  operation: string,
  docs: string,
): ConnectorMeta {
  return { ...STRIPE_SERVICE, role, operation, docs };
}

/**
 * Stripe, as one service descriptor shared by every Stripe node.
 *
 * ## Why a per-service shared directory
 *
 * `_connector` carries what is true of ALL connectors. This carries what is
 * true of Stripe: its base URL, its auth scheme, its idempotency header, its
 * webhook signature format, and its faker. Six Stripe nodes would otherwise
 * retype all of that six times, and the day Stripe changes something, five of
 * the six would keep the old answer.
 *
 * Vendoring any Stripe node copies `_connector` and `_stripe` alongside it. Both
 * are source in the consumer's project, editable in place, and neither is a
 * package.
 *
 * ## The sandbox trap, written down where it is used
 *
 * Stripe's test estate is selected by the KEY, not by the URL —
 * `api.stripe.com` serves both. So a live key sent to a node whose mode says
 * "sandbox" reaches the real ledger and succeeds. Nothing in the request
 * distinguishes them; the only guard is which credential the connection holds,
 * which is exactly why credentials sit on the connection rather than on twelve
 * separate nodes.
 */

import type { ConnectorFaker, FakeRequest } from "../../_connector/js/faker";
import type { ServiceDescriptor } from "../../_connector/js/client";
import type { HmacScheme } from "../../_connector/js/webhook";

const API = "https://api.stripe.com";

/**
 * Stripe's webhook signature scheme.
 *
 * `Stripe-Signature: t=1700000000,v1=<hex>`, where the signed payload is
 * `${t}.${rawBody}` under HMAC-SHA256, and the default replay window is five
 * minutes. The timestamp travels INSIDE the signature header rather than in one
 * of its own, which is why `verification.parse` exists.
 */
export const STRIPE_SIGNATURE_SCHEME: HmacScheme = {
  algorithm: "SHA-256",
  payload: (raw, timestamp) => `${timestamp}.${raw}`,
  tolerance: 300,
  encoding: "hex",
};

/** Split `t=…,v1=…` into its parts. Unknown schemes (`v0=…`) are ignored. */
export function parseStripeSignature(raw: string): { signature?: string; timestamp?: string } {
  const parts = raw.split(",").map((part) => part.trim());
  const result: { signature?: string; timestamp?: string } = {};

  for (const part of parts) {
    const [key, value] = part.split("=", 2);
    if (key === "t") result.timestamp = value;
    // Stripe may send several `v1` signatures during a secret rotation. Taking
    // the first is what the verification loop expects; a rotation window is
    // rare enough that failing over to a second is not worth the ambiguity of
    // "which one matched".
    if (key === "v1" && !result.signature) result.signature = value;
  }

  return result;
}

/**
 * The faker.
 *
 * Shapes, not behaviour: the goal is that a downstream node sees the field
 * NAMES Stripe actually publishes, so an author can wire `{{ $json.data.id }}`
 * against a fake and have it keep working against the real thing. Amounts and
 * ids are deterministic, and every value is visibly synthetic.
 */
export const stripeFaker: ConnectorFaker = (operation, request) => {
  const { fake, config } = request;

  switch (operation) {
    case "payment_intent_create":
      return paymentIntent(config, fake);

    case "refund_create":
      return {
        id: fake.id("re"),
        object: "refund",
        amount: Number(config.amount ?? 0) || fake.int(500, 25000),
        currency: String(config.currency ?? "usd"),
        payment_intent: String(config.paymentIntent ?? fake.id("pi")),
        reason: config.reason ? String(config.reason) : null,
        status: "succeeded",
        created: 1767225600,
      };

    case "customer_create":
      return {
        id: fake.id("cus"),
        object: "customer",
        email: String(config.email ?? "ada@example.test"),
        name: config.name ? String(config.name) : null,
        created: 1767225600,
        livemode: false,
      };

    default:
      // A faker asked for an operation it has no shape for must SAY so. Making
      // something up would produce a green run whose output silently has none
      // of the fields the author is about to reference.
      throw new Error(
        `stripe: no fake response is defined for "${operation}". ` +
          "Add one to stripeFaker before shipping a node that calls it — a connector without a faker " +
          "cannot be developed against, tested, or demonstrated.",
      );
  }
};

function paymentIntent(config: Record<string, unknown>, fake: FakeRequest["fake"]) {
  const amount = Number(config.amount ?? 0) || fake.int(500, 25000);

  return {
    id: fake.id("pi"),
    object: "payment_intent",
    amount,
    amount_received: amount,
    currency: String(config.currency ?? "usd"),
    customer: config.customer ? String(config.customer) : null,
    description: config.description ? String(config.description) : null,
    status: "succeeded",
    // `livemode: false` is not decoration. It is the field a downstream branch
    // reads to refuse to act on test data, and a faker that reported `true`
    // would make that branch untestable.
    livemode: false,
    created: 1767225600,
    latest_charge: fake.id("ch"),
    receipt_email: config.receiptEmail ? String(config.receiptEmail) : null,
  };
}

/** The Stripe service, for the TypeScript runtime. */
export const STRIPE: ServiceDescriptor = {
  service: "stripe",
  title: "Stripe",
  // Same host for both estates — the key decides. See the note at the top.
  sandbox: "credential",
  baseUrls: { live: API, sandbox: API },
  requires: ["secretKey"],
  // Bearer, not Basic. Stripe accepts the key as a Basic username too, and both
  // are documented, but one spelling in one place is one fewer thing to get
  // subtly wrong.
  authorize: (credentials, request) => {
    request.headers.Authorization = `Bearer ${credentials.secretKey}`;
  },
  // Retried durable runs MUST not create a second charge. This is the header
  // that makes `unsafe-to-replay` recoverable rather than merely forbidden.
  idempotencyHeader: "Idempotency-Key",
  faker: stripeFaker,
};

/**
 * Stripe's webhook trigger — the delivery contract, shared by its trigger nodes.
 *
 * Kept beside the service descriptor rather than inside a node, because a
 * signature scheme is a fact about STRIPE. Two Stripe triggers must not be able
 * to disagree about how a delivery is verified.
 */

import type { ConnectorFaker } from "../../_connector/js/faker";
import type { InboundDelivery, TriggerDescriptor } from "../../_connector/js/trigger";
import { verifyDelivery } from "../../_connector/js/trigger";
import type { WebhookVerification } from "../../_connector/js/webhook";
import { parseStripeSignature, STRIPE_SIGNATURE_SCHEME } from "./service";

/**
 * A sample event per type.
 *
 * The point is the SHAPE — an author wiring `{{ $json.data.object.amount }}`
 * against a fake must find the same path when a real delivery arrives. So these
 * mirror Stripe's envelope exactly: `id`, `type`, `created`, `livemode`, and the
 * object under `data.object`.
 */
export const stripeEventFaker: ConnectorFaker = (operation, request) => {
  const { fake, config } = request;
  const type = String(config.sample ?? "payment_intent.succeeded");

  const object = (() => {
    switch (type) {
      case "charge.refunded":
        return {
          id: fake.id("ch"),
          object: "charge",
          amount: 2500,
          amount_refunded: 2500,
          currency: "usd",
          status: "succeeded",
          refunded: true,
        };
      case "checkout.session.completed":
        return {
          id: fake.id("cs"),
          object: "checkout.session",
          amount_total: 2500,
          currency: "usd",
          status: "complete",
          payment_status: "paid",
          customer_email: "ada@example.test",
        };
      case "customer.subscription.deleted":
        return {
          id: fake.id("sub"),
          object: "subscription",
          status: "canceled",
          customer: fake.id("cus"),
          canceled_at: 1767225600,
        };
      default:
        return {
          id: fake.id("pi"),
          object: "payment_intent",
          amount: 2500,
          amount_received: 2500,
          currency: "usd",
          status: "succeeded",
        };
    }
  })();

  return {
    id: fake.id("evt"),
    object: "event",
    type,
    api_version: "2026-01-01",
    created: 1767225600,
    // Never `true`. A faked event that claimed to be live money would make the
    // downstream guard — "only act when livemode" — untestable, which is the
    // one branch you most want covered.
    livemode: false,
    data: { object },
  };
};

export const STRIPE_WEBHOOK_TRIGGER: TriggerDescriptor = {
  service: "stripe",
  operation: "webhook",
  delivery: "webhook",
  setup:
    "Add an endpoint in the Stripe dashboard (or via POST /v1/webhook_endpoints) pointing at the route your " +
    "host mounts for this trigger, then put the endpoint's signing secret on the connection as `webhookSecret`.",
  verification: {
    signatureHeader: "Stripe-Signature",
    scheme: STRIPE_SIGNATURE_SCHEME,
    // Stripe packs the timestamp INTO the signature header (`t=…,v1=…`) rather
    // than sending one of its own, so it has to be parsed out before the HMAC
    // can be computed over `{t}.{body}`.
    parse: parseStripeSignature,
  },
  faker: stripeEventFaker,
};

/**
 * Verify one inbound Stripe delivery.
 *
 * The host calls this BEFORE starting a run, with the body exactly as received.
 * Re-serialised JSON changes key order and whitespace, and produces a mismatch
 * that looks precisely like a wrong secret — hours of debugging the wrong thing.
 */
export function verifyStripeDelivery(
  delivery: InboundDelivery,
  webhookSecret: string | undefined,
  now?: number,
): Promise<WebhookVerification> {
  return verifyDelivery(STRIPE_WEBHOOK_TRIGGER, delivery, webhookSecret, now);
}

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";

import { callConnector } from "../../_connector/js/client";
import { TELEGRAM } from "../../_telegram/js/service";
import { nextOffset } from "../../_telegram/js/trigger";

type TelegramUpdate = { update_id?: number };

/**
 * Poll Telegram for updates.
 *
 * ## A poll trigger DOES call the provider
 *
 * That is what makes it different from a webhook trigger, whose executor only
 * republishes what the host already verified. Here the executor is the fetch, so
 * the host's job is a schedule and a persisted cursor rather than a route.
 *
 * In `fake` mode the call resolves to the faker, so the node is runnable on a
 * canvas before a bot exists — with the same envelope a real poll returns.
 */
export const telegramUpdatesTriggerExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;

  const result = await callConnector<{ ok?: boolean; result?: TelegramUpdate[]; description?: string }>(
    TELEGRAM,
    {
      operation: "get_updates",
      config,
      request: {
        method: "GET",
        path: "getUpdates",
        query: {
          ...(config.offset === undefined || config.offset === null || config.offset === ""
            ? {}
            : { offset: Number(config.offset) }),
          limit: Math.min(100, Math.max(1, Number(config.limit ?? 100))),
          ...(typeof config.allowedUpdates === "string" && config.allowedUpdates.trim() !== ""
            ? { allowed_updates: JSON.stringify(list(config.allowedUpdates)) }
            : {}),
        },
      },
    },
  );

  // Telegram answers 200 with `{ok: false, description}` for application-level
  // failures, so an HTTP status check alone would treat a rejection as success
  // and publish an empty batch. The connector core cannot know that; this is
  // exactly the per-provider knowledge a node exists to hold.
  if (result.data?.ok === false) {
    throw new Error(
      `telegram_updates_trigger: getUpdates was rejected — ${result.data.description ?? "no reason given"}`,
    );
  }

  const updates = Array.isArray(result.data?.result) ? result.data.result : [];
  const cursor = nextOffset(updates, config.offset === undefined ? undefined : Number(config.offset));

  const value = {
    mode: result.mode,
    connection: result.connection,
    cursor,
    count: updates.length,
    updates,
    update: updates[0] ?? null,
  };

  if (updates.length === 0) {
    // A poll that found nothing is the NORMAL case, not a failure. Routing it
    // to its own port keeps the main path meaning "something happened" — and
    // still gives the host somewhere to hang cursor bookkeeping.
    return { __port: "empty", value };
  }

  ctx.emit({
    type: "log",
    level: "info",
    nodeId: ctx.node.id,
    message: `telegram: ${updates.length} update(s), next offset ${cursor} (${result.mode})`,
  });

  return { __port: "out", value };
};

function list(value: string): string[] {
  return value
    .split(",")
    .map((item) => item.trim())
    .filter(Boolean);
}

import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { telegramUpdatesTriggerKind } from "../ui/kind";
import { telegramUpdatesTriggerExecutor } from "./executor";

/** The kind with its TypeScript executor attached — for hosts that EXECUTE on TS. */
export const telegramUpdatesTriggerRunnableKind: NodeKindDefinition = {
  ...telegramUpdatesTriggerKind,
  executor: telegramUpdatesTriggerExecutor,
};

/**
 * The authoring surface every connector node shares.
 *
 * ## The model, and where it came from
 *
 * IFTTT's authoring UX is the one non-engineers actually complete, and three of
 * its four ideas map onto fancy-flow without distortion:
 *
 * 1. **Service first, then capability.** You pick Stripe, *then* pick what about
 *    Stripe. Not a flat wall of four hundred nodes. Here that lives in the
 *    registry — `connector.service` groups a provider's nodes, and the listing
 *    tools narrow in two steps.
 * 2. **The connection is a thing, not a field.** You authorize a service once
 *    and every applet reuses it. Here: `connection.ts` in the runtime, and the
 *    single `connection` config field below.
 * 3. **Ingredients.** A trigger's output fields become named tokens you drop
 *    into a downstream action's fields. fancy-flow already has the machinery —
 *    `outputShape` on the kind, `availableVariables()` reading it off direct
 *    predecessors — so a connector's job is simply to DECLARE its shape. See
 *    `ingredients.ts`.
 * 4. **A sentence, not a form dump.** `summarize()` below.
 *
 * ## Where it does NOT map, and what we did instead
 *
 * An IFTTT applet is one trigger and one action, so "the ingredients" is
 * unambiguous: there is only one upstream. A fancy-flow graph branches, fans
 * out, merges and nests, so a connector node several hops downstream has no
 * single trigger to draw from — `availableVariables()` deliberately offers only
 * DIRECT predecessors, because a grandparent's field resolves to `null` at run
 * time and a suggestion that silently produces nothing is worse than no
 * suggestion.
 *
 * We did not paper over that. Connector triggers publish their event as a
 * single object with a declared shape, so the natural thing an author does —
 * carry it forward on the wire — keeps the ingredients available at each step.
 * Reaching further up the graph is a fancy-flow concern, recorded as a finding
 * rather than reimplemented per node.
 */

import type { ConfigField, NodeKindDefinition, OutputField } from "@particle-academy/fancy-flow/engine";

/** The domains the catalogue is grouped by. Mirrors the plan's taxonomy. */
export type ConnectorDomain =
  | "payments"
  | "commerce"
  | "messaging"
  | "email"
  | "crm"
  | "support"
  | "storage"
  | "calendar"
  | "productivity"
  | "database"
  | "devtools"
  | "analytics"
  | "marketing"
  | "ai"
  | "forms"
  | "hr"
  | "geo";

/** What a connector node does in the graph — IFTTT's "this" versus "that". */
export type ConnectorRole = "trigger" | "action" | "search";

/** How the provider exposes a test estate. Kept in step with the runtime's `SandboxKind`. */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

export type ConnectorMeta = {
  service: string;
  serviceTitle: string;
  domain: ConnectorDomain;
  role: ConnectorRole;
  /** The provider's name for this operation, so search finds what people type. */
  operation: string;
  sandbox: SandboxKind;
  /** Link to the provider documentation this node was written against. */
  docs?: string;
};

/**
 * The two fields EVERY connector node carries, in the same order, with the same
 * keys.
 *
 * Uniformity is the feature. An agent that has configured one connector has
 * configured all of them, and a human who has learned where the sandbox switch
 * lives never has to look for it again.
 */
export function connectionFields(meta: ConnectorMeta): ConfigField[] {
  const modes: Array<{ value: string; label: string }> = [
    { value: "auto", label: "Auto — sandbox locally, live in production" },
    { value: "fake", label: "Fake — no credentials, no network" },
  ];

  // Only offer sandbox where one exists. A select listing a mode the provider
  // does not have is an invitation to pick it and then read an error.
  if (meta.sandbox !== "none") {
    modes.push({ value: "sandbox", label: sandboxLabel(meta.sandbox) });
  }
  modes.push({ value: "live", label: "Live — the real account" });

  return [
    {
      type: "credential",
      key: "connection",
      label: `${meta.serviceTitle} connection`,
      credentialType: `connector:${meta.service}`,
      description:
        `Which configured ${meta.serviceTitle} connection to use. Credentials live in the host's ` +
        "configuration, never in the workflow — a graph is exported, committed and handed to agents.",
    },
    {
      type: "select",
      key: "mode",
      label: "Environment",
      options: modes,
      default: "auto",
      description:
        meta.sandbox === "none"
          ? `${meta.serviceTitle} has no sandbox estate, so "auto" means fake locally and live in production.`
          : "Auto follows the environment. Setting this explicitly overrides it everywhere, including in production.",
    },
  ];
}

function sandboxLabel(kind: SandboxKind): string {
  return kind === "base-url"
    ? "Sandbox — the provider's separate test host"
    : kind === "separate-account"
      ? "Sandbox — your separate test account"
      : "Sandbox — the provider's test estate";
}

/**
 * Build a connector node's authoring surface.
 *
 * Prepends the shared connection fields, applies the domain accent, and stamps
 * the metadata the registry reads. A connector that hand-rolled these would
 * drift from its siblings in exactly the small ways that make a catalogue feel
 * like a pile.
 */
export function defineConnectorKind(
  meta: ConnectorMeta,
  kind: Omit<NodeKindDefinition, "category"> & { category?: NodeKindDefinition["category"] },
): NodeKindDefinition & { connector: ConnectorMeta } {
  return {
    ...kind,
    // `category` stays fancy-flow's own taxonomy — it describes what the node
    // does to the GRAPH, which is what the palette groups by. Connector-ness is
    // a separate axis and is carried separately; overloading one field with two
    // meanings would make "show me the triggers" and "hide the connectors"
    // impossible to ask at the same time.
    category: kind.category ?? (meta.role === "trigger" ? "trigger" : "io"),
    accent: kind.accent ?? DOMAIN_ACCENT[meta.domain],
    configSchema: [...connectionFields(meta), ...(kind.configSchema ?? [])],
    connector: meta,
  };
}

/**
 * One line describing what a configured node will do, in IFTTT's register.
 *
 * A configured connector should read as a sentence, not as a form dump — it is
 * what makes a canvas skimmable, and it is also what an agent quotes back to a
 * human when asking whether to proceed.
 */
export function summarize(meta: ConnectorMeta, config: Record<string, unknown>, detail?: string): string {
  const mode = typeof config.mode === "string" ? config.mode : "auto";
  const where =
    mode === "fake"
      ? " (faked — nothing leaves this machine)"
      : mode === "sandbox"
        ? " in the sandbox"
        : mode === "live"
          ? " on the live account"
          : "";

  const what = detail?.trim() ? detail.trim() : meta.operation.replace(/_/g, " ");

  return meta.role === "trigger"
    ? `When ${meta.serviceTitle} reports ${what}${where}`
    : `Then ${meta.serviceTitle} will ${what}${where}`;
}

/** Declare a trigger's event fields — the "ingredients" downstream nodes pick from. */
export function ingredients(fields: OutputField[]): OutputField[] {
  return fields;
}

const DOMAIN_ACCENT: Record<ConnectorDomain, string> = {
  payments: "#635bff",
  commerce: "#96bf48",
  messaging: "#4a154b",
  email: "#0f9d58",
  crm: "#00a1e0",
  support: "#03363d",
  storage: "#ff9900",
  calendar: "#4285f4",
  productivity: "#2f3437",
  database: "#336791",
  devtools: "#24292f",
  analytics: "#f9a03c",
  marketing: "#1877f2",
  ai: "#d97757",
  forms: "#262627",
  hr: "#5c4ee5",
  geo: "#34a853",
};

/**
 * The one call path every connector node uses.
 *
 * A node's executor never chooses between "call the provider" and "call the
 * faker" — it describes the request it wants and hands it here. That is the
 * point: the code path a consumer develops against with no credentials is the
 * same code path that runs in production, so the fixtures prove something about
 * the executor rather than about a mock.
 *
 * ```ts
 * const charge = await callConnector(STRIPE, {
 *   operation: "charge_create",
 *   config,
 *   input: ctx.inputs.in,
 *   request: { method: "POST", path: "/v1/charges", form: { amount, currency } },
 *   idempotencyKey: `${ctx.node.id}:${runKey}`,
 * });
 * ```
 */

import { resolveConnection, type ConnectionCredentials, type ResolvedConnection } from "./connection";
import { classifyHttp, ConnectorConfigError, ConnectorError, ConnectorTransient } from "./errors";
import { fakeRequest, type ConnectorFaker } from "./faker";
import type { ConnectorMode, RequestedMode, SandboxKind } from "./mode";

/**
 * Everything true of a SERVICE rather than of one operation.
 *
 * One of these per provider, declared once and shared by that provider's nodes.
 * It is data — base URLs, which credential keys are required, how the sandbox
 * is selected — so that facts we verified against provider documentation live
 * in exactly one reviewable place instead of being retyped into each node.
 */
export type ServiceDescriptor = {
  service: string;
  title: string;
  sandbox: SandboxKind;
  /**
   * Base URL per mode. A `credential`-sandbox provider gives the same URL for
   * both, which is itself worth writing down: it is why a live key pointed at
   * "sandbox" quietly reaches production.
   */
  baseUrls: Partial<Record<ConnectorMode, string>>;
  /** Credential keys a remote call cannot proceed without. */
  requires: string[];
  /**
   * Apply the provider's auth scheme to an outgoing request.
   *
   * Receives the resolved MODE as well, because for some providers auth and
   * estate are the same decision expressed in the URL — Telegram puts the bot
   * token in the path and selects its test environment with a `/test` segment
   * after it. A signature that hid the mode would push those providers towards
   * a global, which is the thing this seam exists to avoid.
   */
  authorize: (
    credentials: ConnectionCredentials,
    request: PreparedRequest,
    mode: ConnectorMode,
  ) => void | Promise<void>;
  /** The service's faker. Required — see `faker.ts`. */
  faker: ConnectorFaker;
  /** Header the provider uses for idempotency, when it has one. */
  idempotencyHeader?: string;
};

export type ConnectorRequest = {
  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  path: string;
  query?: Record<string, string | number | boolean | undefined>;
  headers?: Record<string, string>;
  /** JSON body. Mutually exclusive with `form`. */
  json?: unknown;
  /** `application/x-www-form-urlencoded` body — what several payment APIs want. */
  form?: Record<string, string | number | boolean | undefined>;
};

export type PreparedRequest = {
  method: string;
  url: string;
  headers: Record<string, string>;
  body?: string;
};

export type CallOptions = {
  operation: string;
  config: Record<string, unknown>;
  input?: unknown;
  request: ConnectorRequest;
  /**
   * Value for the provider's idempotency header. Pass something derived from
   * the run and the node, never a fresh uuid: the entire point is that a RETRY
   * carries the same key.
   */
  idempotencyKey?: string;
  /** Retry budget for retryable failures. Defaults to 2 extra attempts. */
  retries?: number;
};

/** The HTTP seam. A host may swap it; nothing here assumes a browser or Node. */
export type Transport = (request: PreparedRequest) => Promise<TransportResponse>;

export type TransportResponse = {
  status: number;
  headers: Record<string, string>;
  body: string;
};

let transport: Transport | null = null;

/** Install a transport. Only needed if the runtime has no global `fetch`. */
export function registerTransport(next: Transport | null): void {
  transport = next;
}

/** What a connector call returns, alongside the provider's own payload. */
export type ConnectorResult<T = unknown> = {
  data: T;
  /** Which estate this actually ran against. Always reported, never inferred. */
  mode: ConnectorMode;
  connection: string;
};

export async function callConnector<T = unknown>(
  service: ServiceDescriptor,
  options: CallOptions,
): Promise<ConnectorResult<T>> {
  const connection = resolveConnection({
    service: service.service,
    operation: options.operation,
    connectionId: readString(options.config, "connection"),
    requested: readString(options.config, "mode") as RequestedMode | null,
    sandbox: service.sandbox,
    baseUrls: service.baseUrls,
    requires: service.requires,
  });

  if (connection.mode === "fake") {
    return {
      data: service.faker(
        options.operation,
        fakeRequest(service.service, options.operation, options.config, options.input),
      ) as T,
      mode: "fake",
      connection: connection.id,
    };
  }

  return {
    data: (await remoteCall(service, connection, options)) as T,
    mode: connection.mode,
    connection: connection.id,
  };
}

async function remoteCall(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<unknown> {
  const prepared = await prepare(service, connection, options);
  const send = transport ?? fetchTransport;
  const ctx = { service: service.service, operation: options.operation };
  const budget = options.retries ?? 2;
  let attempt = 0;

  for (;;) {
    let response: TransportResponse;

    try {
      response = await send(prepared);
    } catch (cause) {
      // A thrown transport is a network-level failure: unreachable, reset,
      // timed out. Retryable by nature, and distinct from a 5xx, which at
      // least proves we reached something.
      const error = new ConnectorTransient(
        `${ctx.service}.${ctx.operation}: ${(cause as Error)?.message ?? "transport failed"}`,
        ctx,
      );
      if (attempt++ >= budget) throw error;
      await sleep(backoffMs(attempt));

      continue;
    }

    if (response.status < 400) {
      return response.body.trim() === "" ? null : parseJson(response.body, ctx);
    }

    const error = classifyHttp(
      response.status,
      ctx,
      response.body,
      readRetryAfter(response.headers),
    );

    if (!error.retryable || attempt++ >= budget) throw error;

    // Honour the provider's own instruction when it gave one. Guessing shorter
    // than they asked is how a throttle becomes a ban.
    const wait = "retryAfter" in error && typeof error.retryAfter === "number"
      ? error.retryAfter * 1000
      : backoffMs(attempt);
    await sleep(wait);
  }
}

async function prepare(
  service: ServiceDescriptor,
  connection: ResolvedConnection,
  options: CallOptions,
): Promise<PreparedRequest> {
  const base = connection.baseUrl ?? service.baseUrls[connection.mode];

  if (!base) {
    throw new ConnectorConfigError(
      `${service.service}: no base URL for "${connection.mode}" mode. ` +
        "The service descriptor must declare one per mode it supports.",
      { service: service.service, operation: options.operation },
    );
  }

  const { method, path, query, headers, json, form } = options.request;
  const url = new URL(path.replace(/^\/+/, ""), base.endsWith("/") ? base : `${base}/`);

  for (const [key, value] of Object.entries(query ?? {})) {
    if (value !== undefined) url.searchParams.set(key, String(value));
  }

  const prepared: PreparedRequest = {
    method,
    url: url.toString(),
    headers: { Accept: "application/json", ...headers },
  };

  if (form) {
    prepared.headers["Content-Type"] = "application/x-www-form-urlencoded";
    prepared.body = encodeForm(form);
  } else if (json !== undefined) {
    prepared.headers["Content-Type"] = "application/json";
    prepared.body = JSON.stringify(json);
  }

  if (options.idempotencyKey && service.idempotencyHeader) {
    prepared.headers[service.idempotencyHeader] = options.idempotencyKey;
  }

  await service.authorize(connection.credentials, prepared, connection.mode);

  return prepared;
}

/**
 * Form encoding, including the bracketed-nesting several payment APIs use
 * (`metadata[order_id]=7`). Flat maps pass through unchanged.
 */
function encodeForm(form: Record<string, unknown>): string {
  const pairs: string[] = [];

  const walk = (prefix: string, value: unknown): void => {
    if (value === undefined || value === null) return;
    if (typeof value === "object" && !Array.isArray(value)) {
      for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
        walk(prefix === "" ? key : `${prefix}[${key}]`, nested);
      }

      return;
    }
    if (Array.isArray(value)) {
      value.forEach((item, index) => walk(`${prefix}[${index}]`, item));

      return;
    }
    pairs.push(`${encodeURIComponent(prefix)}=${encodeURIComponent(String(value))}`);
  };

  walk("", form);

  return pairs.join("&");
}

const fetchTransport: Transport = async (request) => {
  const globalFetch = (globalThis as { fetch?: typeof fetch }).fetch;

  if (!globalFetch) {
    throw new Error(
      "no global fetch in this runtime — call registerTransport() with one before running a connector remotely.",
    );
  }

  const response = await globalFetch(request.url, {
    method: request.method,
    headers: request.headers,
    ...(request.body === undefined ? {} : { body: request.body }),
  });

  const headers: Record<string, string> = {};
  response.headers.forEach((value, key) => {
    headers[key.toLowerCase()] = value;
  });

  return { status: response.status, headers, body: await response.text() };
};

function parseJson(body: string, ctx: { service: string; operation: string }): unknown {
  try {
    return JSON.parse(body);
  } catch {
    throw new ConnectorError(
      `${ctx.service}.${ctx.operation}: the provider returned a body that is not JSON.`,
      ctx,
    );
  }
}

function readRetryAfter(headers: Record<string, string>): number | undefined {
  const raw = headers["retry-after"];
  if (!raw) return undefined;
  const seconds = Number(raw);

  return Number.isFinite(seconds) ? seconds : undefined;
}

/** Exponential with a ceiling. Attempt 1 → 250ms, 2 → 500ms, 3 → 1s, capped at 8s. */
function backoffMs(attempt: number): number {
  return Math.min(8000, 250 * 2 ** (attempt - 1));
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readString(config: Record<string, unknown>, key: string): string | null {
  const value = config[key];

  return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
}

/**
 * A CONNECTION — credentials plus an environment choice — configured once per
 * service and referenced by every node that uses it.
 *
 * ## Why this is not per-node config
 *
 * The obvious design is to put an API key field on each node. It is also wrong,
 * for three reasons that only show up later:
 *
 * 1. **Rotation.** A key on twelve nodes is twelve edits and one you will miss.
 * 2. **The sandbox/live switch has to live somewhere singular.** If each node
 *    carries its own, a graph can be half in the test estate and half in the
 *    real one, and nothing about the canvas shows it.
 * 3. **Credentials would be in the graph.** A `WorkflowSchema` is plain JSON
 *    that gets exported, committed, MCP'd to an agent and pasted into issues.
 *    Nothing secret may ever be in it.
 *
 * So a node's config stores a **connection id** — an opaque, non-secret name
 * like `"stripe"` or `"stripe-eu"` — and the host resolves it to credentials at
 * run time. This is the same arrangement fancy-flow already uses for LLM clients
 * and `fancy-git` uses for providers: the node cannot reach for a credential,
 * the host has to hand one over.
 *
 * ```ts
 * registerConnectionHost({
 *   environment: { production: process.env.NODE_ENV === "production" },
 *   connections: {
 *     stripe: {
 *       service: "stripe",
 *       live:    { secretKey: process.env.STRIPE_SECRET_KEY },
 *       sandbox: { secretKey: process.env.STRIPE_TEST_SECRET_KEY },
 *     },
 *   },
 * });
 * ```
 *
 * Note what is NOT here: no key, no token, no placeholder that looks like one.
 * Credentials are configuration, and configuration comes from the consumer's
 * environment.
 */

import { ConnectorConfigError } from "./errors";
import {
  ConnectorModeError,
  resolveConnectorMode,
  type ConnectorMode,
  type HostEnvironment,
  type RequestedMode,
  type SandboxKind,
} from "./mode";

/**
 * Credentials for one estate. Values are opaque strings the node's auth
 * strategy understands — `secretKey`, `clientId`/`clientSecret`, `token`.
 */
export type ConnectionCredentials = Record<string, string | undefined>;

/** One configured connection to one service. */
export type ConnectionSpec = {
  /** The service this connection is for — must match the node's `connector.service`. */
  service: string;
  /** Human label, shown in the picker. Defaults to the id. */
  label?: string;
  /**
   * Pin this connection to a mode. Optional, and usually absent: leaving it
   * unset is what lets the environment supply the default.
   */
  mode?: ConnectorMode;
  live?: ConnectionCredentials;
  sandbox?: ConnectionCredentials;
  /**
   * Override the base URL per mode. Only needed for a `separate-account`
   * provider whose tenant has its own host (a Salesforce instance URL); the
   * `base-url` providers carry theirs in the node's service descriptor.
   */
  baseUrl?: Partial<Record<ConnectorMode, string>>;
};

export type ConnectionHost = {
  environment: HostEnvironment;
  connections: Record<string, ConnectionSpec>;
};

let host: ConnectionHost | null = null;

/**
 * Install the host's connections. Returns an unregister function.
 *
 * One registration for the whole app, matching how a person thinks about it:
 * you authorize Stripe once, then every node that needs Stripe already has it.
 */
export function registerConnectionHost(next: ConnectionHost | null): () => void {
  host = next;

  return () => {
    if (host === next) host = null;
  };
}

export function getConnectionHost(): ConnectionHost | null {
  return host;
}

/** Connection ids the host has configured for a service — feeds the picker. */
export function connectionsFor(service: string): Array<{ id: string; label: string }> {
  const current = getConnectionHost();
  if (!current) return [];

  return Object.entries(current.connections)
    .filter(([, spec]) => spec.service === service)
    .map(([id, spec]) => ({ id, label: spec.label ?? id }));
}

/** What a node's executor actually needs, once everything has been resolved. */
export type ResolvedConnection = {
  id: string;
  service: string;
  mode: ConnectorMode;
  /** Empty in `fake` mode — there is nothing to authenticate against. */
  credentials: ConnectionCredentials;
  /** Undefined in `fake` mode. */
  baseUrl?: string;
};

export type ResolveOptions = {
  service: string;
  operation: string;
  /** The connection id from node config. Defaults to the service name. */
  connectionId?: string | null;
  /** The `mode` field from node config. */
  requested?: RequestedMode | null;
  sandbox: SandboxKind;
  /** Base URL per mode, from the node's service descriptor. */
  baseUrls?: Partial<Record<ConnectorMode, string>>;
  /** Credential keys that must be present for a remote call. */
  requires?: string[];
};

/**
 * Resolve the connection and mode for one call.
 *
 * ## `fake` needs no host at all
 *
 * A freshly vendored connector runs before anything is configured, and that is
 * deliberate: it is the difference between a marketplace someone can try and
 * one they can only read about. So the no-host case resolves to `fake` rather
 * than throwing — UNLESS the author explicitly asked for a remote mode, in
 * which case the ask is honoured by failing loudly instead of quietly doing
 * something else.
 */
export function resolveConnection(options: ResolveOptions): ResolvedConnection {
  const { service, operation, sandbox } = options;
  const requestedMode = options.requested ?? "auto";

  // Checked FIRST, before anything about the host, because it is a static fact
  // about the SERVICE. Asking for a sandbox that does not exist should say so
  // whether or not a connection happens to be configured — otherwise the same
  // mistake produces two different errors depending on unrelated state, and the
  // more useful one is the one you never see.
  if (requestedMode === "sandbox" && sandbox === "none") {
    throw new ConnectorModeError(
      `${service} has no sandbox estate, so "sandbox" cannot be honoured. ` +
        'Use "fake" to develop without credentials, or "live" to talk to the provider.',
    );
  }

  const id = options.connectionId?.trim() || service;
  const current = getConnectionHost();
  const spec = current?.connections[id];

  if (spec && spec.service !== service) {
    throw new ConnectorConfigError(
      `connection "${id}" is configured for the "${spec.service}" service, but this node needs "${service}".`,
      { service, operation },
    );
  }

  if (!current || !spec) {
    if (requestedMode !== "auto" && requestedMode !== "fake") {
      throw new ConnectorConfigError(
        `no "${id}" connection is registered, so ${service}.${operation} cannot run in "${requestedMode}" mode. ` +
          "Call registerConnectionHost({ connections: { " +
          `${id}: { service: "${service}", live: { … } } } }) — the node has no credentials of its own ` +
          'and must not invent any. Set the node\'s mode to "fake" to develop without one.',
        { service, operation },
      );
    }

    return { id, service, mode: "fake", credentials: {} };
  }

  const sandboxCreds = spec.sandbox ?? {};
  const mode = resolveConnectorMode({
    requested: requestedMode,
    connectionMode: spec.mode ?? null,
    sandbox,
    hasSandboxCredentials: hasAll(sandboxCreds, options.requires ?? []),
    environment: current.environment,
  });

  if (mode === "fake") {
    return { id, service, mode, credentials: {} };
  }

  const credentials = (mode === "sandbox" ? spec.sandbox : spec.live) ?? {};
  const missing = (options.requires ?? []).filter((key) => !credentials[key]);

  if (missing.length > 0) {
    // Never silently degrade to the faker here. A run that "succeeded" because
    // it quietly stopped talking to the provider is the worst failure this
    // whole design exists to prevent — it is green, it is wrong, and nothing
    // reports it.
    throw new ConnectorConfigError(
      `connection "${id}" has no ${missing.join(", ")} for ${mode} mode. ` +
        `Set connections.${id}.${mode}.${missing[0]}, or run this node in "fake" mode.`,
      { service, operation },
    );
  }

  const baseUrl = spec.baseUrl?.[mode] ?? options.baseUrls?.[mode];

  return { id, service, mode, credentials, ...(baseUrl ? { baseUrl } : {}) };
}

function hasAll(creds: ConnectionCredentials, keys: string[]): boolean {
  return keys.length > 0 && keys.every((key) => Boolean(creds[key]));
}

/**
 * The connector error taxonomy.
 *
 * Durable runs retry, and a retry policy needs to know WHICH KIND of failure it
 * is looking at. "Something went wrong" is not enough information to decide
 * between retrying, pausing for a human, and stopping — so every connector
 * failure is classified at the point it is known, which is inside the connector,
 * not three frames up where the type has already been lost.
 *
 * | class                    | retry? | why |
 * |--------------------------|--------|-----|
 * | `ConnectorConfigError`   | never  | nothing about a second attempt changes an unset key |
 * | `ConnectorAuthError`     | never  | the credential is wrong; hammering it gets accounts locked |
 * | `ConnectorRateLimited`   | yes    | after `retryAfter`, which the provider told us |
 * | `ConnectorTransient`     | yes    | 5xx, timeout, connection reset |
 * | `ConnectorRequestError`  | never  | 4xx we caused; the same request fails the same way |
 */

export type ConnectorErrorContext = {
  service: string;
  operation: string;
  /** HTTP status when there was one. */
  status?: number;
  /** The provider's own error code, when it publishes one. */
  providerCode?: string;
};

/** Base for everything below, so a host can catch the family in one clause. */
export class ConnectorError extends Error {
  readonly service: string;

  readonly operation: string;

  readonly status?: number;

  readonly providerCode?: string;

  /** Whether a second attempt could plausibly succeed. */
  readonly retryable: boolean = false;

  constructor(message: string, ctx: ConnectorErrorContext) {
    super(message);
    this.name = new.target.name;
    this.service = ctx.service;
    this.operation = ctx.operation;
    this.status = ctx.status;
    this.providerCode = ctx.providerCode;
  }
}

/**
 * A required piece of configuration is missing or unusable.
 *
 * The message must name the exact key the consumer has to set. "Stripe is not
 * configured" sends someone reading source; "no `secretKey` on the `stripe`
 * connection — set it via registerConnectionHost" sends them to the line.
 */
export class ConnectorConfigError extends ConnectorError {}

/** The provider rejected the credential. Retrying cannot help. */
export class ConnectorAuthError extends ConnectorError {
  override readonly retryable = false;
}

/** The provider asked us to slow down. */
export class ConnectorRateLimited extends ConnectorError {
  override readonly retryable = true;

  /** Seconds to wait, when the provider said. */
  readonly retryAfter?: number;

  constructor(message: string, ctx: ConnectorErrorContext & { retryAfter?: number }) {
    super(message, ctx);
    this.retryAfter = ctx.retryAfter;
  }
}

/** A 5xx, a timeout, a reset — the provider's problem, and it may pass. */
export class ConnectorTransient extends ConnectorError {
  override readonly retryable = true;
}

/** A 4xx we caused. The same request will fail the same way. */
export class ConnectorRequestError extends ConnectorError {
  override readonly retryable = false;
}

/**
 * Classify an HTTP response into the taxonomy.
 *
 * 429 before the 4xx sweep, deliberately: a rate limit is a 4xx and is the one
 * 4xx that IS worth retrying, so an ordering that checked `>= 400` first would
 * mark every throttle permanent and turn a busy minute into a failed run.
 */
export function classifyHttp(
  status: number,
  ctx: ConnectorErrorContext,
  body: string,
  retryAfter?: number,
): ConnectorError {
  const detail = body.trim() === "" ? "" : ` — ${truncate(body, 400)}`;
  const where = `${ctx.service}.${ctx.operation}`;

  if (status === 429) {
    return new ConnectorRateLimited(`${where}: rate limited by the provider${detail}`, {
      ...ctx,
      status,
      retryAfter,
    });
  }

  if (status === 401 || status === 403) {
    return new ConnectorAuthError(
      `${where}: the provider rejected the credential (${status})${detail}. ` +
        "Check the connection's credentials and that they match the mode you are running in — " +
        "a live key in sandbox, or the reverse, fails exactly like this.",
      { ...ctx, status },
    );
  }

  if (status >= 500) {
    return new ConnectorTransient(`${where}: provider returned ${status}${detail}`, { ...ctx, status });
  }

  return new ConnectorRequestError(`${where}: request rejected with ${status}${detail}`, { ...ctx, status });
}

function truncate(value: string, max: number): string {
  return value.length <= max ? value : `${value.slice(0, max)}…`;
}

/**
 * The faker layer — every connector ships one, always.
 *
 * ## Why every connector, and not just the ones without a sandbox
 *
 * A sandbox still needs an account, a key, a network, and a provider that is
 * up. That is four ways for someone evaluating the kit to get nothing working,
 * before they have learned anything about the kit. A faker removes all four:
 * vendor a node, drop it on a canvas, press run, see a shaped result.
 *
 * It is also what makes the golden fixtures honest. Fixtures run on both
 * runtimes and are the publish gate; if they needed a network they would either
 * be skipped in CI or be flaky, and a flaky gate is one people learn to
 * re-run rather than read.
 *
 * ## Deterministic, not random
 *
 * Same inputs, same output — always. A faker that returns a fresh uuid every
 * call cannot be asserted on, so its fixtures degrade to "it did not throw",
 * which is the assertion that catches nothing. Values here are derived from a
 * seed built out of the service, the operation and the request, so two runs
 * agree and two runtimes can be compared to each other.
 *
 * The values are obviously fake ON PURPOSE — `fake_`-prefixed ids, `example.test`
 * hosts, round numbers. Nobody should ever look at a faked result and wonder
 * whether it moved real money.
 */

/** A faker: one function per service, switching on the operation. */
export type ConnectorFaker = (operation: string, request: FakeRequest) => unknown;

export type FakeRequest = {
  /** The node's resolved config. */
  config: Record<string, unknown>;
  /** The value on the incoming wire. */
  input?: unknown;
  /** Deterministic helpers, seeded from service + operation + config. */
  fake: FakeValues;
};

/**
 * Deterministic value helpers handed to a faker.
 *
 * Small on purpose. A faker's job is to return the SHAPE the provider returns —
 * the field names a downstream node will reference — not to simulate the
 * provider's business logic.
 */
export type FakeValues = {
  /** A stable id with the provider's usual prefix: `id("ch")` → `ch_fake_1a2b3c`. */
  id: (prefix: string) => string;
  /** A stable integer in `[min, max]`. */
  int: (min: number, max: number) => number;
  /** Pick a stable element of a list. */
  pick: <T>(options: readonly T[]) => T;
  /** A fixed ISO-8601 instant, offset by whole seconds. Never `Date.now()`. */
  timestamp: (offsetSeconds?: number) => string;
  /** A stable lowercase hex string of `length` characters. */
  hex: (length: number) => string;
};

/**
 * The instant every faker counts from.
 *
 * A constant rather than the clock, because a fixture asserting on `createdAt`
 * must not start failing tomorrow. Chosen to be recognisably synthetic.
 */
export const FAKE_EPOCH = "2026-01-01T00:00:00.000Z";

/** FNV-1a. Small, dependency-free, and stable across both runtimes. */
export function seedFrom(...parts: unknown[]): number {
  const text = parts.map((part) => (typeof part === "string" ? part : stableJson(part))).join("|");
  let hash = 0x811c9dc5;

  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    // 32-bit FNV prime multiply, kept in range without BigInt.
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }

  return hash >>> 0;
}

/**
 * Key order must not change a seed.
 *
 * `JSON.stringify` preserves insertion order, so `{a,b}` and `{b,a}` would hash
 * differently and the "same inputs, same output" promise would hold only for
 * objects that happened to be built in the same order — which is exactly the
 * kind of almost-true that survives review and fails in a fixture months later.
 */
function stableJson(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value) ?? "null";
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;

  const entries = Object.entries(value as Record<string, unknown>)
    .filter(([, v]) => v !== undefined)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([k, v]) => `${JSON.stringify(k)}:${stableJson(v)}`);

  return `{${entries.join(",")}}`;
}

/** Build the deterministic helpers for one faked call. */
export function fakeValues(seed: number): FakeValues {
  // A tiny xorshift, advanced per call so successive helpers differ while the
  // whole sequence stays a pure function of the seed.
  let state = seed || 0x9e3779b9;
  const next = (): number => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;

    return state;
  };

  const hex = (length: number): string => {
    let out = "";
    while (out.length < length) out += next().toString(16).padStart(8, "0");

    return out.slice(0, length);
  };

  return {
    hex,
    id: (prefix: string) => `${prefix}_fake_${hex(12)}`,
    int: (min: number, max: number) => min + (next() % Math.max(1, max - min + 1)),
    pick: <T>(options: readonly T[]): T => options[next() % options.length] as T,
    timestamp: (offsetSeconds = 0) =>
      new Date(Date.parse(FAKE_EPOCH) + offsetSeconds * 1000).toISOString(),
  };
}

/** Build the request handed to a faker, with helpers already seeded. */
export function fakeRequest(
  service: string,
  operation: string,
  config: Record<string, unknown>,
  input?: unknown,
): FakeRequest {
  return { config, input, fake: fakeValues(seedFrom(service, operation, config)) };
}

/**
 * Deriving an idempotency key — and being honest when we cannot.
 *
 * ## The gap this works around
 *
 * A durable run RETRIES. For a writing connector that is only survivable if the
 * retry carries the same idempotency key the first attempt did, so the provider
 * returns the original result instead of creating a second charge, a second
 * refund, a second message.
 *
 * **Neither engine's execution context carries a run identity today.** The TS
 * `ctx` is `{ node, inputs, emit, abort }`; `FancyFlow\Runtime\ExecutionContext`
 * is the same four plus `depth`. There is no run key, no attempt number, nothing
 * a node can key on — checked against fancy-flow 0.45.0 and fancy-flow-php
 * 0.17.0 rather than assumed.
 *
 * So this reads the conventional places a host might put one, and returns
 * `null` when there is none.
 *
 * ## Why the two obvious fallbacks are both wrong
 *
 * - **The node id alone** is stable across retries — and also across different
 *   runs. Two legitimate payments for the same customer would share a key, and
 *   the second would be silently deduplicated into the first. A payment that
 *   never happened, reported as success.
 * - **A fresh random value** is unique per run — and also per attempt. A retry
 *   would create a second charge, which is the whole thing we are avoiding.
 *
 * Both are worse than no key. So with no run identity a connector sends none
 * and stays `unsafe-to-replay`, which pins it to a single attempt under the
 * per-node queue driver. Fewer retries, no double writes.
 */

/** Where a host may publish the run key. Checked in order. */
export function runKeyFrom(ctx: unknown): string | null {
  const bag = ctx as Record<string, any> | null;
  if (!bag) return null;

  const candidates = [
    bag.runKey,
    bag.run?.key,
    bag.runId,
    // A host with no engine support can seed it as an initial input, which the
    // engine merges into every node's inputs.
    bag.inputs?.__runKey,
  ];

  for (const candidate of candidates) {
    if (typeof candidate === "string" && candidate.trim() !== "") return candidate.trim();
  }

  return null;
}

/**
 * The idempotency key for one node in one run, or `null`.
 *
 * `null` is a legitimate answer and callers must treat it as one — passing it
 * through means "send no idempotency header", not "make something up".
 */
export function idempotencyKeyFor(ctx: unknown, nodeId: string): string | null {
  const run = runKeyFrom(ctx);

  return run === null ? null : `${run}:${nodeId}`;
}

/**
 * The warning a node emits when it is about to write without a key.
 *
 * Said out loud, at the moment it matters, because the failure it precedes is
 * invisible: the run succeeds, the retry succeeds, and there are two charges.
 */
export const NO_IDEMPOTENCY_KEY_WARNING =
  "no run identity available, so this write is being sent WITHOUT an idempotency key. " +
  "A retry would repeat the effect rather than recover from it — the node is marked " +
  "unsafe-to-replay, so a durable runner will give it one attempt. To enable safe retries, " +
  "seed a stable `__runKey` into the run's initial inputs.";

/**
 * The shared connector runtime, for hosts that EXECUTE on TypeScript.
 *
 * Vendored, not installed: this directory is copied into a consumer's project
 * alongside the first connector node they add, and every connector after that
 * reuses it. There is no package to require — that is the whole point of the
 * node marketplace, and a shared runtime that arrived as a dependency would
 * undo it.
 */

export * from "./client";
export * from "./connection";
export * from "./errors";
export * from "./faker";
export * from "./mode";
export * from "./trigger";
export * from "./webhook";

/**
 * Which copy of a provider a connector talks to — and who decides.
 *
 * Three modes, and the third is the one that makes this marketplace usable:
 *
 * | mode      | talks to                    | needs credentials | needs network |
 * |-----------|-----------------------------|-------------------|---------------|
 * | `live`    | the provider, for real      | yes               | yes           |
 * | `sandbox` | the provider's test estate  | yes (test ones)   | yes           |
 * | `fake`    | the node's own faker        | no                | no            |
 *
 * ## The environment is the DEFAULT, never the constraint
 *
 * A locally-hosted project defaults to sandbox. It is not *pinned* to sandbox:
 * an author who explicitly asks for `live` on their laptop gets `live`, because
 * the alternative — an environment that silently overrides a stated intention —
 * produces the worst outcome available here, which is a workflow that reports
 * success while having charged nobody. Equally, `sandbox` set explicitly stays
 * sandbox in production, which is how you stage a connector before cutting it
 * over.
 *
 * So: explicit beats the connection, the connection beats the environment.
 *
 * ## Why "fake" is a MODE and not a test double
 *
 * Every connector ships a faker (see `faker.ts`), and it is reachable the same
 * way in a test, in a demo and on a laptop with no credentials. Making it a
 * separate mechanism — a mock injected only under test — would mean the code
 * path a consumer develops against is not the one that runs, and the fixtures
 * would prove nothing about the executor.
 */

/** The three environments a connector node can run against. */
export type ConnectorMode = "fake" | "sandbox" | "live";

/** What a node's `mode` config field may say. `auto` means "let the rules decide". */
export type RequestedMode = ConnectorMode | "auto";

export const CONNECTOR_MODES: ConnectorMode[] = ["fake", "sandbox", "live"];

/**
 * How a provider exposes its test estate — the four shapes that actually exist.
 *
 * This is data, not per-node code, because getting it wrong is the difference
 * between hitting a test ledger and hitting a real one. Verified per provider in
 * `.ai/plans/fancy-flow-connector-nodes.md`; a node declares which of the four
 * it is and the core does the rest.
 *
 * - `credential` — same base URL, a test-scoped key selects the estate
 *   (Stripe's `sk_test_…`). The trap: pointing a live key at it works, so the
 *   only guard is the key itself.
 * - `base-url` — a different host entirely (PayPal's `api-m.sandbox.paypal.com`).
 * - `separate-account` — a distinct tenant you must create, often with its own
 *   login host (Salesforce sandbox orgs on `test.salesforce.com`).
 * - `none` — the provider has no test estate. `sandbox` is then not offered at
 *   all, and the node's honest choices are `fake` and `live`.
 */
export type SandboxKind = "credential" | "base-url" | "separate-account" | "none";

/** The host's view of where it is running. Kept tiny so it is trivial to fake. */
export type HostEnvironment = {
  /** True only in a real production deployment. Everything else is "local". */
  production: boolean;
};

export type ModeInputs = {
  /** What the node's config asked for. `undefined` / `"auto"` means "decide". */
  requested?: RequestedMode | null;
  /** A mode pinned on the CONNECTION, if the host pinned one. */
  connectionMode?: ConnectorMode | null;
  /** Whether the provider has a test estate at all. */
  sandbox: SandboxKind;
  /** Whether the connection actually carries credentials for the sandbox estate. */
  hasSandboxCredentials: boolean;
  environment: HostEnvironment;
};

/**
 * Resolve the mode a connector call runs in.
 *
 * Deliberately a pure function of stated facts, so both runtimes can be held to
 * the same table of cases and a host can unit-test its own wiring without a
 * network or a provider.
 */
export function resolveConnectorMode(inputs: ModeInputs): ConnectorMode {
  const { requested, connectionMode, sandbox, hasSandboxCredentials, environment } = inputs;

  // 1. An explicit ask wins everywhere. This is the rule that makes the
  //    environment a default rather than a cage.
  if (requested && requested !== "auto") {
    if (requested === "sandbox" && sandbox === "none") {
      throw new ConnectorModeError(
        'This connector\'s provider has no sandbox estate, so "sandbox" cannot be honoured. ' +
          'Use "fake" to develop without credentials, or "live" to talk to the provider.',
      );
    }

    return requested;
  }

  // 2. A mode pinned on the connection. One place per service, which is the
  //    whole reason connections exist as a separate thing.
  if (connectionMode) return connectionMode;

  // 3. Otherwise the environment decides.
  if (environment.production) return "live";

  // Local: prefer the provider's own test estate when it exists AND is wired.
  // Falling through to `fake` when it is not is what makes a freshly vendored
  // node runnable with no setup at all — the difference between a marketplace
  // you can try and one you can only read about.
  return sandbox !== "none" && hasSandboxCredentials ? "sandbox" : "fake";
}

/** Raised when a requested mode cannot be honoured. Never downgraded silently. */
export class ConnectorModeError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ConnectorModeError";
  }
}

/** True when the mode reaches the provider over the network. */
export function isRemote(mode: ConnectorMode): boolean {
  return mode !== "fake";
}

/**
 * How a connector trigger learns that something happened.
 *
 * **Not every provider pushes, and assuming webhooks is the single most common
 * way a connector catalogue ends up lying.** Google Drive and Microsoft Graph
 * want a *subscription* you must renew before it expires. Salesforce wants a
 * Pub/Sub or CometD stream. S3 wants an event notification routed to
 * infrastructure the consumer provisions. Reddit wants you to poll. Each of
 * those is a different obligation on the host, and a node that declared
 * "webhook" for all of them would install cleanly and then never fire.
 *
 * So a trigger declares its delivery mechanism, and the host can refuse to mount
 * one it has no machinery for — at author time, not at 3am.
 */

import type { ResolvedConnection } from "./connection";
import type { ConnectorFaker } from "./faker";
import { fakeRequest } from "./faker";
import type { HmacScheme, WebhookVerification } from "./webhook";
import { header, verifyHmac } from "./webhook";

/**
 * The delivery mechanisms that actually exist in the wild.
 *
 * - `webhook` — the provider POSTs to a URL you own. Verify the signature.
 * - `subscription` — a webhook that EXPIRES. Someone has to renew it, forever,
 *   and if nobody does the workflow stops firing without an error anywhere.
 *   Distinct from `webhook` precisely because that ongoing duty is invisible.
 * - `poll` — you ask, on a schedule, and track a cursor.
 * - `pubsub` — the provider publishes to a broker (Google Pub/Sub, Salesforce
 *   Pub/Sub API, SNS/SQS) that the consumer must provision.
 * - `stream` — a long-lived connection the host maintains (websocket, gRPC,
 *   SSE, CometD).
 */
export type DeliveryMechanism = "webhook" | "subscription" | "poll" | "pubsub" | "stream";

export type TriggerDescriptor = {
  service: string;
  operation: string;
  delivery: DeliveryMechanism;
  /**
   * What the host has to do before this fires, in one sentence, aimed at the
   * person who has to do it. Surfaced by the editor and by the MCP, because a
   * trigger whose setup is undocumented is a trigger that silently never fires.
   */
  setup: string;
  /** For `subscription`: how long the provider keeps it alive, in seconds. */
  subscriptionTtl?: number;
  /** For `webhook` / `subscription`: how a delivery is authenticated. */
  verification?: WebhookVerificationSpec;
  /** For `poll`: the provider's smallest sane interval, in seconds. */
  minPollSeconds?: number;
  /** A faked sample event, so the node is runnable before any of the above. */
  faker: ConnectorFaker;
};

export type WebhookVerificationSpec = {
  /** Header carrying the signature. */
  signatureHeader: string;
  /** Header carrying the timestamp, when the scheme signs one. */
  timestampHeader?: string;
  scheme: HmacScheme;
  /**
   * Some schemes pack the timestamp INTO the signature header
   * (Stripe: `t=…,v1=…`). Given the raw header value, return the parts.
   */
  parse?: (raw: string) => { signature?: string; timestamp?: string };
};

export type InboundDelivery = {
  /** The body EXACTLY as received. Not re-serialised. See `webhook.ts`. */
  raw: string;
  headers: Record<string, string | string[] | undefined>;
};

/**
 * Verify an inbound delivery against a trigger's declared scheme.
 *
 * A trigger with no `verification` REFUSES rather than accepts. That asymmetry
 * is the whole safety property: an unverifiable endpoint is a stranger's button
 * for starting workflows in your account, and defaulting to "allow" would make
 * every misconfiguration into an open door that looks shut.
 */
export async function verifyDelivery(
  trigger: TriggerDescriptor,
  delivery: InboundDelivery,
  secret: string | undefined,
  now?: number,
): Promise<WebhookVerification> {
  const spec = trigger.verification;

  if (!spec) {
    return {
      ok: false,
      reason: `${trigger.service}.${trigger.operation} declares no signature scheme, so a delivery cannot be trusted.`,
    };
  }

  const rawHeader = header(delivery.headers, spec.signatureHeader);
  const parsed = spec.parse && rawHeader ? spec.parse(rawHeader) : { signature: rawHeader };
  const timestamp = parsed.timestamp
    ?? (spec.timestampHeader ? header(delivery.headers, spec.timestampHeader) : undefined);

  return verifyHmac({
    raw: delivery.raw,
    signature: parsed.signature,
    secret,
    scheme: spec.scheme,
    timestamp,
    ...(now === undefined ? {} : { now }),
  });
}

/**
 * The event a trigger node publishes when it runs.
 *
 * Three sources, in order, and the third is why a connector trigger is usable
 * on day one:
 *
 * 1. A verified delivery the host injected on the `in` port.
 * 2. Nothing injected, but the connection is remote — that is a host wiring
 *    error, and it fails loudly rather than emitting a plausible blank.
 * 3. `fake` mode — the trigger emits its own sample event, so an author can
 *    press Run, see the real field names, and wire the downstream nodes against
 *    them before the provider has ever been contacted.
 */
export function triggerEvent(
  trigger: TriggerDescriptor,
  connection: ResolvedConnection,
  injected: unknown,
  config: Record<string, unknown>,
): unknown {
  if (hasDelivery(injected)) return injected;

  if (connection.mode === "fake") {
    return trigger.faker(
      trigger.operation,
      fakeRequest(trigger.service, trigger.operation, config),
    );
  }

  throw new Error(
    `${trigger.service}.${trigger.operation}: no event was delivered to this trigger. ` +
      `Its delivery mechanism is "${trigger.delivery}" — ${trigger.setup} ` +
      'Set the node\'s mode to "fake" to design against a sample event instead.',
  );
}

/**
 * Whether a value on the `in` port is an actual delivery.
 *
 * An EMPTY object or array counts as nothing delivered, and that is not
 * fussiness: a manually started run seeds `{}` on the trigger's input, so a
 * bare null check would hand the executor an empty envelope and call it an
 * event. Downstream every field would be `null`, the run would be green, and
 * nothing would say the trigger never fired.
 */
function hasDelivery(value: unknown): boolean {
  if (value === undefined || value === null) return false;
  if (Array.isArray(value)) return value.length > 0;
  if (typeof value === "object") return Object.keys(value as object).length > 0;

  return true;
}

/**
 * Verifying an inbound provider webhook.
 *
 * An unverified webhook endpoint is a public, unauthenticated way to start a
 * workflow in someone's account — which is to say, a way for a stranger to make
 * your app refund an order or post to your Slack. So verification is part of the
 * connector pattern rather than an exercise for the host: a trigger node that
 * cannot verify its deliveries must say so, and a host must not be able to mount
 * one by accident.
 *
 * ## The three things every provider's scheme actually needs
 *
 * Providers differ in header names and in what exactly gets signed, and almost
 * nothing else:
 *
 * 1. **The RAW body.** Signatures are computed over bytes. Re-serialising parsed
 *    JSON changes key order and whitespace and produces a signature mismatch
 *    that looks like a wrong secret. The host must pass the body it received.
 * 2. **A constant-time comparison.** `===` on a signature leaks, through timing,
 *    which prefix was right. That is a real forgery path, not a theoretical one.
 * 3. **A timestamp tolerance.** Without it a valid signature is valid forever,
 *    so anyone who ever saw one delivery can replay it whenever they like.
 *
 * WebCrypto rather than `node:crypto`, so the same file runs on Node, Bun, Deno
 * and an edge runtime. Node 22 is the suite's floor and has it globally.
 */

export type WebhookVerification =
  | { ok: true }
  | { ok: false; reason: string };

export type HmacScheme = {
  /** Hash to use. */
  algorithm: "SHA-256" | "SHA-1" | "SHA-512";
  /**
   * Build the exact string that gets signed. Providers differ here more than
   * anywhere else — Stripe signs `${timestamp}.${body}`, Slack signs
   * `v0:${timestamp}:${body}`, GitHub signs the body alone.
   */
  payload: (raw: string, timestamp?: string) => string;
  /** Seconds a delivery stays acceptable. */
  tolerance?: number;
  /** Encoding of the signature the provider sends. */
  encoding?: "hex" | "base64";
};

/**
 * Verify an HMAC-signed delivery.
 *
 * Returns a RESULT rather than throwing, and the failure carries a reason: a
 * host wants to log which check failed (stale? wrong secret? no header?) while
 * still answering the provider with an opaque 400.
 */
export async function verifyHmac(options: {
  raw: string;
  signature: string | undefined;
  secret: string | undefined;
  scheme: HmacScheme;
  timestamp?: string;
  /** Seconds since the epoch. Injected so tests are not clock-dependent. */
  now?: number;
}): Promise<WebhookVerification> {
  const { raw, signature, secret, scheme, timestamp } = options;

  if (!secret) {
    // Never "accept when unconfigured". An endpoint that verifies nothing
    // because nobody set a secret is strictly worse than one that is off: it
    // looks protected.
    return { ok: false, reason: "no signing secret configured for this trigger" };
  }
  if (!signature) return { ok: false, reason: "delivery carried no signature header" };

  if (scheme.tolerance !== undefined) {
    if (!timestamp) return { ok: false, reason: "delivery carried no timestamp header" };

    const sent = Number(timestamp);
    if (!Number.isFinite(sent)) return { ok: false, reason: "timestamp header is not a number" };

    const now = options.now ?? Math.floor(Date.now() / 1000);
    if (Math.abs(now - sent) > scheme.tolerance) {
      return { ok: false, reason: `delivery is outside the ${scheme.tolerance}s replay window` };
    }
  }

  const expected = await hmac(secret, scheme.payload(raw, timestamp), scheme.algorithm, scheme.encoding ?? "hex");

  return constantTimeEquals(expected, signature)
    ? { ok: true }
    : { ok: false, reason: "signature did not match" };
}

/** HMAC of `payload` under `secret`, hex or base64 encoded. */
export async function hmac(
  secret: string,
  payload: string,
  algorithm: HmacScheme["algorithm"],
  encoding: "hex" | "base64" = "hex",
): Promise<string> {
  const subtle = globalThis.crypto?.subtle;

  if (!subtle) {
    throw new Error(
      "WebCrypto is not available in this runtime, so webhook signatures cannot be verified. " +
        "Refusing to accept deliveries unverified.",
    );
  }

  const encoder = new TextEncoder();
  const key = await subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: algorithm },
    false,
    ["sign"],
  );
  const bytes = new Uint8Array(await subtle.sign("HMAC", key, encoder.encode(payload)));

  if (encoding === "base64") {
    let binary = "";
    bytes.forEach((byte) => {
      binary += String.fromCharCode(byte);
    });

    return btoa(binary);
  }

  return Array.from(bytes)
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Compare two strings without leaking where they diverge.
 *
 * The length check first is deliberate and safe: a signature's length is fixed
 * by its algorithm and is not a secret, so revealing a mismatch there tells an
 * attacker nothing they could not compute.
 */
export function constantTimeEquals(a: string, b: string): boolean {
  if (a.length !== b.length) return false;

  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);

  return diff === 0;
}

/**
 * Pull one header case-insensitively.
 *
 * Header case is not preserved consistently across proxies, frameworks and
 * runtimes; a connector that read `req.headers["Stripe-Signature"]` would work
 * behind one server and reject every delivery behind another.
 */
export function header(headers: Record<string, string | string[] | undefined>, name: string): string | undefined {
  const wanted = name.toLowerCase();

  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() !== wanted) continue;

    return Array.isArray(value) ? value[0] : value;
  }

  return undefined;
}

/**
 * Telegram's identity on the authoring surface.
 *
 * `ui/` lands on EVERY host, so it must import nothing from `js/`.
 */

import type { ConnectorMeta } from "../../_connector/ui/connector";

export const TELEGRAM_SERVICE = {
  service: "telegram",
  serviceTitle: "Telegram",
  domain: "messaging",
  // Telegram's test environment is a genuinely separate account: you create a
  // new account inside it and register a new bot there. The `/test` URL segment
  // is how you reach it, but the account is what makes it separate.
  sandbox: "separate-account",
} as const satisfies Pick<ConnectorMeta, "service" | "serviceTitle" | "domain" | "sandbox">;

export function telegramMeta(
  role: ConnectorMeta["role"],
  operation: string,
  docs: string,
): ConnectorMeta {
  return { ...TELEGRAM_SERVICE, role, operation, docs };
}

/**
 * Telegram — the exemplar for a trigger that is NOT a webhook, and for auth that
 * lives in the URL.
 *
 * Two things make this worth a place in the exemplar set:
 *
 * 1. **`getUpdates` long polling and `setWebhook` are mutually exclusive.** You
 *    choose one per bot, and the polling side needs a cursor the host has to
 *    persist. Nothing about that fits the "provider POSTs to you" template, and
 *    a catalogue that assumed webhooks everywhere would model this wrongly and
 *    then never fire.
 * 2. **The bot token is a PATH SEGMENT, not a header**, and the test environment
 *    is a further `/test` segment after it. So `authorize` rewrites the URL
 *    rather than adding a header, which is why the shared client hands it the
 *    resolved mode.
 *
 * There is no official Telegram SDK in any language, so calling the REST API
 * directly is the correct choice here rather than a shortcut — the alternative
 * would be a community wrapper, which is exactly the dependency the suite's
 * rules tell us not to take on a consumer's behalf.
 */

import type { ServiceDescriptor } from "../../_connector/js/client";
import type { ConnectorFaker } from "../../_connector/js/faker";

const API = "https://api.telegram.org";

/**
 * Telegram's faker.
 *
 * `getUpdates` returns `{ ok, result: [update, …] }`, and an update is a
 * discriminated envelope — `update_id` plus exactly one of `message`,
 * `edited_message`, `callback_query`, … The faker reproduces that envelope
 * rather than a flattened convenience shape, because the envelope is what an
 * author has to branch on when the real one arrives.
 */
export const telegramFaker: ConnectorFaker = (operation, request) => {
  const { fake, config } = request;

  if (operation !== "get_updates") {
    throw new Error(
      `telegram: no fake response is defined for "${operation}". Add one to telegramFaker before ` +
        "shipping a node that calls it.",
    );
  }

  const chatId = fake.int(100000000, 999999999);
  const text = String(config.sampleText ?? "hello from the faker");

  return {
    ok: true,
    result: [
      {
        update_id: fake.int(100000, 999999),
        message: {
          message_id: fake.int(1, 9999),
          date: 1767225600,
          text,
          chat: { id: chatId, type: "private", first_name: "Ada", username: "ada_example" },
          from: {
            id: chatId,
            is_bot: false,
            first_name: "Ada",
            username: "ada_example",
            language_code: "en",
          },
        },
      },
    ],
  };
};

export const TELEGRAM: ServiceDescriptor = {
  service: "telegram",
  title: "Telegram",
  // A genuinely separate account: you create one inside the test environment
  // and register a new bot there. The `/test` segment is how you reach it, but
  // the account is what makes it separate — and its flood limits are NOT
  // relaxed, so it is not a free-for-all.
  sandbox: "separate-account",
  baseUrls: { live: API, sandbox: API },
  requires: ["botToken"],
  /**
   * The token is a path segment, so this rewrites the URL instead of setting a
   * header — and the `/test` segment for the test environment goes AFTER the
   * token, which is why the mode is needed here.
   *
   * The token therefore ends up in the request URL, where access logs and error
   * reporters will happily record it. That is Telegram's design, not ours; a
   * host should keep it out of its own logging.
   */
  authorize: (credentials, request, mode) => {
    const url = new URL(request.url);
    const segment = mode === "sandbox" ? `/bot${credentials.botToken}/test` : `/bot${credentials.botToken}`;
    url.pathname = `${segment}${url.pathname}`;
    request.url = url.toString();
  },
  faker: telegramFaker,
};

/**
 * Optional effect classes, for when you'd rather not write your own.
 *
 * Import it, then point a `ui_effect` node at `add-class` with one of these and
 * a `durationMs`. Nothing in the node depends on this file — it is a starting
 * set, not an API, and your own class beats any of them.
 *
 *   import "@/components/fancy/flow-nodes/ui-effect/ui/effects.css";
 *
 * Every animation respects `prefers-reduced-motion`: the colour change still
 * lands, the movement doesn't.
 */

.ff-fx-glow {
  animation: ff-fx-glow 1.2s ease-in-out infinite;
}

.ff-fx-pulse {
  animation: ff-fx-pulse 900ms ease-in-out infinite;
}

.ff-fx-flash {
  animation: ff-fx-flash 600ms ease-out 1;
}

.ff-fx-shake {
  animation: ff-fx-shake 420ms cubic-bezier(0.36, 0.07, 0.19, 0.97) 1;
}

/* An inner glow, so a card can light up without changing its footprint. */
@keyframes ff-fx-glow {
  0%,
  100% {
    box-shadow: inset 0 0 0 1px var(--ff-fx-color, #a855f7), inset 0 0 12px -4px var(--ff-fx-color, #a855f7);
  }
  50% {
    box-shadow: inset 0 0 0 1px var(--ff-fx-color, #a855f7), inset 0 0 26px -2px var(--ff-fx-color, #a855f7);
  }
}

@keyframes ff-fx-pulse {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.02);
  }
}

@keyframes ff-fx-flash {
  from {
    background-color: var(--ff-fx-color, #a855f7);
  }
  to {
    background-color: transparent;
  }
}

@keyframes ff-fx-shake {
  10%,
  90% {
    transform: translateX(-1px);
  }
  20%,
  80% {
    transform: translateX(2px);
  }
  30%,
  50%,
  70% {
    transform: translateX(-4px);
  }
  40%,
  60% {
    transform: translateX(4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ff-fx-glow,
  .ff-fx-pulse,
  .ff-fx-shake {
    animation: none;
  }

  /* Keep the signal, drop the motion — a highlight that never appears is a
     failed notification, not an accessibility win. */
  .ff-fx-glow,
  .ff-fx-pulse {
    box-shadow: inset 0 0 0 2px var(--ff-fx-color, #a855f7);
  }

  .ff-fx-flash {
    animation-duration: 1ms;
    background-color: var(--ff-fx-color, #a855f7);
  }
}

import type { UiEffect, UiEffectHost } from "./types";

/**
 * The host most apps want: apply the effect to the real DOM.
 *
 * Handle resolution, in order:
 *
 *  1. `page` / `:root` / `document` → `document.documentElement`. This is the
 *     theme target — `set-var` on the root is how a whole page changes at once.
 *  2. `[data-fancy-id="<handle>"]` — the stable handle a Fancy surface publishes.
 *  3. The string as a CSS selector, last. Useful outside a Fancy surface, but a
 *     host with a real handle registry should pass `resolve` and never get here.
 *
 * A target that resolves to nothing **throws**. It would be easy to no-op, and
 * that is exactly the trap: the run would report success having styled nothing.
 */
export function createDomUiEffectHost(options: DomUiEffectHostOptions = {}): UiEffectHost {
  const { root, resolve } = options;

  const doc = () => root ?? (typeof document !== "undefined" ? document : null);

  const find = (handle: string): HTMLElement => {
    const d = doc();
    if (!d) throw new Error("ui_effect: no document — register a host for non-browser runs.");

    if (handle === "page" || handle === ":root" || handle === "document") {
      return d.documentElement as HTMLElement;
    }

    const custom = resolve?.(handle);
    if (custom) return custom;

    const byHandle = d.querySelector<HTMLElement>(`[data-fancy-id="${cssEscape(handle)}"]`);
    if (byHandle) return byHandle;

    // Selector fallback. Wrapped because an author-supplied string that isn't
    // valid CSS throws a DOMException, and "SyntaxError" tells them nothing.
    let bySelector: HTMLElement | null = null;
    try {
      bySelector = d.querySelector<HTMLElement>(handle);
    } catch {
      throw new Error(`ui_effect: target "${handle}" is neither a known handle nor a valid selector.`);
    }
    if (bySelector) return bySelector;

    throw new Error(`ui_effect: nothing matches target "${handle}".`);
  };

  return {
    resolve: (handle) => find(handle),
    apply(effect: UiEffect) {
      const el = find(effect.target);
      const undo = applyOnce(el, effect);

      // A duration is what turns four plain ops into pulses and flashes: apply,
      // then put it back. setTimeout is deliberate — the node does not stay
      // running, so the effect outlives the run that started it.
      if (effect.durationMs && effect.durationMs > 0) {
        setTimeout(undo, effect.durationMs);
      }
    },
  };
}

export type DomUiEffectHostOptions = {
  /** Document to operate on. Defaults to the ambient one. */
  root?: Document;
  /** A real handle registry, consulted before `[data-fancy-id]`. */
  resolve?: (handle: string) => HTMLElement | null | undefined;
};

/** Apply one effect and return the function that undoes it. */
function applyOnce(el: HTMLElement, effect: UiEffect): () => void {
  const classes = splitClasses(effect.value);

  switch (effect.op) {
    case "add-class": {
      // Only revert what WE added — reverting a class the page already had
      // would leave the page in a state no one asked for.
      const added = classes.filter((c) => !el.classList.contains(c));
      el.classList.add(...classes);

      return () => el.classList.remove(...added);
    }

    case "remove-class": {
      const removed = classes.filter((c) => el.classList.contains(c));
      el.classList.remove(...classes);

      return () => el.classList.add(...removed);
    }

    case "toggle-class": {
      classes.forEach((c) => el.classList.toggle(c));

      return () => classes.forEach((c) => el.classList.toggle(c));
    }

    case "replace-class": {
      const from = splitClasses(effect.name ?? "");
      const had = from.filter((c) => el.classList.contains(c));
      el.classList.remove(...from);
      el.classList.add(...classes);

      return () => {
        el.classList.remove(...classes);
        el.classList.add(...had);
      };
    }

    case "set-var": {
      const name = requireName(effect, "set-var needs `name` — the custom property, e.g. --fa-accent.");
      const previous = el.style.getPropertyValue(name);
      el.style.setProperty(name, effect.value);

      return () => {
        if (previous) el.style.setProperty(name, previous);
        else el.style.removeProperty(name);
      };
    }

    case "set-style": {
      const name = requireName(effect, "set-style needs `name` — the CSS property, e.g. box-shadow.");
      const previous = el.style.getPropertyValue(name);
      el.style.setProperty(name, effect.value);

      return () => {
        if (previous) el.style.setProperty(name, previous);
        else el.style.removeProperty(name);
      };
    }

    default:
      throw new Error(`ui_effect: unknown op "${String((effect as UiEffect).op)}".`);
  }
}

function requireName(effect: UiEffect, message: string): string {
  const name = (effect.name ?? "").trim();
  if (!name) throw new Error(`ui_effect: ${message}`);

  return name;
}

function splitClasses(value: string): string[] {
  return value.split(/\s+/).filter(Boolean);
}

/** Minimal attribute-value escape — CSS.escape isn't everywhere, and this is one quote. */
function cssEscape(value: string): string {
  return value.replace(/["\\]/g, "\\$&");
}

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";
import { createDomUiEffectHost } from "./dom";
import { getUiEffectHost } from "./host";
import type { UiEffect, UiEffectOp } from "./types";

const OPS: readonly UiEffectOp[] = [
  "add-class",
  "remove-class",
  "toggle-class",
  "replace-class",
  "set-var",
  "set-style",
];

/**
 * Resolve the node's config into a {@link UiEffect} and hand it to the host.
 *
 * ## Why this fails instead of no-opping
 *
 * The tempting implementation checks for a DOM, shrugs when there isn't one,
 * and returns. Then a workflow that "pulses the card" runs on a queue worker,
 * styles nothing, and reports `ok: true`. Nothing throws, nothing is logged,
 * and the run list says success — the same silent-success failure trigger
 * cohorts exist to prevent. So: no host and no document is an ERROR.
 *
 * A browser gets the DOM host for free, because making the common case need
 * zero setup is worth more than the symmetry of always requiring registration.
 */
export const uiEffectExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;

  const op = String(config.op ?? "add-class") as UiEffectOp;
  if (!OPS.includes(op)) {
    throw new Error(`ui_effect: unknown op "${op}". Expected one of ${OPS.join(", ")}.`);
  }

  const effect: UiEffect = {
    target: String(config.target ?? "page").trim() || "page",
    op,
    value: String(config.value ?? ""),
    // Always a string, never absent. An omitted `name` and an empty one mean
    // the same thing to every op, and a payload whose shape depends on which
    // fields the author happened to fill in is one a consumer has to guard.
    name: String(config.name ?? ""),
    durationMs: Number(config.durationMs ?? 0) || 0,
  };

  if (!effect.value && op !== "remove-class") {
    throw new Error(`ui_effect: "${op}" needs a value.`);
  }

  // Config validation belongs to the node, not the host: caught here it is the
  // same error on every runtime and every host, rather than whatever the DOM
  // happens to say. (The DOM host re-checks anyway — cheap, and it is reachable
  // directly.)
  if ((op === "set-var" || op === "set-style" || op === "replace-class") && !effect.name?.trim()) {
    throw new Error(
      op === "replace-class"
        ? 'ui_effect: "replace-class" needs `name` — the class being replaced.'
        : `ui_effect: "${op}" needs \`name\` — the ${op === "set-var" ? "custom property, e.g. --fa-accent" : "CSS property, e.g. box-shadow"}.`,
    );
  }

  const host = getUiEffectHost() ?? (typeof document !== "undefined" ? createDomUiEffectHost() : null);
  if (!host) {
    throw new Error(
      "ui_effect: no UI host. In a browser this works out of the box; elsewhere call " +
        "registerUiEffectHost() with something that can reach the surface — typically a relay to the attached browser.",
    );
  }

  ctx.emit({
    type: "log",
    level: "info",
    nodeId: ctx.node.id,
    message: `${op} on "${effect.target}"${effect.durationMs ? ` for ${effect.durationMs}ms` : ""}`,
    detail: effect,
  });

  await host.apply(effect);

  // Pass the upstream payload through alongside the effect, so this node drops
  // into the middle of a chain without severing it.
  const incoming = (ctx.inputs as any)?.in;

  return { ...(isRecord(incoming) ? incoming : {}), uiEffect: effect, applied: true };
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import type { UiEffectHost } from "./types";

/**
 * The registered host, if any.
 *
 * A module-level singleton, matching how fancy-flow core registers its own
 * capabilities (`registerLlmClient`). A package cannot extend core's capability
 * union, so it owns its own — same shape, same explicitness, same one-line
 * registration.
 */
let host: UiEffectHost | null = null;

/**
 * Install the host that carries out UI effects. Returns an unregister function.
 *
 * ```ts
 * // A browser app — one line, and every ui_effect node works.
 * registerUiEffectHost(createDomUiEffectHost());
 *
 * // A queue worker with a browser attached over a relay.
 * registerUiEffectHost({ apply: (effect) => relay.send("ui_effect", effect) });
 * ```
 */
export function registerUiEffectHost(next: UiEffectHost): () => void {
  host = next;

  return () => {
    if (host === next) host = null;
  };
}

export function getUiEffectHost(): UiEffectHost | null {
  return host;
}

import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { uiEffectKind } from "../ui/kind";
import { uiEffectExecutor } from "./executor";

/**
 * The kind with its TypeScript executor attached — for hosts that EXECUTE on TS.
 *
 * The surface in `ui/kind.ts` deliberately carries no executor: the editor is
 * React on every host, so a PHP project vendors `ui/` and never `js/`. When the
 * two were one file the import dangled on exactly those hosts and the editor
 * build failed — a break that only appeared off the runtime that authored it.
 */
export const uiEffectRunnableKind: NodeKindDefinition = {
  ...uiEffectKind,
  executor: uiEffectExecutor,
};

/**
 * What a `ui_effect` node asks a host to do, and the seam that does it.
 *
 * The node never touches the DOM. It resolves an *intent* — target, operation,
 * value — and hands it to a host-registered {@link UiEffectHost}. That is the
 * same "shuttle, not an engine" arrangement fancy-flow uses for LLM clients,
 * and it is what lets the identical graph run in a browser (apply directly), on
 * a queue worker (forward over a relay to whichever browser is attached), or in
 * a test (record and assert).
 */

/** Everything a host needs to carry out one effect. */
export type UiEffect = {
  /**
   * What to affect: a **stable handle** the host published, or `page` for the
   * document root.
   *
   * Handles, not selectors, are the contract — the Fancy component contract is
   * explicit that agents never guess DOM. The bundled DOM host resolves a
   * handle to `[data-fancy-id="…"]` first and only falls back to treating the
   * string as a selector, so a host with a real handle registry stays authoritative.
   */
  target: string;
  op: UiEffectOp;
  /**
   * The class list, CSS value, or custom-property value — what `op` is setting.
   * Unused by `remove-class` when `name` already identifies the class.
   */
  value: string;
  /**
   * The second identifier some ops need: the custom property for `set-var`
   * (`--fa-accent`), the CSS property for `set-style` (`box-shadow`), or the
   * class being replaced by `replace-class`.
   */
  name?: string;
  /**
   * Revert this effect after N milliseconds. `0` (the default) means permanent.
   *
   * This is what makes a pulse or a flash fall out of the same four ops rather
   * than needing their own: add a class, revert it in 1200ms.
   */
  durationMs?: number;
};

export type UiEffectOp =
  /** Add class(es) in `value`. Idempotent. */
  | "add-class"
  /** Remove class(es) in `value`. Idempotent. */
  | "remove-class"
  /** Toggle class(es) in `value`. **Not** idempotent — see the README on retries. */
  | "toggle-class"
  /** Swap `name` for `value`. Idempotent once applied. */
  | "replace-class"
  /** Set custom property `name` to `value` (theme changes live here). */
  | "set-var"
  /** Set inline style property `name` to `value`. */
  | "set-style";

/**
 * The host capability.
 *
 * Deliberately one method. A narrow contract is one a host satisfies in a few
 * lines over anything — the DOM, a relay frame, a React store, a test spy — and
 * it keeps the node honest about what it is: a message, not a mutation.
 */
export type UiEffectHost = {
  /**
   * Carry out the effect.
   *
   * Throw if it cannot be carried out. Do NOT swallow a missing target: a run
   * that reports success having styled nothing is the failure this node's whole
   * design is arranged against.
   */
  apply: (effect: UiEffect) => void | Promise<void>;
  /**
   * Resolve a stable handle to whatever this host styles. Optional — a host
   * with its own registry implements it; the DOM host's default is
   * `[data-fancy-id]` then a selector fallback.
   */
  resolve?: (handle: string) => unknown;
};
